static SRWLOCK g_lock = SRWLOCK_INIT;
static SRWLOCK g_refresh_lock = SRWLOCK_INIT;
/* The runtime lock taken exclusively: counted while the preparation worker holds it (prepare_worker.h). */
#define PR_LOCK_EXCLUSIVE() (AcquireSRWLockExclusive(&g_lock), sh_prepare_on_worker() ? (void)InterlockedIncrement(&g_sh_prepare.locks_held) : (void)0)
#define PR_UNLOCK_EXCLUSIVE() (sh_prepare_on_worker() ? (void)InterlockedDecrement(&g_sh_prepare.locks_held) : (void)0, ReleaseSRWLockExclusive(&g_lock))
/* g_refresh_lock is not recursive, and an SRW lock waits forever for its own
 * owner. Every acquisition passes through these so a path re-entered on the
 * holding thread can see the hold instead of waiting: a compile under
 * pr_prepare_map evaluates native declarations, that parse reaches the
 * resource-graph instance hooks, and their origin hold promotes
 * (sh_package_runtime_resource_promote), which took this lock exclusively
 * (the 2026-10-22 mixed2 browse-load freeze). The depth is per thread and
 * counts either mode; a re-entry in a test build is a fault, not a wait. */
static __declspec(thread) int t_refresh_depth;
#ifdef SH_PACKAGE_RUNTIME_TESTING
static volatile LONG g_test_refresh_reentries;
long sh_package_runtime_test_refresh_reentries(void)
{ return InterlockedCompareExchange(&g_test_refresh_reentries, 0, 0); }
#endif
/* R-398 perf16: the preparation worker's holds, so a call the engine thread runs on its behalf (prepare_worker.h)
 * borrows them instead of waiting on the worker, which waits on that call. */
static volatile LONG g_worker_refresh_depth;
static __declspec(thread) int t_refresh_borrowed;
static void pr_refresh_acquire(int exclusive)
{
    if (sh_prepare_serving() && InterlockedCompareExchange(&g_worker_refresh_depth, 0, 0)) {
        t_refresh_borrowed++; t_refresh_depth++; return;
    }
#ifdef SH_PACKAGE_RUNTIME_TESTING
    if (t_refresh_depth) {
        InterlockedIncrement(&g_test_refresh_reentries);
        fprintf(stderr, "package runtime: g_refresh_lock acquired again on its holding thread (depth %d); "
            "a product build would wait forever here\n", t_refresh_depth);
        abort();
    }
#endif
    if (!sh_prepare_running() || sh_prepare_on_worker()) {
        if (exclusive) AcquireSRWLockExclusive(&g_refresh_lock); else AcquireSRWLockShared(&g_refresh_lock);
    } else {
        /* The engine thread while a preparation runs: the holder may be waiting on one of its calls. */
        while (!(exclusive ? TryAcquireSRWLockExclusive(&g_refresh_lock) : TryAcquireSRWLockShared(&g_refresh_lock)))
            sh_prepare_service(5);
    }
    t_refresh_depth++;
    if (sh_prepare_on_worker()) InterlockedIncrement(&g_worker_refresh_depth);
}
static void pr_refresh_release(int exclusive)
{
    if (t_refresh_borrowed) { t_refresh_borrowed--; t_refresh_depth--; return; }
    t_refresh_depth--;
    if (sh_prepare_on_worker()) InterlockedDecrement(&g_worker_refresh_depth);
    if (exclusive) ReleaseSRWLockExclusive(&g_refresh_lock); else ReleaseSRWLockShared(&g_refresh_lock);
}
/* 1 with the lock taken exclusively; 0 when another thread holds it, or this one does. */
static int pr_refresh_try(void)
{
    if (t_refresh_depth || !TryAcquireSRWLockExclusive(&g_refresh_lock)) return 0;
    t_refresh_depth++;
    if (sh_prepare_on_worker()) InterlockedIncrement(&g_worker_refresh_depth);
    return 1;
}
/* Whether this thread already holds g_refresh_lock (either mode): a public
 * entry reached from inside a compile or activation must not take it again. */
static int pr_refresh_held(void)
{ return t_refresh_depth > 0 || (sh_prepare_serving() && InterlockedCompareExchange(&g_worker_refresh_depth, 0, 0) > 0); }
