/* An installed package a library rejected on its own bytes alone, with the
 * exact source tree it read (see pr_exclusions_apply). */
typedef struct pr_exclusion {
    char *name;             /* sh_package.name */
    unsigned char tree[32]; /* its source fingerprint when judged */
    char *line;             /* the report line it produced */
} pr_exclusion;
typedef struct pr_movie_record pr_movie_record;
/* Ownership changes are serialized by g_refresh_lock. Published pointers and
 * aliases change together under g_lock. A view borrows its catalog through a
 * retained library parent; every compilation/inventory remains independently
 * owned. Readers hold g_lock, not an untracked provider pointer. */
/* An unchanged original an increment's link bound and then left native
 * (pr_prune_native): its path, exact bytes and the identities bound to it. */
typedef struct pr_native_witness {
    char *path;
    sh_package_file_identity identity;
    int identified; /* 0: bytes unavailable here, so never composed */
    sh_package_native_identity *names;
    size_t name_count;
} pr_native_witness;
static void pr_native_witnesses_free(pr_native_witness *witnesses, size_t count)
{
    for (size_t i = 0; witnesses && i < count; i++) {
        free(witnesses[i].path);
        for (size_t n = 0; n < witnesses[i].name_count; n++) {
            free((void *)witnesses[i].names[n].type); free((void *)witnesses[i].names[n].name);
        }
        free(witnesses[i].names);
    }
    free(witnesses);
}
/* An authored input of a row a library left native (pr_prune_native): the
 * compiled bytes equal the installed SnapMap original, so the game serves them
 * itself. Path and file identity let sh_package_runtime_inputs account each
 * such input after its row is gone. Sorted by path, length, then digest. */
typedef struct pr_unchanged {
    char *path;
    uint64_t length;
    unsigned char digest[32];
} pr_unchanged;
static void pr_unchanged_free(pr_unchanged *rows, size_t count)
{
    for (size_t i = 0; rows && i < count; i++) free(rows[i].path);
    free(rows);
}
static int pr_unchanged_order(const void *a, const void *b)
{
    const pr_unchanged *x = a, *y = b;
    int order = strcmp(x->path, y->path);
    if (order) return order;
    if (x->length != y->length) return x->length < y->length ? -1 : 1;
    return memcmp(x->digest, y->digest, 32);
}
/* An authored shader input the library's source link accounted without
 * publishing it (sh_package_unpublished_shader), keyed by its package's inventoried
 * tree and exact file so a view that joins packages keeps it without index
 * remapping. A dormant pair keeps the binary its checksum matched: a file of
 * the same package, or the installed original at that path (pair_original).
 * Sorted by owner, relative path, length, then digest. */
typedef struct pr_shader_input {
    unsigned char owner[32];
    char *relative;
    uint64_t length;
    unsigned char digest[32];
    int reason, renderer;
    char *pair;
    int pair_original;
    uint64_t pair_length;
    unsigned char pair_digest[32];
    uint32_t checksum;
} pr_shader_input;
static void pr_shader_inputs_free(pr_shader_input *rows, size_t count)
{
    for (size_t i = 0; rows && i < count; i++) { free(rows[i].relative); free(rows[i].pair); }
    free(rows);
}
static int pr_shader_input_order(const void *a, const void *b)
{
    const pr_shader_input *x = a, *y = b;
    int order = memcmp(x->owner, y->owner, 32);
    if (order) return order;
    if ((order = strcmp(x->relative, y->relative)) != 0) return order;
    if (x->length != y->length) return x->length < y->length ? -1 : 1;
    return memcmp(x->digest, y->digest, 32);
}
/* An authored file the library composed with other packages' contributions
 * (sh_package_composed_input), keyed like pr_shader_input by its package's
 * inventoried tree and exact file; peers names the other contributing packages
 * and their files for the report. Sorted by owner, relative path, length, then
 * digest. */
typedef struct pr_composed_input {
    unsigned char owner[32];
    char *relative;
    uint64_t length;
    unsigned char digest[32];
    char *peers;
} pr_composed_input;
static void pr_composed_inputs_free(pr_composed_input *rows, size_t count)
{
    for (size_t i = 0; rows && i < count; i++) { free(rows[i].relative); free(rows[i].peers); }
    free(rows);
}
static int pr_composed_input_order(const void *a, const void *b)
{
    const pr_composed_input *x = a, *y = b;
    int order = memcmp(x->owner, y->owner, 32);
    if (order) return order;
    if ((order = strcmp(x->relative, y->relative)) != 0) return order;
    if (x->length != y->length) return x->length < y->length ? -1 : 1;
    return memcmp(x->digest, y->digest, 32);
}
typedef struct pr_provider {
    pr_native_witness *native_witnesses; /* An increment's (pr_increment_view). */
    size_t native_witness_count;
    sh_package_sources *sources;
    /* Original metadata for retained serving-only owners. Never author paths
     * to reread: resources and complete bundles already own immutable bytes. */
    sh_package_sources *authored_sources;
    sh_package_bundle **bundles; /* Indexed by this inventory's exact owner. */
    size_t bundle_count;
    sh_package_compilation *compiled;
    sh_resource_catalog *catalog;
    sh_audio_originals *audio_originals;
    sh_package_native_assets *native_assets;
    sh_virtual_material_view *virtual_materials;
    sh_package_consumers *consumers;
    /* AI state-machine webs it binds and declarations it owns (package_fsm.h). */
    sh_package_fsm_webs *fsm_webs;
    sh_package_audio_program *audio;
    /* Views retain every root provider whose audio program they serve: the
     * current map, the library and retained occurrence/selector owners. The
     * native audio layer retains these same owners until consumers retire. */
    struct pr_provider **audio_sources;
    size_t audio_source_count;
    /* Per audio source: 1 when it only serves consumers (a rejected
     * candidate's movies) and has no audio policy authority. */
    unsigned char *audio_serving;
    /* An audio root becomes accepted when a provider holding it with
     * authority is accepted (pr_audio_accept). Only then does a later view
     * that retains it for its consumers give it policy authority. */
    volatile LONG audio_accepted;
#ifndef SH_PACKAGE_RUNTIME_TESTING
    sh_strids_reservation *strings;
    sh_audio_id_lease *audio_ids;
#endif
#ifdef PR_NATIVE_SPAWN
    sh_spawn_keys_program *spawn_program;
#endif
    uint32_t *unmodified_types;
    size_t unmodified_count;
    uint32_t *exact_modifier_types;
    size_t exact_modifier_count;
    sh_package_provenance bindings;
    sh_package_provenance policy_uses; /* explicit active document, not resource supplier union */
    sh_package_provenance historical_bindings; /* Original names before private historical linking. */
    sh_package_references required_paths;
    sh_package_file_identity required_map;
    volatile LONG requirements_known;
    /* R-255: a local document's map plan provider holding only generated
     * layers; its requirements resolve in the library it is bound against. */
    int generated_only;
    /* The pool settings the kept inspection judged construction under
     * (sh_package_source_graph_report) and where they are read. */
    int pool_settings_state;
    sh_native_pool_settings pool_settings;
    const sh_native_class_source *pool_source;
    struct pr_provider *parent;
    char *data_root;
    char *rejections;
    char *unserved; /* Valid installed packages this build cannot link yet. */
    char *coverage; /* Accounted missing product coverage; packages still served. */
    pr_exclusion *exclusions; /* Rejections decided on a package's own bytes alone. */
    size_t exclusion_count;
    pr_unchanged *unchanged; /* Authored inputs of rows left native; views keep their bases'. */
    size_t unchanged_count;
    int unchanged_lost;      /* The records could not be retained (accounting only). */
    pr_shader_input *shader_inputs; /* Unpublished shader inputs its link accounted; views keep their bases'. */
    size_t shader_input_count;
    int shader_inputs_lost;  /* Some could not be retained (accounting only). */
    pr_composed_input *composed_inputs; /* Contributions its library composed with peers'; views keep their bases'. */
    size_t composed_input_count;
    int composed_inputs_lost; /* Some could not be retained (accounting only). */
    /* The installed scan it was prepared from (pr_scan_identity). */
    unsigned char scan_identity[32];
    int scan_known;
    /* Loaded from a warm record of a subset of the installed packages (the
     * rest were added since it was written): the start increments it. */
    size_t warm_subset_added;
    sh_package_key_groups *key_groups; /* Group codes its relocated values use. */
    /* Identity provenance (R-397): per compiled resource (same order, prov_count == compiled->resource_count when
     * set), every package of sources whose content entered that row's identity or bytes. NULL when unknown (an
     * older warm record, a view): a removal or a composing addition then compiles the whole library. */
    sh_package_owners *prov;
    size_t prov_count;
    pr_movie_record *movies; /* Immutable plans, reserved before publication. */
    size_t movie_count;
    struct pr_provider *movie_next; /* One registry reference per provider. */
    /* R-309 in-place image recovery. A root library provider holds its compile's need (the
     * library's recovered_images) and whether a scope declares the image gate open. A provider
     * that is published holds the effective set (pr_recovery_settle): the need of its root plus,
     * while that root still declares the gate, everything the previous publication recovered,
     * because those objects stay loaded under the open gate until it closes. Sorted, unique. */
    char **recovery_need;
    size_t recovery_need_count;
    int image_gate;
    char **recovered;
    size_t recovered_count;
    /* Set when the effective set was fixed from another publication (a movie rollback view
     * restores its previous provider's set) instead of being settled from its root. */
    int recovery_fixed;
    /* A start compile's warm publication context (journal, key, replay logs) until its publication commits
     * and is written, or the provider is released (R-344 stage B). */
    pr_warm_pending *warm;
    /* Fixed-name rows this view keeps with a departed map's meaning while
     * that map's native consumers hold them (pr_view_retained_link). */
    size_t deferred_count;
    size_t deferred_explicit; /* of them, rows this map binds itself (its switch waits for the consumers) */
    char **deferred_paths;    /* deferred_count engine paths; admission of an installation skips them */
    unsigned long long deferred_digest;
    char deferred_first[256];
    volatile LONG references;
} pr_provider;
