static void pr_departed_map_release(const char *why)
{
    if (g_departed_map.provider && why) {
        char line[256];
        snprintf(line, sizeof(line), "package library: departed map compile released: %s", why);
        backend_log(line);
    }
    pr_release(g_departed_map.provider); pr_release(g_departed_map.library);
    memset(&g_departed_map, 0, sizeof(g_departed_map));
}
