#ifdef SH_PACKAGE_RUNTIME_TESTING
/* SMP_WARM_ORACLE=1 (testing builds): every recordable start compile is reloaded at once from its encoded
 * record, from copies of the same preamble, and the rebuilt publication must equal the compiled one field for
 * field (pr_publication_text, exact bytes). A miss under unchanged inputs, a difference, or a record the writer
 * would refuse ends the process, so a whole suite run is a differential of the warm path. */
typedef struct pr_warm_preamble {
    sh_package_sources *sources, *inventory;
    pr_left_out left_out;
    char *rejections;
    pr_exclusion *exclusions; size_t exclusion_count;
} pr_warm_preamble;
static int pr_warm_env_on(const char *name)
{
    char *value = NULL; size_t length = 0;
    int on = !_dupenv_s(&value, &length, name) && value && !strcmp(value, "1");
    free(value); return on;
}
static int pr_warm_oracle_enabled(void) { return pr_warm_env_on("SMP_WARM_ORACLE"); }
static void pr_warm_preamble_free(pr_warm_preamble *p)
{
    sh_package_sources_free(p->sources); sh_package_sources_free(p->inventory); sh_package_sources_free(p->left_out.units);
    free(p->rejections); pr_exclusions_free(p->exclusions, p->exclusion_count); memset(p, 0, sizeof(*p));
}
static int pr_warm_preamble_copy(pr_warm_preamble *p, const sh_package_sources *sources, const sh_package_sources *inventory,
    const pr_left_out *left_out, const char *rejections, const pr_exclusion *exclusions, size_t exclusion_count)
{
    sh_package_sources empty = {0};
    char error[256];
    memset(p, 0, sizeof(*p));
    p->sources = sh_package_sources_join(sources, &empty, error, sizeof(error));
    if (inventory) p->inventory = sh_package_sources_join(inventory, &empty, error, sizeof(error));
    if (left_out->units) p->left_out.units = sh_package_sources_join(left_out->units, &empty, error, sizeof(error));
    p->left_out.lost = left_out->lost;
    if (rejections) p->rejections = _strdup(rejections);
    int ok = p->sources && (!inventory || p->inventory) && (!left_out->units || p->left_out.units) && (!rejections || p->rejections);
    for (size_t i = 0; ok && i < exclusion_count; i++)
        ok = pr_exclusion_add(&p->exclusions, &p->exclusion_count, exclusions[i].name, exclusions[i].tree, exclusions[i].line);
    if (!ok) pr_warm_preamble_free(p);
    return ok;
}
static void pr_warm_oracle_fail(const char *what, const char *cold, size_t cold_length, const char *warm, size_t warm_length)
{
    char *trace = NULL; size_t length = 0;
    char line[600];
    snprintf(line, sizeof(line), "warm oracle FAILED: %s", what);
    pr_warm_note(line, -1);
    fprintf(stderr, "%s\n", line);
    if (!_dupenv_s(&trace, &length, "SMP_WARM_TRACE") && trace && *trace) {
        char path[1100]; FILE *file = NULL;
        for (int k = 0; k < 2; k++) {
            snprintf(path, sizeof(path), "%s.%s.txt", trace, k ? "warm" : "cold");
            if (!fopen_s(&file, path, "wb") && file) {
                const char *text = k ? warm : cold; size_t n = k ? warm_length : cold_length;
                if (text) fwrite(text, 1, n, file);
                fclose(file);
            }
        }
    }
    free(trace);
    abort();
}
typedef struct pr_warm_reload {
    pr_warm_preamble copy;
    pr_warm_inputs in;
    sh_package_compilation *compiled;
    sh_package_library isolated;
    pr_unchanged *unchanged; size_t unchanged_count; int unchanged_lost;
    pr_shader_input *shader_inputs; size_t shader_input_count; int shader_inputs_lost;
    pr_composed_input *composed_inputs; size_t composed_input_count; int composed_inputs_lost;
    char *unserved;
} pr_warm_reload;
static void pr_warm_reload_free(pr_warm_reload *x)
{
    x->isolated.compiled = x->compiled;
    sh_package_library_free(&x->isolated);
    pr_unchanged_free(x->unchanged, x->unchanged_count); pr_shader_inputs_free(x->shader_inputs, x->shader_input_count);
    pr_composed_inputs_free(x->composed_inputs, x->composed_input_count); free(x->unserved);
    pr_warm_preamble_free(&x->copy);
    memset(x, 0, sizeof(*x));
}
/* Loads bytes (owned from here on) in oracle mode against fresh copies of the preamble: 1 rebuilt, 0 miss, -1
 * exhausted, -2 no memory for the copies. */
static int pr_warm_reload_bytes(pr_warm_reload *x, const pr_provider *provider, const pr_warm_preamble *preamble,
    const pr_warm_inputs *template_inputs, unsigned char *bytes, size_t length)
{
    memset(x, 0, sizeof(*x));
    if (!pr_warm_preamble_copy(&x->copy, preamble->sources, preamble->inventory, &preamble->left_out, preamble->rejections,
            preamble->exclusions, preamble->exclusion_count)) { free(bytes); return -2; }
    x->in = *template_inputs;
    x->in.oracle = 1;
    memcpy(x->in.key, provider->warm->key, 32);
    x->in.sources = &x->copy.sources; x->in.inventory = x->copy.inventory ? &x->copy.inventory : NULL;
    x->in.left_out = &x->copy.left_out; x->in.rejections = &x->copy.rejections;
    x->in.exclusions = &x->copy.exclusions; x->in.exclusion_count = &x->copy.exclusion_count;
    pr_warm_outputs out = {&x->compiled, &x->isolated, &x->unchanged, &x->unchanged_count, &x->unchanged_lost, &x->shader_inputs,
        &x->shader_input_count, &x->shader_inputs_lost, &x->composed_inputs, &x->composed_input_count, &x->composed_inputs_lost,
        &x->unserved};
    return pr_warm_load_bytes(&x->in, &out, bytes, length, "oracle", GetTickCount64());
}
static char *pr_warm_reload_text(const pr_warm_reload *x, const pr_provider *provider, const sh_package_link_history *history,
    size_t *length)
{
    pr_provider rebuilt = *provider;
    rebuilt.sources = x->copy.sources; rebuilt.compiled = x->compiled; rebuilt.bindings = x->isolated.bindings;
    rebuilt.key_groups = x->isolated.key_groups; rebuilt.consumers = x->isolated.consumers; rebuilt.fsm_webs = x->isolated.fsm_webs;
    rebuilt.virtual_materials = x->isolated.virtual_materials; rebuilt.audio = x->isolated.audio;
    rebuilt.recovery_need = x->isolated.recovered_images; rebuilt.recovery_need_count = x->isolated.recovered_image_count;
    rebuilt.image_gate = x->isolated.image_gate; rebuilt.coverage = x->isolated.coverage;
    rebuilt.rejections = x->copy.rejections; rebuilt.unserved = x->unserved;
    rebuilt.exclusions = x->copy.exclusions; rebuilt.exclusion_count = x->copy.exclusion_count;
    rebuilt.unchanged = x->unchanged; rebuilt.unchanged_count = x->unchanged_count; rebuilt.unchanged_lost = x->unchanged_lost;
    rebuilt.shader_inputs = x->shader_inputs; rebuilt.shader_input_count = x->shader_input_count;
    rebuilt.shader_inputs_lost = x->shader_inputs_lost;
    rebuilt.composed_inputs = x->composed_inputs; rebuilt.composed_input_count = x->composed_input_count;
    rebuilt.composed_inputs_lost = x->composed_inputs_lost;
    return pr_publication_text(&rebuilt, x->copy.inventory, x->copy.left_out.units, x->copy.left_out.lost, history, length);
}
/* SMP_WARM_FUZZ=1 with the oracle: truncations and single-bit flips at spread positions of each encoded record
 * load in oracle mode. A truncation must miss; a flip misses or loads well-formed content; neither may exhaust
 * memory (every count is bounded by the bytes left), crash or leak (halting ASan runs). */
static void pr_warm_fuzz(const pr_provider *provider, const pr_warm_preamble *preamble, const pr_warm_inputs *template_inputs,
    const sh_package_link_history *history, const unsigned char *record, size_t length, const char *cold, size_t cold_length)
{
    size_t truncations = length < 160 ? length : 160, flips = length < 320 ? length : 320;
    size_t misses = 0, loads = 0, equal = 0;
    char line[400];
    for (size_t step = 0; step < truncations + flips; step++) {
        size_t cut = length, at = SIZE_MAX;
        if (step < truncations) cut = length * step / truncations;
        else at = length * (step - truncations) / flips;
        unsigned char *bytes = malloc(cut ? cut : 1);
        if (!bytes) { pr_warm_oracle_fail("no memory for a fuzz record", NULL, 0, NULL, 0); return; }
        memcpy(bytes, record, cut);
        if (at != SIZE_MAX) bytes[at] ^= (unsigned char)(1u << (step % 8));
        pr_warm_reload x;
        int loaded = pr_warm_reload_bytes(&x, provider, preamble, template_inputs, bytes, cut);
        if (loaded == -2) { pr_warm_oracle_fail("no memory for a fuzz preamble", NULL, 0, NULL, 0); return; }
        if (loaded < 0) {
            snprintf(line, sizeof(line), "a damaged record exhausted memory (%s at %zu of %zu)", at == SIZE_MAX ? "cut" : "flip",
                at == SIZE_MAX ? cut : at, length);
            pr_warm_oracle_fail(line, NULL, 0, NULL, 0); return;
        }
        if (loaded == 1 && at == SIZE_MAX) {
            snprintf(line, sizeof(line), "a record cut to %zu of %zu bytes loaded", cut, length);
            pr_warm_oracle_fail(line, NULL, 0, NULL, 0); return;
        }
        if (loaded == 1) {
            size_t n = 0;
            char *text = pr_warm_reload_text(&x, provider, history, &n);
            loads++;
            if (text && n == cold_length && !memcmp(text, cold, n)) equal++;
            free(text);
        } else misses++;
        pr_warm_reload_free(&x);
    }
    snprintf(line, sizeof(line), "warm fuzz: %zu cuts and %zu flips of a %zu-byte record: %zu misses, %zu loads (%zu equal to the "
        "compiled publication)", truncations, flips, length, misses, loads, equal);
    pr_warm_note(line, -1);
}
static void pr_warm_oracle(const pr_provider *provider, const pr_inventory *inventory, const pr_warm_preamble *preamble,
    const pr_warm_inputs *template_inputs)
{
    char cache[4096], error[512] = "";
    sh_package_warm_writer w = {0};
    const sh_package_link_history *history = g_test_link_history ? g_link_history : NULL;
    if (!pr_cache_directory(provider->data_root, cache, sizeof(cache)) ||
        !pr_warm_encode(provider, provider->warm, cache, history, &w, error, sizeof(error))) {
        char what[700];
        snprintf(what, sizeof(what), "the record cannot be written: %s", error);
        sh_package_warm_writer_free(&w);
        pr_warm_oracle_fail(what, NULL, 0, NULL, 0);
        return;
    }
    size_t length = w.length;
    unsigned char *record = NULL;
    int fuzz = pr_warm_env_on("SMP_WARM_FUZZ");
    if (fuzz && !(record = malloc(length ? length : 1))) {
        sh_package_warm_writer_free(&w); pr_warm_oracle_fail("no memory for the fuzz record", NULL, 0, NULL, 0); return;
    }
    if (record && length) memcpy(record, w.bytes, length);
    pr_warm_reload x;
    unsigned char *bytes = w.bytes;
    w.bytes = NULL; w.length = w.capacity = 0;
    int loaded = pr_warm_reload_bytes(&x, provider, preamble, template_inputs, bytes, length);
    if (loaded != 1) {
        pr_warm_reload_free(&x); free(record);
        pr_warm_oracle_fail(loaded == -2 ? "no memory for the preamble copy" : loaded < 0 ? "the reload ran out of memory" :
            g_test_warm_result, NULL, 0, NULL, 0);
        return;
    }
    size_t cold_length = 0, warm_length = 0;
    char *cold = pr_publication_text(provider, inventory ? inventory->sources : NULL, inventory ? inventory->left_out : NULL,
        inventory ? inventory->left_out_lost : 0, history, &cold_length);
    char *warm = pr_warm_reload_text(&x, provider, history, &warm_length);
    int same = cold && warm && cold_length == warm_length && !memcmp(cold, warm, cold_length);
    if (!same) pr_warm_oracle_fail("the rebuilt publication differs", cold, cold_length, warm, warm_length);
    {
        /* What the reload covered: the publication features and the journal it revalidated. */
        const pr_journal *j = provider->warm->journal;
        size_t materials = sh_virtual_material_runtime_count(provider->virtual_materials), private_pages = 0, sounds = 0, inputs = 0;
        size_t scopes = provider->audio ? sh_package_audio_program_scope_count(provider->audio) : 0;
        for (size_t i = 0; i < materials; i++) {
            sh_virtual_material_runtime_binding b;
            if (sh_virtual_material_runtime_at(provider->virtual_materials, i, &b) && b.pages) private_pages++;
        }
        for (size_t i = 0; i < scopes; i++) {
            sounds += sh_package_audio_program_sound_count(provider->audio, i);
            inputs += sh_package_audio_program_input_count(provider->audio, i);
        }
        char line[900];
        snprintf(line, sizeof(line), "warm oracle: %zu-byte record rebuilt the publication exactly (%zu text bytes): "
            "resources %zu bindings %zu consumers %zu webs %zu/%zu/%zu keys %d materials %zu (private %zu) audio %d "
            "(scopes %zu sounds %zu inputs %zu) recovery %zu gate %d unchanged %zu shader %zu composed %zu; journal reads %zu "
            "images %zu strings %zu shaders %zu atlases %zu ready %zu identities %zu history %zu/%zu", length, cold_length,
            provider->compiled->resource_count, provider->bindings.binding_count, sh_package_consumers_count(provider->consumers),
            provider->fsm_webs ? provider->fsm_webs->count : 0, provider->fsm_webs ? provider->fsm_webs->owned_count : 0,
            provider->fsm_webs ? provider->fsm_webs->generated_count : 0, provider->key_groups != NULL, materials, private_pages,
            provider->audio != NULL, scopes, sounds, inputs, provider->recovery_need_count, provider->image_gate,
            provider->unchanged_count, provider->shader_input_count, provider->composed_input_count, j->read_count, j->image_count,
            j->string_count, j->shader_count, j->atlas_count, j->ready_count, j->identity_count,
            history ? sh_package_link_history_count(history) : 0, history ? sh_package_link_history_claims(history) : 0);
        pr_warm_note(line, -1);
    }
    pr_warm_reload_free(&x);
    if (fuzz) pr_warm_fuzz(provider, preamble, template_inputs, history, record, length, cold, cold_length);
    free(record); free(cold); free(warm);
}
/* SMP_REUSE_ORACLE=1 (testing builds): every installed-library compile that bound recorded shared stock is compiled
 * again at once without the record, and the two libraries must agree field for field: the compilation and provenance
 * texts (exact bytes), consumers, state-machine webs and key groups as encoded, coverage, recovered images, the image
 * gate, shader and composed input accounting and the virtual material bindings. A difference ends the process, so a
 * whole suite run is a differential of scope reuse on the production entry point. */
static void pr_reuse_text_put(pr_emit *e, const char *label, const void *bytes, size_t length)
{
    pr_emit_bytes(e, label, strlen(label) + 1);
    uint64_t n = length;
    pr_emit_bytes(e, &n, sizeof(n));
    if (length) pr_emit_bytes(e, bytes, length);
}
static unsigned char *pr_reuse_library_text(const sh_package_library *l, size_t *length)
{
    pr_emit e = {0};
    size_t n = 0;
    char *text = sh_package_warm_compilation_text(l->compiled, &n);
    pr_reuse_text_put(&e, "compilation", text, text ? n : 0); free(text);
    text = sh_package_warm_provenance_text(&l->bindings, &n);
    pr_reuse_text_put(&e, "provenance", text, text ? n : 0); free(text);
    {
        sh_package_warm_writer w = {0};
        sh_package_warm_put_consumers(&w, l->consumers); sh_package_warm_put_webs(&w, l->fsm_webs);
        sh_package_warm_put_key_groups(&w, l->key_groups);
        pr_reuse_text_put(&e, "outputs", w.bytes, w.failed ? 0 : w.length);
        if (w.failed) e.failed = 1;
        sh_package_warm_writer_free(&w);
    }
    pr_reuse_text_put(&e, "coverage", l->coverage, l->coverage ? strlen(l->coverage) : 0);
    for (size_t i = 0; i < l->recovered_image_count; i++)
        pr_reuse_text_put(&e, "recovered", l->recovered_images[i], strlen(l->recovered_images[i]));
    pr_reuse_text_put(&e, "gate", &l->image_gate, sizeof(l->image_gate));
    for (size_t i = 0; i < l->shader_input_count; i++) {
        const sh_package_unpublished_shader *s = l->shader_inputs + i;
        uint64_t fields[5] = {s->file, s->pair, (uint64_t)s->reason, (uint64_t)(int64_t)s->renderer, s->checksum};
        pr_reuse_text_put(&e, "shader", fields, sizeof(fields));
        pr_reuse_text_put(&e, "pair", s->pair_path, s->pair_path ? strlen(s->pair_path) : 0);
    }
    for (size_t i = 0; i < l->composed_input_count; i++) {
        pr_reuse_text_put(&e, "composed", &l->composed_inputs[i].file, sizeof(size_t));
        pr_reuse_text_put(&e, "peers", l->composed_inputs[i].peers, l->composed_inputs[i].peer_count * sizeof(size_t));
    }
    size_t materials = sh_virtual_material_runtime_count(l->virtual_materials);
    pr_reuse_text_put(&e, "materials", &materials, sizeof(materials));
    for (size_t i = 0; i < materials; i++) {
        sh_virtual_material_runtime_binding b;
        if (!sh_virtual_material_runtime_at(l->virtual_materials, i, &b)) { e.failed = 1; break; }
        pr_reuse_text_put(&e, "material", b.name, b.name ? strlen(b.name) : 0);
        pr_reuse_text_put(&e, "atlas", b.atlas, b.atlas ? strlen(b.atlas) : 0);
        int32_t fields[3] = {b.dlc, b.page_kind, b.page_mode};
        pr_reuse_text_put(&e, "page", fields, sizeof(fields));
        if (b.pages) pr_reuse_text_put(&e, "pages", sh_virtual_page_source_identity(b.pages), 32);
        for (size_t k = 0; b.page_paths && k < 21; k++)
            pr_reuse_text_put(&e, "page path", b.page_paths[k], b.page_paths[k] ? strlen(b.page_paths[k]) : 0);
        if (b.record) {
            /* By value: the record's name is a pointer. */
            int32_t values[7] = {b.record->x, b.record->y, b.record->width, b.record->height, b.record->flags,
                b.record->timestamp, b.record->checksum};
            pr_reuse_text_put(&e, "record", b.record->name, b.record->name ? strlen(b.record->name) : 0);
            pr_reuse_text_put(&e, "record values", values, sizeof(values));
        }
    }
    int audio = l->audio != NULL;
    pr_reuse_text_put(&e, "audio", &audio, sizeof(audio));
    if (e.failed) { free(e.bytes); return NULL; }
    *length = e.length; return e.bytes;
}
/* A diagnostic of the oracle (SMP_REUSE_TRACE names the absolute prefix): <prefix>.<label>.txt. A diagnostic that
 * cannot be written is reported, never silently missing. */
static void pr_reuse_diagnostic(const char *label, const void *bytes, size_t length)
{
    char *prefix = NULL, path[1100]; size_t n = 0; FILE *file = NULL;
    if (_dupenv_s(&prefix, &n, "SMP_REUSE_TRACE") || !prefix || !*prefix) {
        fprintf(stderr, "scope reuse oracle: cannot write its %s diagnostic: SMP_REUSE_TRACE is not set\n", label);
        free(prefix); return;
    }
    int written = snprintf(path, sizeof(path), "%s.%s.txt", prefix, label) < (int)sizeof(path) && bytes &&
        !fopen_s(&file, path, "wb") && file;
    if (written) { written = fwrite(bytes, 1, length, file) == length; written = !fclose(file) && written; }
    if (!written) fprintf(stderr, "scope reuse oracle: cannot write %s\n", path);
    free(prefix);
}
/* The compile's own adapters again (pr_journal_attach reversed on copies): the oracle's compile answers alike but
 * records nothing into the publishing compile's warm journal. */
static void pr_journal_detach(const pr_journal *j, sh_package_library_native *native, sh_package_compile_environment *env)
{
    if (native->baseline_backed == pr_jr_game_backed) native->baseline_backed = j->game_backed;
    if (native->image_excluded == pr_jr_image) native->image_excluded = j->image_excluded;
    if (native->strings.reserve == pr_jr_reserve) native->strings = j->strings_inner;
    if (native->source.shader == &j->shader) native->source.shader = j->shader_inner;
    if (native->atlas == pr_jr_atlas) native->atlas = j->atlas;
    if (native->identity_journal == &j->identity_hooks) native->identity_journal = NULL;
    if (env->baseline == pr_jr_game) env->baseline = j->game;
    if (env->baseline_identity == pr_jr_identity) env->baseline_identity = j->identity;
}
static void pr_reuse_oracle(const sh_package_library *reused, const sh_package_sources *sources,
    const sh_package_provenance *contexts, const sh_package_compile_environment *environment,
    const sh_resource_catalog *catalog, pr_original_source *originals, sh_decl_registry_source registry,
    uintptr_t reflection, const sh_package_library_native *native, sh_package_link_history_mark history_mark)
{
    sh_package_library fresh = {0};
    sh_package_library_native without = *native;
    sh_package_compile_environment env = *environment;
    char error[2048] = "", line[900];
    size_t invalid = SIZE_MAX, unserved = SIZE_MAX;
    int own = 0;
    sh_package_rejections more = {0};
    sh_package_owners conflicted = {0};
    without.source.reuse_in = NULL; without.source.reuse_out = NULL; without.reuse_fallback_outside = 0;
    /* The reference is a fresh compile in the restored compile's exact environment: the same native adapters and
     * reservations, the link history as it was before the restored compile (what that compile claimed is released
     * first; an equal reference claims it again), and no source memo, so every unit is discovered afresh rather than
     * replayed from the recordings the restored compile left there. */
    without.source.memo = NULL;
    if (without.history && !sh_package_link_history_rollback(without.history, history_mark)) {
        fprintf(stderr, "scope reuse oracle FAILED: the native binding history cannot return to the restored compile's start\n");
        abort();
    }
    /* Unjournaled, with its own shipped editor roster (the restored compile's was released when it returned). */
    pr_original_source quiet = *originals;
    quiet.journaled = 0;
    if (g_journal) pr_journal_detach(g_journal, &without, &env);
    pr_compile_rows shipped = {catalog, &quiet};
    if (without.editor_rows == pr_compile_rows_read) without.editor_rows_context = &shipped;
    char *captures[2] = {NULL, NULL};
    if (pr_warm_env_on("SMP_REUSE_DUMP")) {
        captures[0] = _strdup(sh_package_source_link_test_capture_dumped()); sh_package_source_link_test_capture_dump(1);
    }
    if (env.invalid_package) env.invalid_package = &invalid;
    if (env.invalid_own_bytes) env.invalid_own_bytes = &own;
    if (env.unserved_package) env.unserved_package = &unserved;
    if (env.more_rejections) env.more_rejections = &more;
    if (env.conflicted_packages) env.conflicted_packages = &conflicted;
    int ok = contexts ? sh_package_library_compile_contexts(sources, contexts, &env, catalog, pr_original, &quiet,
        registry, reflection, &without, &fresh, error, sizeof(error)) :
        sh_package_library_compile(sources, &env, catalog, pr_original, &quiet, registry, reflection, &without,
            &fresh, error, sizeof(error));
    sh_editor_rows_free(&shipped.rows);
    size_t a_length = 0, b_length = 0;
    unsigned char *a = ok ? pr_reuse_library_text(reused, &a_length) : NULL, *b = ok ? pr_reuse_library_text(&fresh, &b_length) : NULL;
    /* SMP_REUSE_ORACLE_CONTROL=1, the negative control of the comparison: one restored byte differs. */
    if (a && a_length && pr_warm_env_on("SMP_REUSE_ORACLE_CONTROL")) {
        a[a_length / 2] ^= 0x20;
        fprintf(stderr, "scope reuse oracle: negative control perturbs restored byte %zu\n", a_length / 2);
    }
    int same = a && b && a_length == b_length && !memcmp(a, b, a_length);
    if (captures[0]) {
        /* The dump stays as the reference compile left it (the restored compile's text when they agree), for any test
         * reading it after the compile. */
        captures[1] = _strdup(sh_package_source_link_test_capture_dumped());
        int differs = !captures[1] || strcmp(captures[0], captures[1]);
        if (differs) {
            fprintf(stderr, "scope reuse oracle: the restored captures differ from the fresh ones\n");
            for (int k = 0; k < 2; k++)
                pr_reuse_diagnostic(k ? "capture.fresh" : "capture.reused", captures[k], captures[k] ? strlen(captures[k]) : 0);
        }
        free(captures[0]); free(captures[1]);
    }
    if (!same) {
        size_t at = 0;
        while (a && b && at < a_length && at < b_length && a[at] == b[at]) at++;
        snprintf(line, sizeof(line), "scope reuse oracle FAILED: %s (first difference at byte %zu of %zu / %zu)",
            !ok ? error : "the restored library differs from a compile without the record", at, a_length, b_length);
        pr_reuse_note(line); fprintf(stderr, "%s\n", line);
        pr_reuse_diagnostic("reused", a, a_length); pr_reuse_diagnostic("fresh", b, b_length);
        abort();
    }
    snprintf(line, sizeof(line), "scope reuse oracle: restored library equals a compile without the record (%zu bindings, %zu bytes compared)",
        reused->reuse_bindings, a_length);
    pr_reuse_note(line);
    free(a); free(b);
    sh_package_library_free(&fresh); sh_package_rejections_free(&more); sh_package_owners_free(&conflicted);
}
/* SMP_REUSE_TEXTS=<absolute directory>: each linked compile's library text as <pid>-<n>.txt, n counting this
 * process's linked compiles, and one index.txt line each (<pid>-<n>, bytes, SHA-256, bindings bound, input key), so a
 * run with reuse compares with a run without it across processes and apart from the in-process oracle. The input key
 * is the compile's content alone (route, packages by name and tree digest, components and files by relative path,
 * length and digest; no absolute path): compiles of the same inputs must publish the same library in both runs,
 * whatever their order or number. */
static long g_test_text_serial;
static void pr_reuse_text_record(const sh_package_library *l, const sh_package_sources *s, int contexts)
{
    char *directory = NULL, path[1200], hex[65] = "", key[65] = "";
    size_t n = 0, length = 0;
    if (_dupenv_s(&directory, &n, "SMP_REUSE_TEXTS") || !directory || !*directory) { free(directory); return; }
    long serial = ++g_test_text_serial;
    unsigned long pid = GetCurrentProcessId();
    unsigned char *text = pr_reuse_library_text(l, &length);
    sh_package_file_identity identity, input;
    pr_emit e = {0};
    uint64_t counts[4] = {(uint64_t)contexts, s->package_count, s->component_count, s->file_count};
    pr_emit_bytes(&e, counts, sizeof(counts));
    for (size_t i = 0; i < s->package_count; i++) {
        pr_emit_bytes(&e, s->packages[i].name, strlen(s->packages[i].name) + 1);
        if (s->fingerprints) pr_emit_bytes(&e, s->fingerprints[i], 32);
        if (s->original_fingerprints) pr_emit_bytes(&e, s->original_fingerprints[i], 32);
    }
    for (size_t i = 0; i < s->component_count; i++) {
        uint64_t owner = s->components[i].owner;
        pr_emit_bytes(&e, &owner, sizeof(owner));
        pr_emit_bytes(&e, s->components[i].relative, strlen(s->components[i].relative) + 1);
        pr_emit_bytes(&e, s->components[i].descriptor_digest, 32);
    }
    for (size_t i = 0; i < s->file_count; i++) {
        const sh_package_source_file *f = s->files + i;
        uint64_t fields[4] = {f->owner, f->component, f->length, (uint64_t)f->directory};
        pr_emit_bytes(&e, fields, sizeof(fields));
        pr_emit_bytes(&e, f->relative, strlen(f->relative) + 1);
        pr_emit_bytes(&e, f->engine_path ? f->engine_path : "", (f->engine_path ? strlen(f->engine_path) : 0) + 1);
        pr_emit_bytes(&e, f->digest, 32);
    }
    FILE *file = NULL;
    int ok = text && sh_package_bytes_identity(text, length, &identity) && !e.failed &&
        sh_package_bytes_identity(e.bytes ? e.bytes : (const unsigned char *)"", e.length, &input);
    free(e.bytes);
    for (int i = 0; ok && i < 32; i++) {
        snprintf(hex + 2 * i, 3, "%02x", identity.digest[i]); snprintf(key + 2 * i, 3, "%02x", input.digest[i]);
    }
    ok = ok && snprintf(path, sizeof(path), "%s/%lu-%ld.txt", directory, pid, serial) < (int)sizeof(path) &&
        !fopen_s(&file, path, "wb") && file;
    if (ok) { ok = fwrite(text, 1, length, file) == length; ok = !fclose(file) && ok; }
    ok = ok && snprintf(path, sizeof(path), "%s/index.txt", directory) < (int)sizeof(path) && !fopen_s(&file, path, "ab") && file;
    if (ok) {
        ok = fprintf(file, "%lu-%ld %zu %s bound %zu key %s\n", pid, serial, length, hex, l->reuse_bindings, key) > 0;
        ok = !fclose(file) && ok;
    }
    if (!ok) fprintf(stderr, "scope reuse texts: cannot record compile %ld under %s\n", serial, directory);
    free(text); free(directory);
}
#endif

/* R-255: the private source root of a map plan holding no private sources,
 * only the generated layers a local document's first load serves. */
static const char g_no_private_sources[] = "";
/* R-347: a compile reuses the catalog a live provider holds when the installation under doom_base is still exactly
 * the one that catalog read (sh_resource_catalog_matches: index bytes, archive sizes, and the very archive files it
 * has held open since it opened); otherwise it opens its own. Either way the compile holds its own reference. */
static sh_resource_catalog *pr_catalog_for(const pr_provider *previous, const char *doom_base, char *error, size_t capacity)
{
    const pr_provider *owner = previous && previous->catalog ? previous :
        g_library_provider && g_library_provider->catalog ? g_library_provider : NULL;
    if (owner && sh_resource_catalog_matches(owner->catalog, doom_base, NULL, 0) == 1) {
#ifdef SH_PACKAGE_RUNTIME_TESTING
        InterlockedIncrement(&g_test_catalog_reuses);
#endif
        return sh_resource_catalog_retain(owner->catalog);
    }
    if (!owner) {
        /* R-400: the first compile of the process takes the catalog the boot worker opened at attach. */
        sh_resource_catalog *boot = pr_boot_prefetch_catalog(doom_base);
        if (boot) return boot;
    }
#ifdef SH_PACKAGE_RUNTIME_TESTING
    InterlockedIncrement(&g_test_catalog_opens);
#endif
    return sh_resource_catalog_open(doom_base, error, capacity);
}
/* An image row (.bimage): the family a publication releases to its backing (pr_release_published). */
static int pr_released_image(const sh_compiled_resource *r)
{
    size_t n = r->engine_path ? strlen(r->engine_path) : 0;
    return n > 7 && !_stricmp(r->engine_path + n - 7, ".bimage");
}
/* R-347: once a publication is complete, an archive-backed image it publishes keeps no resident bytes. The body holds
 * the pinned archive row its bytes were decoded from (sh_package_backing over sh_resource_slice: the archive handles
 * share reading only and outlive the catalog), so every reader reads exactly those bytes again through it
 * (sh_package_compilation_read, the serving route; sh_package_body_read) for as long as any holder keeps the body,
 * and the bytes themselves go when no holder keeps them. Only images are let go: after publication they are read
 * only through the serving, comparison, change and record functions, which all read through the body. A pending
 * warm record names each backed body by the original read with its identity: found first, while every byte is here.
 * Called before any other thread can see the provider. */
static void pr_release_published(pr_provider *provider)
{
    sh_package_compilation *compiled = provider ? provider->compiled : NULL;
    if (!compiled) return;
    pr_warm_pending *pending = provider->warm;
    /* Without origins found here the record is written later from bytes read again (pr_body_origins_build). */
    int early = 1;
#ifdef SH_PACKAGE_RUNTIME_TESTING
    early = !g_test_origins_late;
#endif
    if (early && pending && !pending->origins_built && pr_body_origins_build(&pending->origins, compiled, pending->journal))
        pending->origins_built = 1;
    for (size_t i = 0; i < compiled->resource_count; i++) {
        sh_compiled_resource *r = compiled->resources + i;
        if (!r->body || !r->body_owner || r->presented || !sh_package_body_backed(r->body_owner) ||
            r->body != sh_package_body_bytes(r->body_owner) || !pr_released_image(r)) continue;
        r->body = NULL; sh_package_body_detach(r->body_owner);
#ifdef SH_PACKAGE_RUNTIME_TESTING
        InterlockedIncrement(&g_test_detached_published);
#endif
    }
}
/* R-397: a provider's per-row identity provenance from a path-keyed list (moved from: its sets are taken).
 * Rows the list does not name were built from stock alone. 0 only on allocation failure. */
typedef struct pr_prov_key { const char *path; size_t index; } pr_prov_key;
static int pr_prov_key_order(const void *a, const void *b)
{ return strcmp(((const pr_prov_key *)a)->path, ((const pr_prov_key *)b)->path); }
static int pr_prov_take(pr_provider *provider, const char *const *paths, sh_package_owners *sets, size_t count)
{
    size_t rows = provider->compiled ? provider->compiled->resource_count : 0;
    sh_package_owners *table = calloc(rows ? rows : 1, sizeof(*table));
    pr_prov_key *keys = calloc(count ? count : 1, sizeof(*keys));
    if (!table || !keys) { free(table); free(keys); return 0; }
    for (size_t i = 0; i < count; i++) keys[i] = (pr_prov_key){paths[i], i};
    qsort(keys, count, sizeof(*keys), pr_prov_key_order);
    for (size_t r = 0; r < rows; r++) {
        pr_prov_key key = {provider->compiled->resources[r].engine_path, 0};
        const pr_prov_key *found = bsearch(&key, keys, count, sizeof(*keys), pr_prov_key_order);
        if (found) { table[r] = sets[found->index]; memset(sets + found->index, 0, sizeof(*sets)); }
    }
    free(keys);
    for (size_t i = 0; provider->prov && i < provider->prov_count; i++) sh_package_owners_free(provider->prov + i);
    free(provider->prov);
    provider->prov = table; provider->prov_count = rows;
    return 1;
}
