typedef struct pr_bank_list {
    uint32_t *ids, *languages;
    size_t count, capacity;
    int failed;
} pr_bank_list;

static int pr_collect_bank(void *context, uint32_t id, uint32_t language)
{
    pr_bank_list *list = context;
    if (list->count == list->capacity) {
        size_t grown = list->capacity ? list->capacity * 2 : 64;
        uint32_t *ids = realloc(list->ids, grown * sizeof(*ids));
        if (ids) list->ids = ids;
        uint32_t *languages = ids ? realloc(list->languages, grown * sizeof(*languages)) : NULL;
        if (!languages) { list->failed = 1; return 0; }
        list->languages = languages;
        list->capacity = grown;
    }
    list->ids[list->count] = id;
    list->languages[list->count++] = language;
    return 1;
}

/* Visitors may read audio originals, which takes both locks again, so they run
 * after the walk releases them. */
int sh_package_runtime_audio_packaged_banks(sh_audio_originals_bank_visit visit, void *visitor,
    char *error, size_t capacity)
{
    pr_bank_list list = {0};
    int result;
    if (!visit) return sh_audio_originals_packaged_banks(NULL, NULL, NULL, error, capacity);
    AcquireSRWLockShared(&g_lock);
    result = sh_audio_originals_packaged_banks(g_current_provider ?
        g_current_provider->audio_originals : NULL, pr_collect_bank, &list, error, capacity);
    ReleaseSRWLockShared(&g_lock);
    if (list.failed) {
        if (error && capacity) snprintf(error, capacity, "out of memory listing packaged audio banks");
        result = -1;
    }
    for (size_t i = 0; result == 1 && i < list.count; i++)
        if (!visit(visitor, list.ids[i], list.languages[i])) result = 0;
    free(list.ids);
    free(list.languages);
    return result;
}

/* A growable summary: each line is sized from what it prints, so no package,
 * component or diagnostic count can truncate it. failed is sticky. */
typedef struct pr_summary { char *text; size_t length, capacity; int failed; } pr_summary;
static void pr_summary_put(pr_summary *s, const char *format, ...)
{
    va_list args;
    int needed;
    if (s->failed) return;
    va_start(args, format); needed = vsnprintf(NULL, 0, format, args); va_end(args);
    if (needed < 0) { s->failed = 1; return; }
    if ((size_t)needed >= s->capacity - s->length) {
        size_t next = s->capacity ? s->capacity : 4096;
        while ((size_t)needed >= next - s->length) {
            if (next > SIZE_MAX / 2) { s->failed = 1; return; }
            next *= 2;
        }
        char *grown = (char *)realloc(s->text, next);
        if (!grown) { s->failed = 1; return; }
        s->text = grown; s->capacity = next;
    }
    va_start(args, format); vsnprintf(s->text + s->length, s->capacity - s->length, format, args); va_end(args);
    s->length += (size_t)needed;
}
/* The game settings the active compilation requires (policy requirements):
 * each composed value, then every component requesting it with its own value
 * (a package's nested components may ask differently from its root). Called
 * with g_lock held. */
static void pr_summary_settings(pr_summary *s)
{
    sh_json_object cvars = {0};
    const char *raw = sh_json_object_get(&g_compiled->policy.requirements, "cvars");
    if (!raw || !sh_json_parse_object(raw, strlen(raw), 2, &cvars) || !cvars.count) {
        pr_summary_put(s, "Effective settings: no package requires a game setting.\n");
        sh_json_object_free(&cvars); return;
    }
    pr_summary_put(s, "Effective settings required by packages:\n");
    for (size_t c = 0; c < cvars.count; c++) {
        size_t listed = 0;
        pr_summary_put(s, "  %s = %s; requested by", cvars.members[c].key, cvars.members[c].value_json);
        for (size_t i = 0; i < g_sources->package_count; i++) {
            const sh_package_descriptor *root = NULL;
            for (size_t j = 0; j < g_sources->component_count && !root; j++)
                if (g_sources->components[j].owner == i && !g_sources->components[j].relative[0])
                    root = &g_sources->components[j].descriptor;
            for (size_t j = 0; j < g_sources->component_count; j++) {
                const sh_package_component *component = g_sources->components + j;
                sh_json_object requirements = {0}, own = {0};
                const char *section, *value;
                if (component->owner != i) continue;
                if ((section = sh_json_object_get(&component->descriptor.fields, "requirements")) &&
                    sh_json_parse_object(section, strlen(section), 3, &requirements) &&
                    (section = sh_json_object_get(&requirements, "cvars")) &&
                    sh_json_parse_object(section, strlen(section), 2, &own) &&
                    (value = sh_json_object_get(&own, cvars.members[c].key)) != NULL) {
                    if (component->relative[0])
                        pr_summary_put(s, "%s %s [%s] component %s (%s)", listed++ ? "," : "",
                            root ? root->name : "Package", root ? root->id : "?", component->relative, value);
                    else
                        pr_summary_put(s, "%s %s [%s] (%s)", listed++ ? "," : "", root ? root->name : "Package",
                            root ? root->id : "?", value);
                }
                sh_json_object_free(&own); sh_json_object_free(&requirements);
            }
        }
        if (!listed) pr_summary_put(s, " the active map's packages");
        pr_summary_put(s, "\n");
    }
    sh_json_object_free(&cvars);
}
static int pi_summary_line(pr_summary *s);
char *sh_package_runtime_summary(void)
{
    pr_summary s = {0};
    size_t i, j;
    AcquireSRWLockShared(&g_lock);
    const char *rejections = g_library_provider ? g_library_provider->rejections : NULL;
    const char *coverage = g_library_provider ? g_library_provider->coverage : NULL;
    const char *unserved = g_library_provider ? g_library_provider->unserved : NULL;
    pr_summary_put(&s, "Installed library: %zu packages.\n", g_inventory ? g_inventory->sources->package_count : 0);
    /* Conversion helps only an earlier-release package: a descriptor without a
     * usable id (installer overrides_plan.go legacyDesc) or resources outside
     * assets/ (pi_classify, PI_LEGACY). Malformed content, unusable names and
     * peer disagreements are not that, so they get no conversion advice. */
    if (rejections) {
        pr_summary_put(&s, "%s%s", rejections,
            "Skipped packages stay unchanged on disk; each reason names what to fix, and other packages are "
            "unaffected. 'sh_packages inputs <package>' lists their files.\n");
        if (strstr(rejections, "package.json is missing its required id") || strstr(rejections, "package.json id must be"))
            pr_summary_put(&s, "A package.json without a usable id is an earlier-release descriptor this library does "
                "not serve. Map deliveries are converted automatically; for a local authoring folder the optional "
                "developer tool snapmap-plus migrate-overrides converts it.\n");
    }
    if (unserved) pr_summary_put(&s, "%s%s", unserved,
        "Packages not served yet stay installed and unchanged; they need a Snapmap+ update, not an edit.\n");
    if (coverage) pr_summary_put(&s, "%s", coverage);
    if (g_authoring_error[0]) pr_summary_put(&s,
        "Local authoring composition unavailable: %s\nIndependent map packages can still compile.\n", g_authoring_error);
    if (!g_ready) pr_summary_put(&s, "Packages could not compile: %s\n%s",
        g_error[0] ? g_error : "compiler has not initialized",
        g_compiled ? "The last successful compilation remains active.\n" : "");
    pi_summary_line(&s);
    if (!g_sources || !g_compiled || !g_sources->package_count) {
        pr_summary_put(&s, "No packages in the active compilation.\n"); goto done;
    }
    pr_summary_put(&s, "%zu packages; %zu native resources; %zu identical duplicates; %zu composed declarations.\n",
        g_sources->package_count, g_compiled->resource_count, g_compiled->duplicate_count, g_compiled->composed_count);
    for (i = 0; i < g_sources->package_count; i++) {
        const sh_package_descriptor *descriptor = NULL;
        size_t files = 0, components = 0, gameplay = 0;
        uint64_t bytes = 0;
        for (j = 0; j < g_sources->component_count; j++) if (g_sources->components[j].owner == i) {
            components++;
            if (!g_sources->components[j].relative[0]) descriptor = &g_sources->components[j].descriptor;
        }
        for (j = 0; j < g_sources->file_count; j++) if (g_sources->files[j].owner == i && !g_sources->files[j].directory) {
            files++; bytes += g_sources->files[j].length;
        }
        for (j = 0; j < g_compiled->resource_count; j++)
            gameplay += sh_package_owners_contains(&g_compiled->resources[j].gameplay_owners, i);
        pr_summary_put(&s, "%s [%s]\n  %zu files, %llu bytes, %zu components; %s\n  %s\n",
            descriptor ? descriptor->name : "Package", descriptor ? descriptor->id : "?",
            files, (unsigned long long)bytes, components, gameplay ? "contains gameplay resources" : "editor support",
            g_sources->packages[i].root);
    }
    pr_summary_settings(&s);
done:
    ReleaseSRWLockShared(&g_lock);
    if (s.failed) { free(s.text); return NULL; }
    return s.text;
}

/* Per-input accounting (sh_packages inputs). Every unit the installed scan
 * discovered, and each of its files and folders, gets one disposition from the
 * served library's own records: compiled rows (every input index, duplicates
 * included), the files generated rows' producers read, rows left native as
 * unchanged originals, and the library's left-out and not-served reports. An
 * input none of them explains is reported as unaccounted; it is never
 * dismissed as ancillary. */
enum {
    PI_SERVED, PI_SHARED, PI_COMPOSED, PI_OVERLAP, PI_GENERATED, PI_UNCHANGED, PI_SHADER,
    PI_DESCRIPTOR, PI_FOLDER, PI_AUTHOR, PI_LEGACY,
    PI_MALFORMED, PI_LEFT_OUT, PI_UNSERVED, PI_UNACCOUNTED, PI_KINDS
};
static const char *const g_pi_kinds[PI_KINDS] = {
    "served", "shared copy", "composed", "overlap resolved", "generated input", "unchanged original",
    "inactive shader", "descriptor", "folder", "author data", "outside assets",
    "malformed unit", "left out", "not served yet", "unaccounted"
};
#define PI_PAGE 250u
#define PI_LISTED 40u
typedef struct pi_key { size_t owner; const char *relative; size_t length, index; } pi_key;
static int pi_key_order(const void *a, const void *b)
{
    const pi_key *x = a, *y = b;
    size_t n = x->length < y->length ? x->length : y->length;
    int order;
    if (x->owner != y->owner) return x->owner < y->owner ? -1 : 1;
    if ((order = strncmp(x->relative, y->relative, n)) != 0) return order;
    return x->length < y->length ? -1 : x->length > y->length;
}
/* One served file a generated row's producer read (generated_sources). */
typedef struct pi_generated { size_t file, row; } pi_generated;
static int pi_generated_order(const void *a, const void *b)
{
    const pi_generated *x = a, *y = b;
    return x->file != y->file ? (x->file < y->file ? -1 : 1) : x->row < y->row ? -1 : x->row > y->row;
}
typedef struct pi_unit {
    const sh_package_sources *sources; /* the inventory, or its left-out units */
    size_t owner, served;              /* served: owner in the library, or SIZE_MAX */
    int status;                        /* PI_SERVED, or the kind all its files share */
    const char *reason;                /* the library's report line, through '\n' */
    size_t counts[PI_KINDS], files, folders, empty, components;
} pi_unit;
typedef struct pi_report {
    const pr_provider *library;
    const pr_inventory *inventory;
    const sh_package_compilation *compiled;
    const sh_package_sources *served;
    const sh_resource_catalog *catalog;
    size_t *row_start, *rows;  /* served file -> compiled rows listing it */
    pi_key *served_files;      /* by owner and exact relative path */
    pi_key *parents[2];        /* folders holding inventory / left-out entries */
    size_t parent_count[2];
    pi_generated *generated;
    size_t generated_count;
    pi_unit *units;
    size_t unit_count;
    int failed;
    /* Built for detailed reports only (pi_select, pi_reach): the library's
     * exposure selection, and per editor row (not a generated lookup row) the
     * rows its binding graph reaches. State -1 not built, 0 failed, 1 built. */
    pr_exposure_pick *picks;
    size_t pick_count, pick_sets;
    int picks_state, picks_served;  /* served: the selection the pickers use now */
    size_t *tiles, tile_count, reach_stride;
    char **tile_names;
    int *tile_class;                /* 0 left out for an equal exposure, 1 kept for one, 2 neither */
    unsigned char *reach;           /* tile_count rows of reach_stride bytes, one bit per resource */
    int reach_state;
} pi_report;
/* The report line naming exactly this package root, or NULL. */
static const char *pi_line(const char *text, const char *prefix, const char *root, const char *after)
{
    size_t p = strlen(prefix), r = strlen(root), a = strlen(after);
    for (const char *line = text; line && *line; ) {
        const char *end = strchr(line, '\n');
        if (!strncmp(line, prefix, p) && !strncmp(line + p, root, r) && !strncmp(line + p + r, after, a))
            return line;
        line = end ? end + 1 : NULL;
    }
    return NULL;
}
static const sh_package_descriptor *pi_descriptor(const sh_package_sources *sources, size_t owner)
{
    for (size_t j = 0; j < sources->component_count; j++)
        if (sources->components[j].owner == owner && !sources->components[j].relative[0])
            return &sources->components[j].descriptor;
    return NULL;
}
static void pi_free(pi_report *report)
{
    free(report->row_start); free(report->rows); free(report->served_files);
    free(report->parents[0]); free(report->parents[1]); free(report->generated); free(report->units);
    pr_exposure_free(report->picks, report->pick_count);
    for (size_t t = 0; report->tile_names && t < report->tile_count; t++) free(report->tile_names[t]);
    free(report->tiles); free(report->tile_names); free(report->tile_class); free(report->reach);
}
static int pi_parents(const sh_package_sources *sources, pi_key **out, size_t *count)
{
    *out = NULL; *count = 0;
    if (!sources || !sources->file_count) return 1;
    if (!(*out = calloc(sources->file_count, sizeof(**out)))) return 0;
    for (size_t i = 0; i < sources->file_count; i++) {
        const char *slash = strrchr(sources->files[i].relative, '/');
        if (slash) (*out)[(*count)++] = (pi_key){sources->files[i].owner, sources->files[i].relative,
            (size_t)(slash - sources->files[i].relative), i};
    }
    qsort(*out, *count, sizeof(**out), pi_key_order);
    return 1;
}
static void pi_unit_add(pi_report *report, const sh_package_sources *sources, size_t owner)
{
    pi_unit *unit = report->units + report->unit_count++;
    const pr_provider *library = report->library;
    memset(unit, 0, sizeof(*unit));
    unit->sources = sources; unit->owner = owner; unit->served = SIZE_MAX;
    const char *root = sources->packages[owner].root;
    if (sources != report->inventory->sources) {
        unit->status = PI_MALFORMED;
        unit->reason = pi_line(library->rejections, "Skipped local package ", root, ": ");
    } else {
        for (size_t j = 0; j < report->served->package_count && unit->served == SIZE_MAX; j++)
            if (!strcmp(report->served->packages[j].name, sources->packages[owner].name) &&
                !memcmp(report->served->fingerprints[j], sources->fingerprints[owner], 32)) unit->served = j;
        if (unit->served != SIZE_MAX) unit->status = PI_SERVED;
        else if ((unit->reason = pi_line(library->unserved, "Local package ", root, " is not served yet")))
            unit->status = PI_UNSERVED;
        else if ((unit->reason = pi_line(library->rejections, "Skipped local package ", root, ": ")))
            unit->status = PI_LEFT_OUT;
        else unit->status = PI_UNACCOUNTED;
    }
    for (size_t j = 0; j < sources->component_count; j++) unit->components += sources->components[j].owner == owner;
}
/* Called with g_lock held. An empty report means no library is served. */
static int pi_build(pi_report *report)
{
    const pr_provider *library = g_library_provider;
    memset(report, 0, sizeof(*report));
    report->picks_state = report->reach_state = -1;
    if (!library || !library->compiled || !library->sources || !g_inventory) return 1;
    report->library = library; report->inventory = g_inventory;
    report->compiled = library->compiled; report->served = library->sources;
    report->catalog = library->catalog ? library->catalog : library->parent ? library->parent->catalog : NULL;
    const sh_package_compilation *compiled = report->compiled;
    const sh_package_sources *served = report->served, *left = g_inventory->left_out;
    size_t files = served->file_count, total = 0, *cursor = NULL;
    for (size_t r = 0; r < compiled->resource_count; r++) {
        if (compiled->resources[r].source_count > SIZE_MAX - total) return 0;
        total += compiled->resources[r].source_count;
        if (compiled->resources[r].generated_source_count > SIZE_MAX - report->generated_count) return 0;
        report->generated_count += compiled->resources[r].generated_source_count;
    }
    report->row_start = calloc(files + 1, sizeof(*report->row_start));
    report->rows = calloc(total ? total : 1, sizeof(*report->rows));
    report->served_files = calloc(files ? files : 1, sizeof(*report->served_files));
    report->generated = calloc(report->generated_count ? report->generated_count : 1, sizeof(*report->generated));
    report->units = calloc(g_inventory->sources->package_count + (left ? left->package_count : 0) + 1,
        sizeof(*report->units));
    cursor = calloc(files ? files : 1, sizeof(*cursor));
    if (!report->row_start || !report->rows || !report->served_files || !report->generated || !report->units ||
        !cursor || !pi_parents(g_inventory->sources, &report->parents[0], &report->parent_count[0]) ||
        !pi_parents(left, &report->parents[1], &report->parent_count[1])) { free(cursor); return 0; }
    for (size_t r = 0; r < compiled->resource_count; r++)
        for (size_t s = 0; s < compiled->resources[r].source_count; s++)
            if (compiled->resources[r].sources[s] < files) report->row_start[compiled->resources[r].sources[s] + 1]++;
    for (size_t f = 0; f < files; f++) {
        report->row_start[f + 1] += report->row_start[f];
        cursor[f] = report->row_start[f];
        report->served_files[f] = (pi_key){served->files[f].owner, served->files[f].relative,
            strlen(served->files[f].relative), f};
    }
    for (size_t r = 0; r < compiled->resource_count; r++) {
        const sh_compiled_resource *resource = compiled->resources + r;
        for (size_t s = 0; s < resource->source_count; s++)
            if (resource->sources[s] < files) report->rows[cursor[resource->sources[s]]++] = r;
    }
    free(cursor);
    qsort(report->served_files, files, sizeof(*report->served_files), pi_key_order);
    size_t generated = 0;
    for (size_t r = 0; r < compiled->resource_count; r++)
        for (size_t g = 0; g < compiled->resources[r].generated_source_count; g++)
            if (compiled->resources[r].generated_sources[g] < files)
                report->generated[generated++] = (pi_generated){compiled->resources[r].generated_sources[g], r};
    report->generated_count = generated;
    qsort(report->generated, generated, sizeof(*report->generated), pi_generated_order);
    for (size_t i = 0; i < g_inventory->sources->package_count; i++) pi_unit_add(report, g_inventory->sources, i);
    for (size_t i = 0; left && i < left->package_count; i++) pi_unit_add(report, left, i);
    return 1;
}
static void pi_row(pr_summary *s, const sh_compiled_resource *r)
{
    size_t names = sh_package_resource_native_count(r);
    pr_summary_put(s, " %s", r->engine_path);
    if (r->native_type && r->native_name) pr_summary_put(s, " as %s %s", r->native_type, r->native_name);
    else if (r->type && r->name) pr_summary_put(s, " as %s %s", r->type, r->name);
    if (names > 1) pr_summary_put(s, " +%zu names", names - 1);
    if (r->original_path) pr_summary_put(s, " (private alias of %s)", r->original_path);
    if (r->composed) pr_summary_put(s, " (composed)");
    if (r->generated) pr_summary_put(s, " (generated)");
    if (r->presented) pr_summary_put(s, " (label presented)");
}
/* The index entries (first..last) of the generated rows whose producers read
 * this served file, as the compiler recorded each read (generated_sources). */
static void pi_generated_range(const pi_report *report, size_t file, size_t *first, size_t *last)
{
    size_t low = 0, high = report->generated_count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (report->generated[middle].file < file) low = middle + 1; else high = middle;
    }
    *first = *last = low;
    while (*last < report->generated_count && report->generated[*last].file == file) ++*last;
}
/* The library's exposure selection (pr_exposure_select): the one the
 * pickers use while the library's own view is served (no map composition is
 * active), else the library's own. */
static void pi_select(pi_report *report)
{
    const sh_package_compilation *compiled = report->compiled;
    report->picks_state = 0;
    if (pr_reading_staged()) {
        /* A staged departure view: the selection its publication would install (pr_exposure_refresh). */
        pr_original_source originals = {g_catalog ? sh_resource_catalog_read_path : NULL, (void *)g_catalog,
            g_reading_view->native_assets};
#ifdef SH_PACKAGE_RUNTIME_TESTING
        sh_package_baseline_reader test = NULL; void *context = NULL;
        sh_package_runtime_test_source_inputs(NULL, NULL, &test, &context);
        if (test) { originals.game = test; originals.context = context; }
#endif
        if (!pr_exposure_select(g_reading_view->compiled, &g_reading_view->bindings, g_reading_view->sources, &originals,
                &report->picks, &report->pick_count, NULL)) return;
        report->picks_served = 1;
    } else if (!g_map_provider && g_current_provider && g_compiled) {
        int ok = 1;
        AcquireSRWLockShared(&g_exposure_lock);
        if (g_exposure_count && !(report->picks = calloc(g_exposure_count, sizeof(*report->picks)))) ok = 0;
        for (size_t i = 0; ok && i < g_exposure_count; i++) {
            pr_exposure_pick *pick = report->picks + i;
            *pick = g_exposure_picks[i];
            pick->name = _strdup(g_exposure_picks[i].name); pick->kept = _strdup(g_exposure_picks[i].kept);
            report->pick_count = i + 1;
            if (!pick->name || !pick->kept) ok = 0;
        }
        ReleaseSRWLockShared(&g_exposure_lock);
        if (!ok) return;
        report->picks_served = 1;
    } else {
        pr_original_source originals = {report->catalog ? sh_resource_catalog_read_path : NULL, (void *)report->catalog,
            report->library->native_assets};
#ifdef SH_PACKAGE_RUNTIME_TESTING
        sh_package_baseline_reader test = NULL; void *context = NULL;
        sh_package_runtime_test_source_inputs(NULL, NULL, &test, &context);
        if (test) { originals.game = test; originals.context = context; }
#endif
        if (!pr_exposure_select(compiled, &report->library->bindings, report->served, &originals,
                &report->picks, &report->pick_count, NULL)) return;
    }
    /* A kept row belongs to one set: the sets are its distinct kept rows. */
    for (size_t i = 0; i < report->pick_count; i++) {
        size_t j = 0;
        while (j < i && strcmp(report->picks[j].kept, report->picks[i].kept)) j++;
        report->pick_sets += j == i;
    }
    report->picks_state = 1;
}
/* An entityDef's edge to an editor row is the lifetime edge to a template
 * describing it (package_library.c pl_label_companion), not a dependency of
 * the entityDef's own: through it every row placing one entityDef would
 * reach the others. */
static int pi_companion(const sh_compiled_resource *from, const sh_compiled_resource *to)
{
    return from->type && to->type && !strcmp(from->type, "entitydef") && !strcmp(to->type, "snapeditorentitydef");
}
/* Every editor row's reach through the bound dependency graph (the files it
 * shows or places, and the rows those reach), for an input's exposures. */
static void pi_reach(pi_report *report)
{
    const sh_package_compilation *compiled = report->compiled;
    size_t total = compiled->resource_count, edge_count = 0, at = 0;
    size_t *edge_start = NULL, *edges = NULL, *queue = NULL;
    int ok = 1;
    report->reach_state = 0;
    if (report->picks_state < 0) pi_select(report);
    if (report->picks_state != 1) return;
    for (size_t r = 0; r < total; r++) {
        if (compiled->resources[r].bound_dependency_count > SIZE_MAX / sizeof(size_t) - edge_count) return;
        edge_count += compiled->resources[r].bound_dependency_count;
    }
    edge_start = calloc(total + 1, sizeof(*edge_start)); edges = calloc(edge_count ? edge_count : 1, sizeof(*edges));
    queue = calloc(total ? total : 1, sizeof(*queue));
    report->tiles = calloc(total ? total : 1, sizeof(*report->tiles));
    report->tile_names = calloc(total ? total : 1, sizeof(*report->tile_names));
    report->tile_class = calloc(total ? total : 1, sizeof(*report->tile_class));
    if (!edge_start || !edges || !queue || !report->tiles || !report->tile_names || !report->tile_class) ok = 0;
    for (size_t r = 0; ok && r < total; r++) {
        const sh_compiled_resource *from = compiled->resources + r;
        edge_start[r] = at;
        for (size_t d = 0; d < from->bound_dependency_count; d++) {
            const sh_compiled_resource *to = sh_package_compilation_find(compiled, from->bound_dependencies[d]);
            if (to && !pi_companion(from, to)) edges[at++] = (size_t)(to - compiled->resources);
        }
        if (from->generated_layer || !from->engine_path || !from->type || strcmp(from->type, "snapeditorentitydef")) continue;
        char *name = pr_exposure_name(from->engine_path);
        if (!name) continue;
        size_t t = report->tile_count++;
        report->tiles[t] = r; report->tile_names[t] = name;
        report->tile_class[t] = pr_exposure_find(report->picks, report->pick_count, name) ? 0 : 2;
        for (size_t i = 0; report->tile_class[t] == 2 && i < report->pick_count; i++)
            if (!strcmp(report->picks[i].kept, name)) report->tile_class[t] = 1;
    }
    if (ok) edge_start[total] = at;
    report->reach_stride = (total + 7) / 8;
    if (ok && report->tile_count && report->reach_stride > SIZE_MAX / report->tile_count) ok = 0;
    if (ok && !(report->reach = calloc(report->tile_count ? report->tile_count * report->reach_stride : 1, 1))) ok = 0;
    for (size_t t = 0; ok && t < report->tile_count; t++) {
        unsigned char *seen = report->reach + t * report->reach_stride;
        size_t head = 0, tail = 0;
        queue[tail++] = report->tiles[t]; seen[report->tiles[t] / 8] |= (unsigned char)(1u << (report->tiles[t] % 8));
        while (head < tail) {
            size_t r = queue[head++];
            for (size_t e = edge_start[r]; e < edge_start[r + 1]; e++) {
                size_t next = edges[e];
                if (seen[next / 8] & (1u << (next % 8))) continue;
                seen[next / 8] |= (unsigned char)(1u << (next % 8)); queue[tail++] = next;
            }
        }
    }
    free(edge_start); free(edges); free(queue);
    report->reach_state = ok;
}
static int pi_tile_reaches(const pi_report *report, size_t tile, size_t row)
{
    return row < report->compiled->resource_count &&
        ((report->reach[tile * report->reach_stride + row / 8] >> (row % 8)) & 1);
}
/* 1 when tile reaches a row serving this served file or generated from it; 2
 * when it is itself one of the rows serving it. */
static int pi_tile_exposes(const pi_report *report, size_t tile, size_t served)
{
    int reached = 0;
    for (size_t at = report->row_start[served]; at < report->row_start[served + 1]; at++) {
        if (report->rows[at] == report->tiles[tile]) return 2;
        reached |= pi_tile_reaches(report, tile, report->rows[at]);
    }
    size_t first = 0, last = 0;
    pi_generated_range(report, served, &first, &last);
    for (size_t g = first; g < last && !reached; g++) reached = pi_tile_reaches(report, tile, report->generated[g].row);
    return reached;
}
static const char *const g_pi_kept[] = {"as a changed row replaces the original's own",
    "as its package comes earlier in library order", "as no package order separates them and its row path sorts first"};
/* The package a changed editor row's binding names first in library order. */
static void pi_row_package(pr_summary *s, const pi_report *report, const char *name)
{
    size_t owner = pr_exposure_owner(&report->library->bindings, report->served, name);
    const sh_package_descriptor *descriptor = owner < report->served->package_count ? pi_descriptor(report->served, owner) : NULL;
    if (descriptor) pr_summary_put(s, " of %s [%s]", descriptor->name, descriptor->id);
}
/* The picker listing an equal exposure decides for one editor row; every
 * names the rows a kept one stands for. Served status is the row's own. */
static void pi_tile_status(pr_summary *s, const pi_report *report, const char *name, int every)
{
    const pr_exposure_pick *pick = pr_exposure_find(report->picks, report->pick_count, name);
    size_t members = 0, named = 0;
    if (pick) {
        pr_summary_put(s, " left out of the pickers for an equal exposure (still served and registered): %s", pick->kept);
        pi_row_package(s, report, pick->kept);
        pr_summary_put(s, " is kept for it, %s", g_pi_kept[pick->rule]);
        return;
    }
    for (size_t i = 0; i < report->pick_count; i++) if (!strcmp(report->picks[i].kept, name)) members = report->picks[i].members;
    if (!members) return;
    pr_summary_put(s, " kept in the pickers for an equal exposure of %zu rows", members);
    for (size_t i = 0; every && i < report->pick_count; i++) {
        if (strcmp(report->picks[i].kept, name)) continue;
        pr_summary_put(s, "%s %s", named++ ? "," : ", standing for", report->picks[i].name);
        if (report->picks[i].rule != PR_KEPT_CHANGE) pi_row_package(s, report, report->picks[i].name);
    }
}
/* One editor row exposing an input, briefly: its name, the row it privately
 * republishes when it is not the input's own row, and its picker listing. */
static void pi_tile_brief(pr_summary *s, const pi_report *report, size_t tile, int own)
{
    const sh_compiled_resource *r = report->compiled->resources + report->tiles[tile];
    pr_summary_put(s, "editor row %s", report->tile_names[tile]);
    if (!own && r->original_path) pr_summary_put(s, " (private alias of %s)", r->original_path);
    pi_tile_status(s, report, report->tile_names[tile], 0);
}
#ifdef SH_PACKAGE_RUNTIME_TESTING
const char *sh_package_runtime_test_exposure_reason(const char *name)
{
    const char *reason = NULL;
    AcquireSRWLockShared(&g_exposure_lock);
    const pr_exposure_pick *pick = pr_exposure_find(g_exposure_picks, g_exposure_count, name);
    if (pick) reason = g_pi_kept[pick->rule];
    ReleaseSRWLockShared(&g_exposure_lock);
    return reason;
}
#endif
static const char *pi_renderer(int renderer)
{
    return renderer == SH_PACKAGE_SHADER_VULKAN ? "Vulkan library" : renderer == SH_PACKAGE_SHADER_OPENGL ?
        "OpenGL library" : "no renderer contract";
}
/* The source link's own reason an unpublished shader input needs no row. */
static void pi_shader_detail(pr_summary *detail, const pr_shader_input *shader)
{
    const char *other = shader->renderer == SH_PACKAGE_SHADER_VULKAN ? "OpenGL" : "Vulkan";
    switch (shader->reason) {
    case SH_PACKAGE_SHADER_UNPUBLISHED_OTHER_RENDERER:
        pr_summary_put(detail, "%s renderer artifact; the %s publishes only its own renderer's shaders (source link)",
            other, pi_renderer(shader->renderer));
        break;
    case SH_PACKAGE_SHADER_UNPUBLISHED_DRIVER_CACHE:
        pr_summary_put(detail, "shader driver cache/debug file; no renderer publishes it (source link, %s)",
            pi_renderer(shader->renderer));
        break;
    case SH_PACKAGE_SHADER_UNPUBLISHED_STOCK_INCLUDE:
        pr_summary_put(detail, "equals the installed SnapMap include and no selected program reads it; kept, not "
            "published (source link, %s)", pi_renderer(shader->renderer));
        break;
    case SH_PACKAGE_SHADER_UNPUBLISHED_DORMANT_PAIR:
        if (shader->pair_original)
            pr_summary_put(detail, "dormant %s permutation declaration: checksum %08x matches the installed original %s "
                "(source link); the %s publishes neither", other, shader->checksum, shader->pair,
                pi_renderer(shader->renderer));
        else
            pr_summary_put(detail, "dormant %s permutation declaration: checksum %08x matches %s | %llu bytes "
                "%02x%02x%02x%02x (source link); the %s publishes neither", other, shader->checksum, shader->pair,
                (unsigned long long)shader->pair_length, shader->pair_digest[0], shader->pair_digest[1],
                shader->pair_digest[2], shader->pair_digest[3], pi_renderer(shader->renderer));
        break;
    default:
        pr_summary_put(detail, "accounted by the source link (reason %d, %s)", shader->reason, pi_renderer(shader->renderer));
    }
}
/* One entry's disposition; detail, when not NULL, receives its evidence. */
static int pi_classify(const pi_report *report, const pi_unit *unit, size_t index, pr_summary *detail)
{
    const sh_package_source_file *file = unit->sources->files + index;
    const sh_package_component *component = unit->sources->components + file->component;
    if (unit->status != PI_SERVED) {
        if (detail) pr_summary_put(detail, "with its whole unit (see the unit's reason)");
        return unit->status;
    }
    if (file->directory) {
        int set = unit->sources == report->inventory->sources ? 0 : 1;
        pi_key key = {file->owner, file->relative, strlen(file->relative), 0};
        int held = report->parent_count[set] && bsearch(&key, report->parents[set], report->parent_count[set],
            sizeof(key), pi_key_order) != NULL;
        if (detail) pr_summary_put(detail, held ? "authored folder, kept with the package" :
            "empty authored folder, kept with the package");
        return PI_FOLDER;
    }
    if (!file->engine_path) {
        const char *local = file->relative + strlen(component->relative);
        if (*local == '/') local++;
        if (!_stricmp(local, "package.json")) {
            if (detail) pr_summary_put(detail, "%s %s [%s]", component->relative[0] ? "nested component" : "package",
                component->descriptor.name, component->descriptor.id);
            return PI_DESCRIPTOR;
        }
        int catalog = report->catalog != NULL;
#ifdef SH_PACKAGE_RUNTIME_TESTING
        catalog = catalog || g_test_catalog_path_count;
#endif
        char *canonical = catalog ? pr_canonical(local) : NULL;
        const sh_resource_catalog_entry *const *entries = NULL;
        size_t known = canonical && report->catalog ? sh_resource_catalog_find_path(report->catalog, canonical, &entries) : 0;
#ifdef SH_PACKAGE_RUNTIME_TESTING
        for (size_t p = 0; canonical && !report->catalog && p < g_test_catalog_path_count; p++)
            known += !_stricmp(g_test_catalog_paths[p], canonical);
#endif
        free(canonical);
        if (known) {
            if (detail) pr_summary_put(detail, "names game resource %s outside assets/, an earlier-release placement "
                "this library does not serve (unsupported legacy layout). Map deliveries are converted automatically; "
                "for a local authoring folder the optional developer tool snapmap-plus migrate-overrides converts it", local);
            return PI_LEGACY;
        }
        if (detail) pr_summary_put(detail, "outside assets/ and not a game resource path; kept with the package");
        return PI_AUTHOR;
    }
    pi_key key = {unit->served, file->relative, strlen(file->relative), 0};
    const pi_key *found = report->served->file_count ? bsearch(&key, report->served_files,
        report->served->file_count, sizeof(key), pi_key_order) : NULL;
    if (!found) {
        if (detail) pr_summary_put(detail, "the served library holds no copy of this file");
        return PI_UNACCOUNTED;
    }
    size_t served = found->index, best = SIZE_MAX, effective = SIZE_MAX;
    int kind = PI_KINDS, differs = 0;
    for (size_t at = report->row_start[served]; at < report->row_start[served + 1]; at++) {
        const sh_compiled_resource *r = report->compiled->resources + report->rows[at];
        size_t source = r->source != SIZE_MAX ? r->source : r->sources[0];
        const sh_package_source_file *other = source < report->served->file_count ? report->served->files + source : NULL;
        int k = r->composed ? PI_COMPOSED : source == served ? PI_SERVED :
            other && other->length == file->length && !memcmp(other->digest, file->digest, 32) ? PI_SHARED : PI_OVERLAP;
        if (k < kind) { kind = k; best = report->rows[at]; effective = source; }
        for (size_t q = 0; q < r->source_count && !differs; q++) {
            const sh_package_source_file *listed = r->sources[q] < report->served->file_count ?
                report->served->files + r->sources[q] : NULL;
            differs = listed && (listed->length != file->length || memcmp(listed->digest, file->digest, 32));
        }
    }
    char *canonical = pr_canonical(file->engine_path);
    /* A generated row names input paths, but only the files its producer
     * actually read are its inputs: another package's file at the same path,
     * or one the row's scope never saw, is not. */
    size_t first = 0, last = 0, readers = 0, reader[3] = {0};
    pi_generated_range(report, served, &first, &last);
    for (size_t g = first; g < last; g++) {
        if (readers < 3) reader[readers] = report->generated[g].row;
        readers++;
    }
    if (kind == PI_KINDS && readers) kind = PI_GENERATED;
    const pr_unchanged *unchanged = NULL;
    if (kind == PI_KINDS && canonical && report->library->unchanged_count) {
        pr_unchanged probe = {canonical, file->length, {0}};
        memcpy(probe.digest, file->digest, 32);
        unchanged = bsearch(&probe, report->library->unchanged, report->library->unchanged_count,
            sizeof(probe), pr_unchanged_order);
        if (unchanged) kind = PI_UNCHANGED;
    }
    /* Only the link's record for this package's exact file explains it; a
     * shader-like path alone never does. */
    const pr_shader_input *shader = NULL;
    if (kind == PI_KINDS && report->library->shader_input_count && report->served->fingerprints) {
        pr_shader_input probe = {{0}};
        memcpy(probe.owner, report->served->fingerprints[unit->served], 32);
        probe.relative = (char *)file->relative; probe.length = file->length; memcpy(probe.digest, file->digest, 32);
        shader = bsearch(&probe, report->library->shader_inputs, report->library->shader_input_count,
            sizeof(probe), pr_shader_input_order);
        if (shader) kind = PI_SHADER;
    }
    /* A row listing this file may serve the union its library composed from
     * several packages' contributions (editor fields, registration lists): only
     * the library's record for this exact file says so. Without the records a
     * different-bytes row cannot name what it serves for this file. */
    const pr_composed_input *composition = NULL;
    int composition_unknown = 0;
    if ((kind == PI_SERVED || kind == PI_SHARED || kind == PI_OVERLAP) && report->library->composed_input_count &&
        report->served->fingerprints) {
        pr_composed_input probe = {{0}};
        memcpy(probe.owner, report->served->fingerprints[unit->served], 32);
        probe.relative = (char *)file->relative; probe.length = file->length; memcpy(probe.digest, file->digest, 32);
        composition = bsearch(&probe, report->library->composed_inputs, report->library->composed_input_count,
            sizeof(probe), pr_composed_input_order);
        if (composition) kind = PI_COMPOSED;
    }
    if (!composition && report->library->composed_inputs_lost && (kind == PI_OVERLAP || (kind == PI_SERVED && differs))) {
        kind = PI_UNACCOUNTED; composition_unknown = 1;
    }
    if (kind == PI_KINDS) kind = PI_UNACCOUNTED;
    char refusal[1024];
    if (detail) {
        size_t start = detail->length, rows = report->row_start[served + 1] - report->row_start[served], shown = 0;
        if (kind == PI_SHARED || kind == PI_OVERLAP) {
            const sh_package_source_file *other = report->served->files + effective;
            const sh_package_descriptor *owner = pi_descriptor(report->served, other->owner);
            pr_summary_put(detail, "%s %s [%s] %s", kind == PI_SHARED ? "same bytes as" : "different bytes; served from",
                owner ? owner->name : report->served->packages[other->owner].name, owner ? owner->id : "?", other->relative);
        } else if (kind == PI_COMPOSED && composition) {
            pr_summary_put(detail, "composed with %s: the library composes this file's contribution with theirs, so "
                "the row serves their union", composition->peers && *composition->peers ? composition->peers :
                "other packages' contributions");
        } else if (kind == PI_UNACCOUNTED && composition_unknown) {
            pr_summary_put(detail, "the row also lists other packages' different bytes, and composition records were not "
                "retained, so what it serves for this file is not known");
        } else if (kind == PI_UNCHANGED) {
            pr_summary_put(detail, "equals the installed SnapMap original at %s; the game serves it", canonical);
        } else if (kind == PI_SHADER) {
            pi_shader_detail(detail, shader);
        } else if (kind == PI_UNACCOUNTED && canonical &&
            sh_package_native_assets_page_refusal(report->served->packages[unit->served].name, canonical, refusal, sizeof(refusal))) {
            pr_summary_put(detail, "left out: %s", refusal);
        } else if (kind == PI_UNACCOUNTED) {
            pr_summary_put(detail, "no served row, generated use or unchanged-original record%s%s (missing product coverage)",
                report->library->unchanged_lost ? "; unchanged-original records were not retained" : "",
                report->library->shader_inputs_lost ? "; shader accounting records were not retained" : "");
        }
        if (best != SIZE_MAX) {
            pr_summary_put(detail, "%srow", detail->length > start ? "; " : "");
            pi_row(detail, report->compiled->resources + best); shown++;
            for (size_t at = report->row_start[served]; at < report->row_start[served + 1] && shown < 3; at++)
                if (report->rows[at] != best) {
                    pr_summary_put(detail, ";"); pi_row(detail, report->compiled->resources + report->rows[at]); shown++;
                }
            if (rows > shown) pr_summary_put(detail, "; %zu more rows", rows - shown);
        }
        for (size_t g = 0; g < readers && g < 3; g++) {
            pr_summary_put(detail, "%sread by generated", detail->length > start ? "; " : "");
            pi_row(detail, report->compiled->resources + reader[g]);
        }
        if (readers > 3) pr_summary_put(detail, "; %zu more generated rows", readers - 3);
        /* The editor rows exposing it, those an equal exposure leaves out of
         * the pickers first, then those it keeps; a row of its own only then. */
        size_t tiles = 0, tiles_shown = 0;
        for (int pass = 0; report->reach_state == 1 && pass < 3; pass++)
            for (size_t t = 0; t < report->tile_count; t++) {
                int exposes = report->tile_class[t] == pass ? pi_tile_exposes(report, t, served) : 0;
                if (!exposes || (exposes == 2 && pass == 2)) continue;
                if (tiles++ >= 3) continue;
                pr_summary_put(detail, "%s", detail->length > start ? "; " : "");
                pi_tile_brief(detail, report, t, exposes == 2); tiles_shown++;
            }
        if (tiles > tiles_shown) pr_summary_put(detail, "; %zu more editor rows", tiles - tiles_shown);
        if (rows > 3 || readers > 3 || tiles > 3 || (best != SIZE_MAX &&
            sh_package_resource_native_count(report->compiled->resources + best) > 1))
            pr_summary_put(detail, "; 'sh_packages exposures' lists all");
    }
    free(canonical);
    return kind;
}
static void pi_count(pi_report *report)
{
    for (size_t u = 0; u < report->unit_count; u++) {
        pi_unit *unit = report->units + u;
        for (size_t i = 0; i < unit->sources->file_count; i++) {
            const sh_package_source_file *file = unit->sources->files + i;
            if (file->owner != unit->owner) continue;
            int kind = pi_classify(report, unit, i, NULL);
            unit->counts[kind]++;
            if (file->directory) {
                int set = unit->sources == report->inventory->sources ? 0 : 1;
                pi_key key = {file->owner, file->relative, strlen(file->relative), 0};
                unit->folders++;
                unit->empty += !report->parent_count[set] || !bsearch(&key, report->parents[set],
                    report->parent_count[set], sizeof(key), pi_key_order);
            } else unit->files++;
        }
    }
}
static void pi_counts(pr_summary *s, const size_t *counts)
{
    int listed = 0;
    for (int k = 0; k < PI_KINDS; k++)
        if (counts[k]) pr_summary_put(s, "%s%s %zu", listed++ ? ", " : "", g_pi_kinds[k], counts[k]);
    if (!listed) pr_summary_put(s, "no entries");
}
static void pi_unit_line(pr_summary *s, const pi_unit *unit)
{
    const sh_package_descriptor *descriptor = pi_descriptor(unit->sources, unit->owner);
    pr_summary_put(s, "%s [%s] (%s): %s; %zu files, %zu folders (%zu empty), %zu components: ",
        descriptor ? descriptor->name : "Package", descriptor ? descriptor->id : "?", unit->sources->packages[unit->owner].name,
        unit->status == PI_SERVED ? "served library" : g_pi_kinds[unit->status], unit->files, unit->folders,
        unit->empty, unit->components);
    pi_counts(s, unit->counts);
    pr_summary_put(s, "\n");
    if (unit->reason) pr_summary_put(s, "  %.*s\n", (int)strcspn(unit->reason, "\n"), unit->reason);
    else if (unit->status == PI_MALFORMED) pr_summary_put(s, "  Left out for invalid content; its report line is not retained.\n");
    else if (unit->status == PI_UNACCOUNTED)
        pr_summary_put(s, "  Installed, but the served library neither serves it nor records why (missing product coverage).\n");
}
static void pi_entry(pr_summary *s, const pi_report *report, const pi_unit *unit, size_t index, size_t row, int named)
{
    const sh_package_source_file *file = unit->sources->files + index;
    pr_summary_put(s, "  %zu. ", row);
    if (named) pr_summary_put(s, "%s/", unit->sources->packages[unit->owner].name);
    if (file->directory) pr_summary_put(s, "%s/ | ", file->relative);
    else pr_summary_put(s, "%s | %llu bytes %02x%02x%02x%02x | ", file->relative, (unsigned long long)file->length,
        file->digest[0], file->digest[1], file->digest[2], file->digest[3]);
    pr_summary detail = {0};
    int kind = pi_classify(report, unit, index, &detail);
    if (detail.failed) s->failed = 1;
    pr_summary_put(s, "%s: %s\n", g_pi_kinds[kind], detail.text ? detail.text : "");
    free(detail.text);
}
/* Whether some unit is the package a report line names. */
static int pi_line_has_unit(const pi_report *report, const char *line, size_t length)
{
    static const char prefix[] = "Skipped local package ";
    const char *root = line + sizeof(prefix) - 1, *end;
    if (length < sizeof(prefix) - 1 || strncmp(line, prefix, sizeof(prefix) - 1)) return 0;
    for (end = root; end + 1 < line + length && (end[0] != ':' || end[1] != ' '); end++);
    for (size_t u = 0; u < report->unit_count; u++) {
        const char *unit = report->units[u].sources->packages[report->units[u].owner].root;
        if (strlen(unit) == (size_t)(end - root) && !strncmp(unit, root, (size_t)(end - root))) return 1;
    }
    return 0;
}
char *sh_package_runtime_inputs(const char *query, size_t first)
{
    pr_summary s = {0};
    pi_report report;
    AcquireSRWLockShared(&g_lock);
    if (!pi_build(&report)) { pr_summary_put(&s, "Input accounting is unavailable: out of memory.\n"); goto done; }
    if (!report.library) {
        pr_summary_put(&s, "No installed library is served yet%s%s.\n", g_error[0] ? ": " : "", g_error);
        goto done;
    }
    pi_count(&report);
    if (query && *query) pi_reach(&report); else pi_select(&report);
    size_t totals[PI_KINDS] = {0}, files = 0, folders = 0, empty = 0, components = 0;
    for (size_t u = 0; u < report.unit_count; u++) {
        for (int k = 0; k < PI_KINDS; k++) totals[k] += report.units[u].counts[k];
        files += report.units[u].files; folders += report.units[u].folders;
        empty += report.units[u].empty; components += report.units[u].components;
    }
    if (!query || !*query) {
        size_t attention = 0, listed = 0;
        pr_summary_put(&s, "Installed inputs: %zu files and %zu folders (%zu empty) in %zu delivery units with %zu "
            "components; the served library compiles %zu units.\n", files, folders, empty, report.unit_count, components,
            report.served->package_count);
        pr_summary_put(&s, "Dispositions: "); pi_counts(&s, totals); pr_summary_put(&s, ".\n");
        for (size_t u = 0; u < report.unit_count; u++) {
            pi_unit_line(&s, report.units + u);
            attention += report.units[u].counts[PI_UNACCOUNTED] + report.units[u].counts[PI_LEGACY];
        }
        if (report.library->unchanged_lost)
            pr_summary_put(&s, "Unchanged-original records were not retained; inputs they explain show as unaccounted.\n");
        if (report.library->shader_inputs_lost)
            pr_summary_put(&s, "Shader accounting records were not retained; inputs they explain show as unaccounted.\n");
        if (report.library->composed_inputs_lost)
            pr_summary_put(&s, "Composition records were not retained; inputs whose rows list other packages' different "
                "bytes show as unaccounted.\n");
        if (report.inventory->left_out_lost)
            pr_summary_put(&s, "The files of units left out for invalid content could not be retained for this report.\n");
        if (report.picks_state != 1) pr_summary_put(&s, "Equal exposures could not be listed: out of memory.\n");
        else if (report.pick_count)
            pr_summary_put(&s, "Equal exposures%s: %zu set%s keep%s one editor row each in the pickers; %zu other row%s "
                "left out of them stay%s served and registered. 'sh_packages inputs <package>' names each.\n",
                report.picks_served ? "" : " of the installed library (the active map's composition is served now and "
                "selects its own)", report.pick_sets, report.pick_sets == 1 ? "" : "s", report.pick_sets == 1 ? "s" : "",
                report.pick_count, report.pick_count == 1 ? "" : "s", report.pick_count == 1 ? "s" : "");
        for (const char *line = report.library->rejections; line && *line; ) {
            const char *end = strchr(line, '\n');
            size_t length = end ? (size_t)(end - line) : strlen(line);
            if (!pi_line_has_unit(&report, line, length))
                pr_summary_put(&s, "Unit rejected before its files were inventoried: %.*s\n", (int)length, line);
            line = end ? end + 1 : NULL;
        }
        if (attention) pr_summary_put(&s, "Inputs needing attention (%zu):\n", attention);
        for (size_t u = 0; u < report.unit_count && listed < PI_LISTED; u++) {
            const pi_unit *unit = report.units + u;
            if (unit->status != PI_SERVED || !(unit->counts[PI_UNACCOUNTED] + unit->counts[PI_LEGACY])) continue;
            for (size_t i = 0; i < unit->sources->file_count && listed < PI_LISTED; i++) {
                if (unit->sources->files[i].owner != unit->owner) continue;
                int kind = pi_classify(&report, unit, i, NULL);
                if (kind == PI_UNACCOUNTED || kind == PI_LEGACY) pi_entry(&s, &report, unit, i, ++listed, 1);
            }
        }
        if (attention > listed) pr_summary_put(&s, "  %zu more; list a package to see them.\n", attention - listed);
        if (report.library->coverage) pr_summary_put(&s, "Coverage notes (packages still served):\n%s", report.library->coverage);
        pr_summary_put(&s, "'sh_packages inputs <package id or folder> [first row]' lists every input with its exposures; "
            "'sh_packages inputs <path>' finds a path in every package.\n");
        goto done;
    }
    size_t row = 0, shown = 0, matched = 0;
    if (!first) first = 1;
    if (report.reach_state != 1) pr_summary_put(&s, "Editor-row exposures could not be listed: out of memory.\n");
    for (size_t u = 0; u < report.unit_count; u++) {
        const pi_unit *unit = report.units + u;
        const sh_package_descriptor *descriptor = pi_descriptor(unit->sources, unit->owner);
        if (_stricmp(unit->sources->packages[unit->owner].name, query) && (!descriptor || _stricmp(descriptor->id, query)))
            continue;
        matched++;
        pi_unit_line(&s, unit);
        for (size_t i = 0; i < unit->sources->file_count; i++) {
            if (unit->sources->files[i].owner != unit->owner) continue;
            if (++row < first || shown >= PI_PAGE) continue;
            pi_entry(&s, &report, unit, i, row, 0); shown++;
        }
    }
    if (!matched) {
        for (size_t u = 0; u < report.unit_count; u++) {
            const pi_unit *unit = report.units + u;
            for (size_t i = 0; i < unit->sources->file_count; i++) {
                const sh_package_source_file *file = unit->sources->files + i;
                if (file->owner != unit->owner || (_stricmp(file->relative, query) &&
                    (!file->engine_path || _stricmp(file->engine_path, query)))) continue;
                if (++row < first || shown >= PI_PAGE) continue;
                pi_entry(&s, &report, unit, i, row, 1); shown++;
            }
        }
        if (!row) pr_summary_put(&s, "No installed package or input matches %s.\n", query);
    }
    if (row) {
        pr_summary_put(&s, "Rows %zu-%zu of %zu.", shown ? first : 0, shown ? first + shown - 1 : 0, row);
        if (shown && first + shown <= row) pr_summary_put(&s, " Next: sh_packages inputs %s %zu", query, first + shown);
        pr_summary_put(&s, "\n");
    }
done:
    pi_free(&report);
    ReleaseSRWLockShared(&g_lock);
    if (s.failed) { free(s.text); return NULL; }
    return s.text;
}
/* Whether entry index of unit is listed by query (sh_package_runtime_inputs). */
static int pi_matches(const pi_unit *unit, size_t index, const char *query, int by_unit)
{
    const sh_package_source_file *file = unit->sources->files + index;
    if (by_unit) return 1;
    return !_stricmp(file->relative, query) || (file->engine_path && !_stricmp(file->engine_path, query));
}
static int pi_unit_matches(const pi_unit *unit, const char *query)
{
    const sh_package_descriptor *descriptor = pi_descriptor(unit->sources, unit->owner);
    return !_stricmp(unit->sources->packages[unit->owner].name, query) || (descriptor && !_stricmp(descriptor->id, query));
}
static void pi_exposure(pr_summary *s, const sh_compiled_resource *r, const char *role, size_t *line, size_t first)
{
    size_t names = sh_package_resource_native_count(r);
    if (++*line >= first && *line < first + PI_PAGE) {
        pr_summary_put(s, "  %zu. %s", *line, role); pi_row(s, r); pr_summary_put(s, "\n");
    }
    for (size_t n = 0; n < names; n++) {
        sh_package_native_identity identity = sh_package_resource_native_at(r, n);
        if (++*line >= first && *line < first + PI_PAGE)
            pr_summary_put(s, "  %zu.   identity %s %s\n", *line, identity.type ? identity.type : "?", identity.name ? identity.name : "?");
    }
}
char *sh_package_runtime_input_exposures(const char *query, size_t entry, size_t first)
{
    pr_summary s = {0};
    pi_report report;
    size_t row = 0, line = 0;
    int by_unit = 0, found = 0;
    if (!first) first = 1;
    AcquireSRWLockShared(&g_lock);
    if (!pi_build(&report)) { pr_summary_put(&s, "Input accounting is unavailable: out of memory.\n"); goto done; }
    if (!report.library || !query || !*query) { pr_summary_put(&s, "No installed library is served yet, or no query.\n"); goto done; }
    pi_reach(&report);
    if (report.reach_state != 1) pr_summary_put(&s, "Editor-row exposures could not be listed: out of memory.\n");
    for (size_t u = 0; u < report.unit_count && !by_unit; u++) by_unit = pi_unit_matches(report.units + u, query);
    for (size_t u = 0; u < report.unit_count && !found; u++) {
        const pi_unit *unit = report.units + u;
        if (by_unit && !pi_unit_matches(unit, query)) continue;
        for (size_t i = 0; i < unit->sources->file_count && !found; i++) {
            const sh_package_source_file *file = unit->sources->files + i;
            if (file->owner != unit->owner || !pi_matches(unit, i, query, by_unit) || ++row != entry) continue;
            found = 1;
            pi_entry(&s, &report, unit, i, row, !by_unit);
            if (unit->status != PI_SERVED || file->directory || !file->engine_path) break;
            pi_key key = {unit->served, file->relative, strlen(file->relative), 0};
            const pi_key *served = report.served->file_count ? bsearch(&key, report.served_files,
                report.served->file_count, sizeof(key), pi_key_order) : NULL;
            if (served) for (size_t at = report.row_start[served->index]; at < report.row_start[served->index + 1]; at++)
                pi_exposure(&s, report.compiled->resources + report.rows[at], "row", &line, first);
            size_t from = 0, to = 0;
            if (served) pi_generated_range(&report, served->index, &from, &to);
            for (size_t g = from; g < to; g++)
                pi_exposure(&s, report.compiled->resources + report.generated[g].row, "read by generated", &line, first);
            for (int pass = 0; served && report.reach_state == 1 && pass < 3; pass++)
                for (size_t t = 0; t < report.tile_count; t++) {
                    int exposes = report.tile_class[t] == pass ? pi_tile_exposes(&report, t, served->index) : 0;
                    if (!exposes || (exposes == 2 && pass == 2) || !(++line >= first && line < first + PI_PAGE)) continue;
                    pr_summary_put(&s, "  %zu. editor row", line); pi_row(&s, report.compiled->resources + report.tiles[t]);
                    pr_summary_put(&s, ":"); pi_tile_status(&s, &report, report.tile_names[t], 1);
                    if (report.tile_class[t] == 2) pr_summary_put(&s, " exposes it");
                    pr_summary_put(&s, "\n");
                }
        }
    }
    if (!found) pr_summary_put(&s, "No entry %zu matches %s.\n", entry, query);
    else {
        size_t last = line < first ? 0 : line < first + PI_PAGE - 1 ? line : first + PI_PAGE - 1;
        pr_summary_put(&s, "Exposure lines %zu-%zu of %zu.", last ? first : 0, last, line);
        if (last && last < line) pr_summary_put(&s, " Next: sh_packages exposures %s %zu %zu", query, entry, last + 1);
        pr_summary_put(&s, "\n");
    }
done:
    pi_free(&report);
    ReleaseSRWLockShared(&g_lock);
    if (s.failed) { free(s.text); return NULL; }
    return s.text;
}
/* Disposition totals for the summary, or 0 when no library is served. */
static int pi_summary_line(pr_summary *s)
{
    pi_report report;
    int ok = pi_build(&report);
    if (ok && report.library) {
        size_t totals[PI_KINDS] = {0}, files = 0, folders = 0;
        pi_count(&report);
        for (size_t u = 0; u < report.unit_count; u++) {
            for (int k = 0; k < PI_KINDS; k++) totals[k] += report.units[u].counts[k];
            files += report.units[u].files; folders += report.units[u].folders;
        }
        pr_summary_put(s, "Inputs: %zu files and %zu folders in %zu units: ", files, folders, report.unit_count);
        pi_counts(s, totals);
        pr_summary_put(s, ". 'sh_packages inputs' accounts for each.\n");
        if (totals[PI_LEGACY]) pr_summary_put(s, "%zu files name game resources outside assets/, an earlier-release "
            "placement this library does not serve (unsupported legacy layout); 'sh_packages inputs' names them.\n",
            totals[PI_LEGACY]);
    } else if (!ok) pr_summary_put(s, "Input accounting is unavailable: out of memory.\n");
    pi_free(&report);
    return ok;
}
void sh_package_runtime_release(void) { ReleaseSRWLockShared(&g_lock); }


int sh_package_runtime_read_captured(const char *engine_path, unsigned char **body, size_t *length,
    const char *family, const char *name, sh_package_resource_capture **capture)
{
    const sh_compiled_resource *resource;
    char error[1024] = "";
    int result = 0;
    if (body) *body = NULL;
    if (length) *length = 0;
    if (!body || !length) return -1;
    int refresh_entered = capture && !g_activation_callback && !pr_refresh_held();
    if (refresh_entered) pr_refresh_acquire(1);
    AcquireSRWLockShared(&g_lock);
    resource = pr_find_engine(pr_reader_compiled(), engine_path);
    if (resource) {
        *body = sh_package_compilation_read_served(pr_reader_compiled(), resource, (size_t)PTRDIFF_MAX,
                                            length, error, sizeof(error));
        result = *body ? 1 : -1;
        if (result > 0 && resource->generated) {
            sh_resource_graph_frame frame;
            size_t i;
            /* Keep producer edges even for a preview read outside a native
             * parse. The held snapshot owns every path until recording ends. */
            sh_resource_graph_begin(&frame, "", engine_path);
            for (i = 0; i < resource->generated_input_count; i++)
                sh_resource_graph_file(resource->generated_inputs[i]);
            sh_resource_graph_end(&frame, 1);
        }
    }
    if (result > 0 && capture && !*capture)
        *capture = pr_resource_capture_locked(resource, family, name, 1);
    ReleaseSRWLockShared(&g_lock);
    if (refresh_entered) pr_refresh_release(1);
    if (result < 0) backend_log(error[0] ? error : "compiled package resource read failed");
    return result;
}
int sh_package_runtime_read(const char *engine_path, unsigned char **body, size_t *length)
{ return sh_package_runtime_read_captured(engine_path, body, length, NULL, NULL, NULL); }

static char *pr_policy_section(const sh_package_policy *policy, const char *section, size_t *length)
{
    const sh_json_object *object = NULL;
    if (length) *length = 0;
    if (policy && section && length) {
        if (!strcmp(section, "requirements")) object = &policy->requirements;
        if (!strcmp(section, "strings")) object = &policy->strings;
        if (!strcmp(section, "hud")) object = &policy->hud;
    }
    return object ? sh_json_serialize_object(object, 0, length) : NULL;
}

int sh_package_runtime_open_file_captured(const char *engine_path, FILE **stream, uint64_t *length,
    const char *family, const char *name, sh_package_resource_capture **capture)
{
    const sh_compiled_resource *resource;
    char error[1024] = "";
    int result = 0;
    if (stream) *stream = NULL;
    if (length) *length = 0;
    if (!stream || !length) return -1;
    int refresh_entered = capture && !g_activation_callback && !pr_refresh_held();
    if (refresh_entered) pr_refresh_acquire(1);
    AcquireSRWLockShared(&g_lock);
    resource = pr_find_engine(g_compiled, engine_path);
    if (resource && !resource->body && !resource->body_owner && !resource->installed_alias) {
        result = -1;
        *stream = sh_package_file_open(resource->cache_file, length, error, sizeof(error));
        if (*stream) result = 1;
    }
    if (result > 0 && capture && !*capture)
        *capture = pr_resource_capture_locked(resource, family, name, 1);
    ReleaseSRWLockShared(&g_lock);
    if (refresh_entered) pr_refresh_release(1);
    if (result < 0) backend_log(error[0] ? error : "package resource cache is unavailable");
    return result;
}
int sh_package_runtime_open_file(const char *engine_path, FILE **stream, uint64_t *length)
{ return sh_package_runtime_open_file_captured(engine_path, stream, length, NULL, NULL, NULL); }

int sh_package_runtime_module_variants(char ***names, size_t *count)
{
    size_t n = 0, at = 0;
    char **out = NULL;
    int ok = 1;
    if (names) *names = NULL;
    if (count) *count = 0;
    if (!names || !count) return 0;
    AcquireSRWLockShared(&g_lock);
    for (int pass = 0; ok && pass < 2; pass++) {
        for (size_t i = 0; g_compiled && i < g_compiled->resource_count; i++) {
            const sh_compiled_resource *resource = g_compiled->resources + i;
            if (!resource->engine_path || !resource->native_type || strcmp(resource->native_type, "snapmodule") ||
                strncmp(resource->engine_path, "maps/modules/smp/", 17)) continue;
            if (!pass) { n++; continue; }
            if (!(out[at] = _strdup(resource->engine_path))) { ok = 0; break; }
            at++;
        }
        if (!pass && n && !(out = calloc(n, sizeof(*out)))) ok = 0;
    }
    ReleaseSRWLockShared(&g_lock);
    if (!ok) { sh_package_runtime_module_variants_free(out, at); return 0; }
    *names = out; *count = at;
    return 1;
}

void sh_package_runtime_module_variants_free(char **names, size_t count)
{
    for (size_t i = 0; names && i < count; i++) free(names[i]);
    free(names);
}

char *sh_package_runtime_policy(const char *section, size_t *length)
{
    const sh_package_compilation *compiled = sh_package_runtime_acquire();
    char *out = pr_policy_section(compiled ? &compiled->policy : NULL, section, length);
    sh_package_runtime_release(); return out;
}

/* Selection does not manufacture a new closure proof from live observations.
 * It can only preserve a source inspection for the same map bytes when every
 * additional observed path is already covered. Changed edits need inspection. */
static int pr_selection_keeps_requirements(const pr_provider *map,
    const char *json, size_t length, const sh_package_references *references)
{
    sh_package_file_identity identity;
    if (!map->requirements_known || !json || length != map->required_map.length ||
        !sh_package_bytes_identity(json, length, &identity) ||
        memcmp(identity.digest, map->required_map.digest, sizeof(identity.digest)) ||
        (references && references->incomplete) || !pr_pool_settings_current(map)) return 0;
    for (size_t i = 0; references && i < references->count; i++) {
        sh_package_references one = {&references->items[i], 1, 0}, observed = {0};
        const char *type = references->items[i].type;
        int covered = 1;
        if (!_strnicmp(type, "snapeditor", 10) || !_strnicmp(type, "snappropertyinspector", 21)) continue;
        if (!sh_package_map_resources(map->compiled, map->catalog, "{}", 2, &one, &observed) ||
            !observed.count) covered = 0;
        for (size_t j = 0; covered && j < observed.count; j++) {
            size_t found;
            for (found = 0; found < map->required_paths.count; found++)
                if (!strcmp(observed.items[j].name, map->required_paths.items[found].name)) break;
            if (found == map->required_paths.count) covered = 0;
        }
        sh_package_references_free(&observed);
        if (!covered) return 0;
    }
    return 1;
}

int sh_package_runtime_select_map_occurrences(const char *json, size_t length,
    const sh_package_references *references, const sh_package_occurrence_snapshot *document,
    char *error, size_t capacity)
{
    sh_package_policy selected = {0}, old_policy;
    sh_package_references copied_references = {0}, old_references;
    char *copy = NULL, *old_json;
    int ok = 0;
    size_t i;
    sh_package_owners owners = {0};
    sh_package_provenance promoted = {0};
    if (error && capacity) error[0] = 0;
    const sh_package_provenance *uses = sh_package_occurrence_provenance(document);
    if (uses && (!json || uses->semantics != SH_PACKAGE_PROVENANCE_USES ||
        !sh_package_provenance_select_uses(uses, NULL, NULL, &promoted))) return 0;
    if (json) {
        if (!length || length == SIZE_MAX || !(copy = (char *)malloc(length + 1))) {
            if (error && capacity) snprintf(error, capacity, "cannot retain map package context");
            sh_package_provenance_free(&promoted); return 0;
        }
        memcpy(copy, json, length); copy[length] = 0;
        if (references) {
            copied_references.incomplete = references->incomplete;
            for (i = 0; i < references->count; i++)
                if (!sh_package_references_add(&copied_references, references->items[i].type,
                                                references->items[i].name)) {
                    free(copy); sh_package_references_free(&copied_references);
                    if (error && capacity) snprintf(error, capacity, "cannot retain map resource references");
                    sh_package_provenance_free(&promoted); return 0;
                }
        }
    } else if (length || (references && references->count)) { sh_package_provenance_free(&promoted); return 0; }
    double phase = pr_read_now();
    PR_LOCK_EXCLUSIVE();
    g_phase_stats.select_lock_ms += pr_read_now() - phase; phase = pr_read_now();
    if (g_activating || g_native_preparing) {
        if (error && capacity) snprintf(error, capacity, "package activation is in progress; retry map preparation");
        goto done;
    }
    if (copy) {
        sh_package_sources empty_sources = {0};
        sh_package_compilation empty = {0};
        empty.sources = &empty_sources;
        if (!(g_current_provider ? pr_exact_policy(g_current_provider, uses ? &promoted : &g_promoted, copy, length,
                &copied_references, &selected, &owners, error, capacity) :
            sh_package_map_policy(&empty, g_catalog, copy, length,
                &copied_references, &selected, &owners, NULL, error, capacity))) goto done;
    }
    g_phase_stats.select_policy_ms += pr_read_now() - phase; phase = pr_read_now();
    old_json = g_map_json; old_policy = g_map_policy;
    g_map_json = copy; g_map_length = length; g_map_policy = selected;
    if (uses || !json) {
        sh_package_provenance_free(&g_promoted); g_promoted = promoted; memset(&promoted, 0, sizeof(promoted));
        g_promotion_generation++;
        pr_lease_foreign();
        pr_lease_changed();
    }
    old_references = g_map_references; g_map_references = copied_references;
    copied_references = old_references;
    if (g_map_provider && !pr_selection_keeps_requirements(g_map_provider, copy, length, &g_map_references))
        InterlockedExchange(&g_map_provider->requirements_known, 0);
    g_phase_stats.select_requirements_ms += pr_read_now() - phase;
    copy = old_json; selected = old_policy; ok = 1;
done:
    PR_UNLOCK_EXCLUSIVE();
    free(copy); sh_package_policy_free(&selected); sh_package_references_free(&copied_references);
    if (ok) {
        char line[160];
        snprintf(line, sizeof(line), "package policy: %s; %llu gameplay package(s)",
                 json ? "map selected" : "map cleared", (unsigned long long)sh_package_owners_count(&owners));
        backend_log(line);
    }
    sh_package_owners_free(&owners); sh_package_provenance_free(&promoted);
    return ok;
}
int sh_package_runtime_select_map(const char *json, size_t length,
    const sh_package_references *references, char *error, size_t capacity)
{ return sh_package_runtime_select_map_occurrences(json, length, references, NULL, error, capacity); }

char *sh_package_runtime_active_policy(const char *section, size_t *length)
{
    char *out;
    AcquireSRWLockShared(&g_lock);
    out = pr_policy_section(&g_map_policy, section, length);
    ReleaseSRWLockShared(&g_lock);
    return out;
}

static char *pr_decl_alias_path(const char *alias)
{
    char *path, *key;
    size_t n;
    if (!alias) return NULL;
    key = sh_package_engine_path(alias);
    if (!key || strncmp(key, "decltree/", 9)) { free(key); return NULL; }
    n = strlen(key);
    if (n > SIZE_MAX - 8u) { free(key); return NULL; }
    path = (char *)malloc(n + 8u);
    if (path) snprintf(path, n + 8u, "generated/decls/%s", key + 9);
    free(key);
    return path;
}

int sh_package_runtime_decl_alias_exists(const char *alias)
{
    const sh_compiled_resource *resource;
    char *path = pr_decl_alias_path(alias);
    int exists;
    if (!path) return 0;
    AcquireSRWLockShared(&g_lock);
    resource = g_compiled ? sh_package_compilation_find(g_compiled, path) : NULL;
    exists = resource && resource->type && (resource->body || resource->body_owner);
    ReleaseSRWLockShared(&g_lock);
    free(path);
    return exists;
}

int sh_package_runtime_read_decl_alias_captured(const char *alias, unsigned char **body, size_t *length,
    const char *family, const char *name, sh_package_resource_capture **capture)
{
    const sh_compiled_resource *resource;
    char *path;
    char error[1024] = "";
    int result = -1;
    if (body) *body = NULL;
    if (length) *length = 0;
    if (!body || !length || !(path = pr_decl_alias_path(alias))) return -1;
    int refresh_entered = capture && !g_activation_callback && !pr_refresh_held();
    if (refresh_entered) pr_refresh_acquire(1);
    AcquireSRWLockShared(&g_lock);
    resource = g_compiled ? sh_package_compilation_find(g_compiled, path) : NULL;
    if (resource && resource->type) {
        *body = sh_package_compilation_read_served(g_compiled, resource, (size_t)INT_MAX, length, error, sizeof(error));
        result = *body ? 1 : -1;
    }
    if (result > 0 && capture && !*capture)
        *capture = pr_resource_capture_locked(resource, family, name, 1);
    /* Removed SnapMap originals are explicit restoration entries in the
     * compilation. Historical aliases cannot admit another resource or revive
     * a failed first activation after its provider was rolled back to NULL. */
    ReleaseSRWLockShared(&g_lock);
    if (refresh_entered) pr_refresh_release(1);
    free(path);
    return result;
}
int sh_package_runtime_read_decl_alias(const char *alias, unsigned char **body, size_t *length)
{ return sh_package_runtime_read_decl_alias_captured(alias, body, length, NULL, NULL, NULL); }

/* All callbacks below read retained data or native reflection. They must not
 * load declarations while the provider is acquired. Native construction stays
 * in the admitted activation route. */
/* Every code a provider's registration keys hold, from its key bindings. */
static void pr_key_taken(const pr_provider *provider, sh_package_key_set *taken)
{
    for (size_t i = 0; provider && i < provider->bindings.binding_count; i++) {
        const sh_package_provenance_binding *binding = provider->bindings.bindings + i;
        sh_package_key_set held;
        char *end = NULL;
        unsigned long value;
        if (strcmp(binding->family, SH_PACKAGE_KEY_FAMILY)) continue;
        value = strtoul(binding->name, &end, 10);
        if (!end || *end || value > 0xfffffffful) continue;
        sh_package_key_decode(NULL, (uint32_t)value, &held);
        for (size_t w = 0; w < sizeof(held.words) / sizeof(held.words[0]); w++) taken->words[w] |= held.words[w];
    }
}
/* The group codes a document capture may extend: a copy of the serving
 * generation's table (the map's while one serves, else the library's), the
 * other table beside it and the codes their keys hold. The copy is adopted
 * only if the capture defines new sets. */
typedef struct pr_key_context {
    pr_provider *owner;
    const sh_package_key_groups *other;
    sh_package_key_groups *scratch;
    sh_package_key_set taken;
} pr_key_context;
static void pr_key_context_open(pr_key_context *keys, pr_provider *owner)
{
    memset(keys, 0, sizeof(*keys));
    keys->owner = owner;
    keys->other = owner && owner != pr_reader() && pr_reader() ? pr_reader()->key_groups : NULL;
    keys->scratch = owner ? calloc(1, sizeof(*keys->scratch)) : NULL;
    if (keys->scratch && owner->key_groups) *keys->scratch = *owner->key_groups;
    pr_key_taken(pr_reader(), &keys->taken);
    pr_key_taken(owner, &keys->taken);
}
/* Adopt new group codes a capture defined, and publish them (exclusive). */
static int pr_key_context_close(pr_key_context *keys, int adopt)
{
    int ok = !adopt || !keys->owner || keys->scratch != NULL;
    if (adopt && keys->scratch && keys->owner &&
        keys->scratch->count > (keys->owner->key_groups ? keys->owner->key_groups->count : 0)) {
        PR_LOCK_EXCLUSIVE();
        sh_package_key_groups *serving = NULL;
#ifdef PR_NATIVE_SPAWN
        sh_spawn_keys_program *program = NULL;
#endif
        int publish = keys->owner == g_current_provider ||
            keys->owner == g_library_provider || keys->owner == g_map_provider;
        if (publish && keys->owner != g_current_provider && g_current_provider) {
            serving = calloc(1, sizeof(*serving));
            if (serving && g_current_provider->key_groups) *serving = *g_current_provider->key_groups;
            ok = serving && sh_package_key_groups_merge(serving, keys->scratch);
        }
#ifdef PR_NATIVE_SPAWN
        if (ok && publish && g_current_provider) {
            program = sh_spawn_keys_program_create_exact(keys->owner == g_current_provider ? keys->scratch : serving,
                g_current_provider->unmodified_types, g_current_provider->unmodified_count,
                g_current_provider->exact_modifier_types, g_current_provider->exact_modifier_count);
            ok = program != NULL;
        }
#endif
        /* Prepare both dictionaries before transferring either pointer. A
         * failed allocation must not commit a code only one consumer knows. */
        if (ok) {
            sh_package_key_groups *old = keys->owner->key_groups;
            keys->owner->key_groups = keys->scratch; keys->scratch = old;
            if (serving) {
                old = g_current_provider->key_groups;
                g_current_provider->key_groups = serving; serving = old;
            }
#ifdef PR_NATIVE_SPAWN
            if (program) {
                sh_spawn_keys_program *old_program = g_current_provider->spawn_program;
                g_current_provider->spawn_program = program; program = old_program;
            }
#endif
            if (publish) pr_publish_key_groups();
        }
#ifdef PR_NATIVE_SPAWN
        sh_spawn_keys_program_release(program);
#endif
        free(serving);
        PR_UNLOCK_EXCLUSIVE();
    }
    free(keys->scratch); keys->scratch = NULL;
    return ok;
}

void sh_package_runtime_key_decode(uint32_t value, sh_package_key_set *keys, uint32_t *historical)
{
    AcquireSRWLockShared(&g_lock);
    pr_provider *owner = g_current_provider;
    const sh_package_key_groups *groups = owner ? owner->key_groups : NULL;
    sh_package_key_decode(groups, value, keys);
    if (historical) *historical = owner && owner->key_groups ? owner->key_groups->historical : 0;
    ReleaseSRWLockShared(&g_lock);
}

int sh_package_runtime_key_code(const sh_package_key_set *keys, uint32_t *code)
{
    pr_key_context context;
    int result = -1;
    if (code) *code = 0;
    /* An editor edit never waits for a refresh; capture holds this lock too. */
    if (!keys || !code || !pr_refresh_try()) return -1;
    AcquireSRWLockShared(&g_lock);
    pr_key_context_open(&context, g_map_provider ? g_map_provider : g_library_provider);
    if (context.scratch) {
        *code = sh_package_key_groups_code(context.scratch, context.other, &context.taken, keys);
        result = *code != 0;
    }
    ReleaseSRWLockShared(&g_lock);
    if (!pr_key_context_close(&context, result == 1)) { *code = 0; result = -1; }
    pr_refresh_release(1);
    return result;
}
static char *pr_capture_document(const pr_provider *provider,
    sh_decl_registry_source registry, uintptr_t reflection, int retain_native,
    const sh_package_provenance *saved, const sh_package_bundle_binding *additional,
    size_t additional_count, const char *json, size_t length, size_t *output_length,
    sh_package_occurrence_snapshot **ownership, sh_mpkg_used **deliveries,
    size_t *delivery_count, sh_package_references *closure, sh_package_references *typed,
    sh_package_map_local_uses *local_uses, pr_key_context *keys, char *error, size_t capacity)
{
    sh_package_bundle_binding *rows = NULL;
    sh_package_source_reader *reader = NULL;
    sh_package_provenance uses = {0};
    sh_package_references references = {0}, resources = {0};
    sh_package_map_local_uses locals = {0};
    sh_package_source_binding inspection = {0};
    sh_package_occurrence_snapshot *next = NULL;
    sh_mpkg_used *used = NULL;
    char *out = NULL; size_t out_length = 0, count = 0, row_count;
    if (output_length) *output_length = 0;
    if (!provider || !provider->sources || !provider->compiled || !json ||
        !output_length || !ownership || (additional_count && !additional) ||
        (!!deliveries != !!delivery_count) || provider->bundle_count > SIZE_MAX - additional_count)
        goto done;
    double phase = pr_read_now();
    if (!(rows = pr_provider_rows(provider, additional, additional_count, &row_count))) goto done;
    g_phase_stats.rows_ms += pr_read_now() - phase; phase = pr_read_now();
    pr_original_source originals = {provider->catalog ? sh_resource_catalog_read_path : NULL,
        provider->catalog, provider->native_assets};
#ifdef SH_PACKAGE_RUNTIME_TESTING
    sh_package_runtime_test_source_inputs(NULL, NULL, &originals.game, &originals.context);
#endif
    reader = sh_package_source_reader_open(provider->compiled, provider->catalog,
        pr_original, &originals, registry, reflection, error, capacity);
    g_phase_stats.reader_ms += pr_read_now() - phase;
    if (!reader) goto done;
    /* R-249: documents bound for a plan are what the engine loads; captures of
     * live documents keep their bytes (sh_package_source_reader_project_mode). */
    sh_package_source_reader_project_mode(reader, retain_native ? 1 : 2);
    if (keys) sh_package_source_reader_key_codes(reader, keys->scratch, keys->other, &keys->taken,
        sh_package_map_uses_saved_keys);
    sh_package_source_reader_map_local(reader, &pr_map_local);
    pr_variants variants = {0};
    if (!retain_native && !g_test_variants_off && provider != g_current_provider && provider != g_map_provider &&
        provider != g_library_provider) sh_package_source_reader_variant_sink(reader, pr_variant_collect, &variants);
    sh_mpkg_use_requirements required = {provider->compiled, provider->catalog};
    phase = pr_read_now();
    out = sh_package_map_uses_select_local(reader, json, length, saved, &provider->bindings,
        rows, row_count, sh_mpkg_new_use_required, &required,
        retain_native ? pr_retained_use : NULL, (void *)provider, &out_length,
        &uses, &references, &locals, &inspection, error, capacity);
    g_phase_stats.walk_ms += pr_read_now() - phase; phase = pr_read_now();
    sh_package_source_reader_close(reader); reader = NULL;
    if (out && variants.count && !pr_variants_serve(provider->compiled,
        g_library_provider ? g_library_provider->compiled : NULL,
        &(pr_binding_sets){{&provider->bindings, g_library_provider ? &g_library_provider->bindings : NULL, NULL}},
        &variants, error, capacity)) { free(out); out = NULL; }
    pr_variants_free(&variants);
    if (!out) goto done;
    next = sh_package_occurrence_prepare_document(&uses, rows, row_count, error, capacity);
    if (!next) goto done;
    if (!pr_capture_leases(provider, next, error, capacity)) goto done;
    g_phase_stats.document_ms += pr_read_now() - phase; phase = pr_read_now();
    if (deliveries) {
        count = sh_mpkg_used_packages_for_uses(provider->compiled, provider->catalog,
            out, out_length, &references, &uses, rows, row_count, &used, &resources, error, capacity);
        if (count == SIZE_MAX) goto done;
    }
    g_phase_stats.deliveries_ms += pr_read_now() - phase;
    /* Map-local play declaration uses tie their consumers to the named
     * occurrence's identity, at their own typed sites; they never enter
     * resource delivery above or the typed names. */
    sh_package_occurrence_release(*ownership); *ownership = next; next = NULL;
    if (deliveries) { sh_mpkg_used_free(*deliveries); *deliveries = used; used = NULL; *delivery_count = count; }
    if (closure && deliveries) { sh_package_references_free(closure); *closure = resources; memset(&resources, 0, sizeof(resources)); }
    if (typed) { sh_package_references_free(typed); *typed = references; memset(&references, 0, sizeof(references)); }
    if (local_uses) { sh_package_map_local_uses_free(local_uses); *local_uses = locals; memset(&locals, 0, sizeof(locals)); }
    *output_length = out_length;
done:
    if (!output_length || !*output_length) {
        free(out); out = NULL;
        if (error && capacity && !*error) snprintf(error, capacity, "exact map occurrence ownership could not be prepared");
    }
    sh_package_occurrence_release(next); sh_mpkg_used_free(used);
    sh_package_provenance_free(&uses); sh_package_references_free(&references);
    sh_package_references_free(&resources); sh_package_map_local_uses_free(&locals);
    sh_package_source_reader_close(reader); free(rows); return out;
}

char *sh_package_runtime_capture_document(const sh_package_map_plan *plan,
    const sh_package_provenance *saved, const sh_package_bundle_binding *additional,
    size_t additional_count, const char *json, size_t length, size_t *output_length,
    sh_package_occurrence_snapshot **ownership, sh_mpkg_used **deliveries,
    size_t *delivery_count, char *error, size_t capacity)
{
    char *out = NULL;
    size_t pending_length = 0, pending_count = 0;
    sh_package_occurrence_snapshot *pending_ownership = NULL;
    sh_mpkg_used *pending_deliveries = NULL;
    if (error && capacity) *error = 0;
    if (output_length) *output_length = 0;
    if (!ownership || !output_length || (!!deliveries != !!delivery_count)) {
        if (error && capacity) snprintf(error, capacity, "map occurrence output is unavailable");
        return NULL;
    }
    if (sh_package_runtime_serving_disabled()) {
        /* No user package is served this launch (sh_user_overrides 0): a
         * native document owns no package content and is its own capture.
         * One that names package uses or carries deliveries cannot run
         * without its packages and is refused, its provenance untouched. */
        sh_package_occurrence_snapshot *empty = NULL;
        if (plan || additional_count || (saved && (saved->use_count || saved->binding_count || saved->context_count))) {
            if (error && capacity) snprintf(error, capacity,
                "this map uses packages, and package serving is disabled for this launch (sh_user_overrides 0)");
            return NULL;
        }
        if (!json || length == SIZE_MAX || !(out = malloc(length + 1)) ||
            !(empty = sh_package_occurrence_prepare_document(NULL, NULL, 0, error, capacity))) {
            free(out);
            if (error && capacity && !*error) snprintf(error, capacity, "map occurrence output could not be allocated");
            return NULL;
        }
        memcpy(out, json, length); out[length] = 0;
        sh_package_occurrence_release(*ownership); *ownership = empty;
        if (deliveries) { sh_mpkg_used_free(*deliveries); *deliveries = NULL; *delivery_count = 0; }
        *output_length = length;
        return out;
    }
    int refresh_entered = !g_activation_callback && !pr_refresh_held();
    double locked = pr_read_now();
    if (refresh_entered) pr_refresh_acquire(1);
    AcquireSRWLockShared(&g_lock);
    g_phase_stats.capture_lock_ms += pr_read_now() - locked;
    pr_key_context keys;
    pr_key_context_open(&keys, plan ? plan->provider : pr_open_map() ? pr_open_map() : g_library_provider);
#ifndef SH_PACKAGE_RUNTIME_TESTING
    sh_decl_registry_source registry = {0};
    sh_decl_native_source metadata = {NULL, pr_native_read, 0, g_native_scripts};
    if (sh_decl_server_registry_source(&registry) && sh_decl_native_source_ready(&metadata,
        g_native_accessor, g_native_types, g_native_game_system) == 1)
        out = pr_capture_document(plan ? plan->provider : g_current_provider, registry, metadata.reflection, !plan,
            saved, additional, additional_count, json, length, &pending_length, &pending_ownership,
            deliveries ? &pending_deliveries : NULL, deliveries ? &pending_count : NULL, NULL, NULL, NULL, &keys, error, capacity);
#else
    sh_decl_registry_source registry = {0}; uintptr_t reflection = 0;
    if (sh_package_runtime_test_source_inputs(&registry, &reflection, NULL, NULL))
        out = pr_capture_document(plan ? plan->provider : g_current_provider, registry, reflection, !plan,
            saved, additional, additional_count, json, length, &pending_length, &pending_ownership,
            deliveries ? &pending_deliveries : NULL, deliveries ? &pending_count : NULL, NULL, NULL, NULL, &keys, error, capacity);
#endif
    ReleaseSRWLockShared(&g_lock);
    if (!pr_key_context_close(&keys, out != NULL)) {
        free(out); out = NULL;
        if (error && capacity) snprintf(error, capacity, "map registration dictionary could not be published");
    }
    if (out) {
        sh_package_occurrence_release(*ownership); *ownership = pending_ownership; pending_ownership = NULL;
        if (deliveries) {
            sh_mpkg_used_free(*deliveries); *deliveries = pending_deliveries; pending_deliveries = NULL;
            *delivery_count = pending_count;
        }
        *output_length = pending_length;
    }
    sh_package_occurrence_release(pending_ownership); sh_mpkg_used_free(pending_deliveries);
    if (refresh_entered) pr_refresh_release(1);
    if (!out && error && capacity && !*error) snprintf(error, capacity, "native map occurrence reader is unavailable");
    return out;
}

