        hints->view.name = hints->bank.name;
        for (size_t i = 0; i < 5; i++) {
            if (!pr_inline_native_read(view, hints->bank.resource, 0xd0 + i * 8, &pointer, sizeof(pointer)) ||
                !pr_inline_native_reference(view, "snapeditorentitydef", pointer, hints->rows + i) ||
                !pr_inline_native_ready(view, pointer, hints->flags + 1 + i) ||
                !pr_inline_native_read(view, pointer, 0x3c8, &category, sizeof(category)) ||
                !pr_inline_native_read(view, pointer, 0x1c8, &pointer, sizeof(pointer)) ||
                !pr_inline_native_reference(view, "entitydef", pointer, hints->definitions + i) ||
                !pr_inline_native_ready(view, pointer, hints->flags + 6 + i)) return -1;
            hints->view.selectors[i] = (sh_native_inline_hint_selector){hints->rows[i].name, hints->definitions[i].name, category};
        }
