    size_t length = family ? strlen(family) : 0;
    if (!length || length >= sizeof(folder)) { candidate->failed = 1; return 0; }
    for (size_t i = 0; i <= length; i++) folder[i] = (char)tolower((unsigned char)family[i]);
    sh_decl_source text = {0}; int served = 0;
    int read = pr_inline_read_typed(candidate->view, folder, name, &text, &served, NULL);
    free((char *)text.text);
    if (read < 0) { candidate->failed = 1; return 0; }
    if (!read) return 1;
    memcpy(candidate->view->resolved_family, folder, length + 1);
    candidate->found = 1;
    return 0;
