static const sh_package_provenance_use *pr_inline_site(const sh_package_provenance *uses, size_t entity)
{
    char owner[64];
    snprintf(owner, sizeof(owner), "entity/%zu", entity);
    for (size_t i = 0; uses && i < uses->use_count; i++) {
        const sh_package_provenance_use *use = uses->uses + i;
        if (use->owner && use->reference && !strcmp(use->owner, owner) &&
            !strcmp(use->reference, "/k:entityDef/k:inherit")) return use;
    }
    return NULL;
}
/* Declaration names fold ASCII case and separators and drop one leading '/'. */
static int pr_inline_name_equal(const char *a, const char *b)
{
    if (!a || !b) return 0;
    if (*a == '/' && a[1] != '/') a++;
    if (*b == '/' && b[1] != '/') b++;
    for (; *a && *b; a++, b++) {
        char x = *a == '\\' ? '/' : *a, y = *b == '\\' ? '/' : *b;
        if (x >= 'A' && x <= 'Z') x += 32;
        if (y >= 'A' && y <= 'Z') y += 32;
        if (x != y) return 0;
    }
    return !*a && !*b;
}
/* Every other typed site bound to name, the definition this entity inherits
 * or a served ancestor its conversion folds, for a per-use decision by its
 * consumer (sh_native_inline_source.looked_up). Other entities inheriting it
 * are independent occurrences and are not listed. */
static int pr_inline_looked_up(void *context, size_t entity, const char *name, sh_native_inline_use *uses,
    size_t capacity)
{
    pr_inline_view *view = context;
    const sh_package_provenance_use *site = pr_inline_site(view->uses, entity);
    size_t count = 0;
    if (!site) return 0;
    /* The entity's own definition is exactly its inherit's binding; a folded
     * ancestor (a chain never repeats a name) is every binding the document
     * records under that name. */
    int own = !name || (site->binding < view->uses->binding_count &&
        pr_inline_name_equal(name, view->uses->bindings[site->binding].name));
    for (size_t i = 0; i < view->uses->use_count; i++) {
        const sh_package_provenance_use *use = view->uses->uses + i;
        if (use == site) continue;
        if (own ? use->binding != site->binding : use->binding >= view->uses->binding_count ||
            !pr_inline_name_equal(name, view->uses->bindings[use->binding].name)) continue;
        if (use->owner && !strncmp(use->owner, "entity/", 7) && use->reference &&
            !strcmp(use->reference, "/k:entityDef/k:inherit")) continue;
        if (count < capacity) uses[count] = (sh_native_inline_use){use->owner, use->reference};
        if (++count > INT_MAX) return -1;
    }
    return (int)count;
}
/* The typed names the captured document's sites hold, vanilla ones included. */
static int pr_inline_typed_name(void *context, size_t index, const char **family, const char **name)
{
    const pr_inline_view *view = context;
    if (view->typed.incomplete) return -1;
    if (index >= view->typed.count) return 0;
    *family = view->typed.items[index].type; *name = view->typed.items[index].name;
    return 1;
}
/* The captured document's map-local play declaration uses, each at its site. */
static int pr_inline_local_use(void *context, size_t index, const char **owner, const char **reference,
    const char **name)
{
    const pr_inline_view *view = context;
    if (view->typed.incomplete) return -1;
    if (index >= view->local.count) return 0;
    *owner = view->local.items[index].owner; *reference = view->local.items[index].reference;
    *name = view->local.items[index].name;
    return 1;
}
/* Why one use keeps its package route regardless of native equivalence: a
 * supplier the derived map must keep (pr_inline_requirement), or a definition
 * served as authored. NULL when nothing keeps it. */
static const char *pr_inline_use_kept(const pr_inline_view *view, const sh_package_provenance_use *site,
    const char *name, sh_decl_carrier_limit *limit)
{
    *limit = SH_DECL_CARRIER_GAP;
    for (size_t c = 0; c < site->context_count; c++) {
        size_t index = site->contexts[c];
        if (index >= view->uses->context_count) return "this use has no recorded source context";
        const sh_package_provenance_context *source = view->uses->contexts + index;
        for (size_t t = 0; t < source->tree_count; t++)
            for (size_t k = 0; k < view->kept_count; k++)
                if (!memcmp(source->trees[t], view->kept[k].tree, 32)) {
                    *limit = view->kept[k].limit;
                    return view->kept[k].reason;
                }
    }
    /* A definition served as authored with undecided native semantics keeps
     * its package: converting it would claim an equivalence nothing proved. */
    const sh_package_compilation *compiled = view->provider ? view->provider->compiled : NULL;
    for (size_t i = 0; name && compiled && i < compiled->resource_count; i++) {
        const sh_compiled_resource *r = compiled->resources + i;
        if (r->semantic_coverage && r->type && !strcmp(r->type, "entitydef") && r->name && !_stricmp(r->name, name))
            return "its definition's native state selection is not modelled (served as authored)";
    }
    return NULL;
}
static const char *pr_inline_keep(void *context, size_t entity, const char *name, sh_decl_carrier_limit *limit)
{
    pr_inline_view *view = context;
    const sh_package_provenance_use *site = pr_inline_site(view->uses, entity);
    *limit = SH_DECL_CARRIER_GAP;
    if (!site) return "this entity has no verified package use to replace";
    return pr_inline_use_kept(view, site, name, limit);
}
/* The captured document's typed uses, each with its saved name and its own
 * suppliers' keep decision (sh_native_inline_source.bound_use). An entity's
 * own inherit is listed without a name: placed occurrences decide it. */
static int pr_inline_bound_use(void *context, size_t index, sh_native_inline_use *use, const char **name,
    const char **kept, sh_decl_carrier_limit *limit)
{
    const pr_inline_view *view = context;
    *name = *kept = NULL; *limit = SH_DECL_CARRIER_GAP;
    if (!view->uses || index >= view->uses->use_count) return 0;
    const sh_package_provenance_use *site = view->uses->uses + index;
    *use = (sh_native_inline_use){site->owner, site->reference};
    if ((site->owner && !strncmp(site->owner, "entity/", 7) && site->reference &&
        !strcmp(site->reference, "/k:entityDef/k:inherit")) || site->binding >= view->uses->binding_count) return 1;
    *name = view->uses->bindings[site->binding].name;
    *kept = pr_inline_use_kept(view, site, *name, limit);
    return 1;
}

/* ---- R137 native placement ----
 * A converted entity must pass SnapMap's map validation: its native base needs
 * a row among SnapMap's shipped editor declarations, and an editor row a
 * package adds for its definition must add nothing (package_editor_rows.h). */
#define PR_EDITOR_PREFIX "generated/decls/snapeditorentitydef/"
static int pr_name_order(const void *a, const void *b)
{ return strcmp(*(const char *const *)a, *(const char *const *)b); }
/* Shipped rows, read once per catalog; guarded by g_editor_rows_lock. */
static SRWLOCK g_editor_rows_lock = SRWLOCK_INIT;
static sh_editor_rows g_editor_rows;
static const void *g_editor_rows_key;
static int g_editor_rows_state;
/* SnapMap's shipped editor entries in catalog (under test, the fixture's
 * names) read into rows: 1, 0 when there is no catalog, -1 on failure. */
static int pr_read_shipped_rows(const sh_resource_catalog *catalog, const pr_original_source *originals,
    sh_editor_rows *rows)
{
    const char **names = NULL; char **owned = NULL; size_t name_count = 0;
    int state = -1;
#ifdef SH_PACKAGE_RUNTIME_TESTING
    /* A fixture that lists no shipped entries ships none; the unavailable
     * switch stands in for a compile without the game's catalog. */
    (void)catalog;
    if (g_test_editor_rows_unavailable) return 0;
    names = (const char **)g_test_editor_rows; name_count = g_test_editor_rows ? g_test_editor_row_count : 0;
#else
    if (!catalog) return 0;
    size_t total = sh_resource_catalog_count(catalog);
    if (!(owned = calloc(total ? total : 1, sizeof(*owned)))) return -1;
    for (size_t i = 0; i < total; i++) {
        const sh_resource_catalog_entry *entry = sh_resource_catalog_at(catalog, i);
        size_t length = entry && entry->path ? strlen(entry->path) : 0;
        if (length <= sizeof(PR_EDITOR_PREFIX) + 4 || strncmp(entry->path, PR_EDITOR_PREFIX, sizeof(PR_EDITOR_PREFIX) - 1) ||
            strcmp(entry->path + length - 5, ".decl")) continue;
        size_t n = length - (sizeof(PR_EDITOR_PREFIX) - 1) - 5;
        if (!(owned[name_count] = malloc(n + 1))) goto done;
        memcpy(owned[name_count], entry->path + sizeof(PR_EDITOR_PREFIX) - 1, n); owned[name_count++][n] = 0;
    }
    if (name_count) qsort(owned, name_count, sizeof(*owned), pr_name_order);
    names = (const char **)owned;
#endif
    for (size_t i = 0; i < name_count; i++) {
        if (i && !strcmp(names[i], names[i - 1])) continue;
        size_t length = strlen(names[i]) + sizeof(PR_EDITOR_PREFIX) + 5;
        char *path = malloc(length);
        unsigned char *body = NULL; size_t size = 0;
        if (!path) goto done;
        snprintf(path, length, PR_EDITOR_PREFIX "%s.decl", names[i]);
        int scope = pr_original((void *)originals, path, &body, &size);
        free(path);
        /* Only SnapMap's own archive supplies the shipped editor roster. */
        if (scope < 0) rows->unreadable++;
        int added = scope == 1 ? sh_editor_rows_add_text(rows, names[i], (const char *)body, size) : 0;
        free(body);
        if (added < 0) goto done;
    }
    if (sh_editor_rows_finish(rows, NULL)) state = 1;
done:
    for (size_t i = 0; owned && i < name_count; i++) free(owned[i]);
    free(owned);
    if (state != 1) sh_editor_rows_free(rows);
    return state;
}
/* The shipped rows for placement, read once per catalog (g_editor_rows_lock). */
static int pr_shipped_rows(const sh_resource_catalog *catalog, const pr_original_source *originals)
{
    const void *key = catalog;
#ifdef SH_PACKAGE_RUNTIME_TESTING
    key = g_test_editor_rows;
#endif
    if (g_editor_rows_state && g_editor_rows_key == key) return g_editor_rows_state;
    sh_editor_rows_free(&g_editor_rows); g_editor_rows_key = key; g_editor_rows_state = -1;
    if (!key) return -1;
    return g_editor_rows_state = pr_read_shipped_rows(catalog, originals, &g_editor_rows) == 1 ? 1 : -1;
}
static int pr_stock_rows(const pr_inline_view *view)
{ return pr_shipped_rows(view->provider->catalog, &view->originals); }

/* ---- Toybox roster for label qualification (strids.h, sh_strids_palette) ---
 * Every editor entry that is a toybox tile or a logic selector (an Add Logic
 * input or output, which states no meta category: its meta is the empty text), as
 * the current provider serves it:
 * every served editor declaration (package, legacy public and product rows,
 * and packages' own versions of shipped entries), then every shipped entry the
 * provider does not serve. Each resolves its inherited fields through the
 * served entries first and the shipped ones after, so an untouched shipped
 * child of a changed parent shows the parent's served label. Rows read as
 * served, so an aliased row names the label alias its presented text selects
 * (with a map overlay or an installed increment, the one of the resource it
 * serves); label presentation is all this reads, and conversion keeps reading
 * authored bodies. The entries are copies owned here until the next call; the
 * string refresh reads them while it runs (dllmain.c binds this to strids). */
typedef struct pr_roster { sh_strids_palette_entry *entries; char **strings; size_t count, string_count; } pr_roster;
static pr_roster g_roster;
static void pr_roster_free(void)
{
    for (size_t i = 0; i < g_roster.string_count; i++) free(g_roster.strings[i]);
    free(g_roster.strings); free(g_roster.entries); memset(&g_roster, 0, sizeof(g_roster));
}
static const char *pr_roster_copy(const char *value, size_t capacity)
{
    char *copy = _strdup(value);
    if (!copy || g_roster.string_count >= capacity) { free(copy); return NULL; }
    g_roster.strings[g_roster.string_count++] = copy;
    return copy;
}
/* The roster of one compilation (g_roster); the caller keeps it alive. */
static int pr_palette_of(const sh_package_compilation *compiled, const sh_resource_catalog *catalog,
    const pr_original_source *originals, const sh_strids_palette_entry **entries, size_t *count)
{
    sh_editor_rows served = {0};
    pr_exposure_pick *left_out = NULL;
    size_t left_out_count = 0;
    int state = 0, published = compiled == g_compiled;
    *entries = NULL; *count = 0;
    pr_roster_free();
    AcquireSRWLockExclusive(&g_editor_rows_lock);
    if (pr_shipped_rows(catalog, originals) != 1) goto done; /* Not yet readable: base labels. */
    state = -1;
    /* Rows another equal exposure stands for are not visible (pr_exposure_select):
     * the published compilation's selection, or this compilation's own. */
    if (!published && compiled) {
        pr_original_source own = *originals;
        if (!pr_exposure_select(compiled, NULL, compiled->sources, &own, &left_out, &left_out_count, NULL)) goto done;
    }
    for (size_t i = 0; compiled && i < compiled->resource_count; i++) {
        const sh_compiled_resource *resource = compiled->resources + i;
        size_t length = strlen(resource->engine_path), size = 0;
        char error[256];
        if (length <= sizeof(PR_EDITOR_PREFIX) + 4 || !resource->type ||
            strncmp(resource->engine_path, PR_EDITOR_PREFIX, sizeof(PR_EDITOR_PREFIX) - 1) ||
            strcmp(resource->engine_path + length - 5, ".decl")) continue;
        size_t n = length - (sizeof(PR_EDITOR_PREFIX) - 1) - 5;
        char *name = malloc(n + 1);
        if (!name) goto done;
        memcpy(name, resource->engine_path + sizeof(PR_EDITOR_PREFIX) - 1, n); name[n] = 0;
        unsigned char *body = sh_package_compilation_read_served(compiled, resource, SIZE_MAX / 2, &size, error, sizeof(error));
        int added = body ? sh_editor_rows_add_text(&served, name, (const char *)body, size) : -1;
        free(name); free(body);
        if (added < 0) goto done;
    }
    if (!sh_editor_rows_finish(&served, &g_editor_rows)) goto done;
    size_t total = served.count + g_editor_rows.count, strings = total * 4;
    if (!(g_roster.entries = calloc(total ? total : 1, sizeof(*g_roster.entries))) ||
        !(g_roster.strings = calloc(strings ? strings : 1, sizeof(*g_roster.strings)))) goto done;
    for (size_t i = 0; i < total; i++) {
        const sh_editor_row *row = i < served.count ? served.items + i : g_editor_rows.items + (i - served.count);
        if (i >= served.count && sh_editor_rows_find(&served, row->name)) continue; /* Served above. */
        if (published ? pr_exposure_left_out(row->name) : pr_exposure_find(left_out, left_out_count, row->name) != NULL)
            continue;
        const char *entity = sh_editor_rows_effective(&served, &g_editor_rows, row, SH_EDITOR_ROW_ENTITY_DEF);
        const char *label = sh_editor_rows_effective(&served, &g_editor_rows, row, SH_EDITOR_ROW_LABEL);
        const char *category = sh_editor_rows_effective(&served, &g_editor_rows, row, SH_EDITOR_ROW_CATEGORY);
        const char *meta = sh_editor_rows_effective(&served, &g_editor_rows, row, SH_EDITOR_ROW_META);
        if (!entity || !*entity || !label || !category) continue;
        if (!meta) meta = ""; /* a selector row states no meta category */
        sh_strids_palette_entry *entry = g_roster.entries + g_roster.count;
        if (!(entry->row = pr_roster_copy(row->name, strings)) || !(entry->label = pr_roster_copy(label, strings)) ||
            !(entry->category = pr_roster_copy(category, strings)) || !(entry->meta = pr_roster_copy(meta, strings))) goto done;
        g_roster.count++;
    }
    state = 1;
done:
    ReleaseSRWLockExclusive(&g_editor_rows_lock);
    sh_editor_rows_free(&served);
    pr_exposure_free(left_out, left_out_count);
    if (state != 1) pr_roster_free();
    else { *entries = g_roster.entries; *count = g_roster.count; }
    return state;
}
int sh_package_runtime_palette(void *context, const sh_strids_palette_entry **entries, size_t *count)
{
    (void)context;
    AcquireSRWLockShared(&g_lock);
    pr_original_source originals = {g_catalog ? sh_resource_catalog_read_path : NULL, (void *)g_catalog,
        pr_reader() ? pr_reader()->native_assets : NULL};
#ifdef SH_PACKAGE_RUNTIME_TESTING
    {
        sh_package_baseline_reader test = NULL; void *test_context = NULL;
        sh_package_runtime_test_source_inputs(NULL, NULL, &test, &test_context);
        if (test) { originals.game = test; originals.context = test_context; }
    }
#endif
    int state = pr_palette_of(pr_reader_compiled(), g_catalog, &originals, entries, count);
    ReleaseSRWLockShared(&g_lock);
    return state;
}
#ifdef SH_PACKAGE_RUNTIME_TESTING
int sh_package_runtime_test_palette_of(const sh_package_compilation *compiled,
    const struct sh_strids_palette_entry **entries, size_t *count)
{
    pr_original_source originals = {NULL, NULL, NULL};
    sh_package_runtime_test_source_inputs(NULL, NULL, &originals.game, &originals.context);
    return pr_palette_of(compiled, NULL, &originals, entries, count);
}
#endif
static int pr_compile_rows_read(void *context, const struct sh_editor_rows **rows)
{
    pr_compile_rows *compile = context;
    if (!compile->state) {
        int read = pr_read_shipped_rows(compile->catalog, compile->originals, &compile->rows);
        /* A descendant closure needs every shipped entry: one the archive holds
         * but that cannot be read or parsed fails the roster (an absent or
         * campaign-only name is simply not a SnapMap entry). */
        if (read == 1 && compile->rows.unreadable) { sh_editor_rows_free(&compile->rows); read = -1; }
        compile->state = read == 1 ? 1 : read == 0 ? 2 : -1;
    }
    *rows = compile->state == 1 ? &compile->rows : NULL;
    return compile->state == 1 ? 1 : compile->state == 2 ? 0 : -1;
}
/* Editor rows this map's packages serve, read once per conversion. */
static int pr_package_rows(pr_inline_view *view)
{
    const sh_package_compilation *compiled = view->provider->compiled;
    char error[256];
    const char **context_copy = NULL, **shipped_name = NULL; /* private name -> shipped name */
    size_t copies = 0;
    int state = -1;
    if (view->package_rows_state) return view->package_rows_state;
    view->package_rows_state = -1;
    context_copy = calloc(compiled->resource_count ? compiled->resource_count : 1, sizeof(*context_copy));
    shipped_name = calloc(compiled->resource_count ? compiled->resource_count : 1, sizeof(*shipped_name));
    if (!context_copy || !shipped_name) goto done;
    for (size_t i = 0; i < compiled->resource_count; i++) {
        const sh_compiled_resource *resource = compiled->resources + i;
        size_t length = strlen(resource->engine_path), size = 0;
        if (resource->native_original || resource->restored_original ||
            strncmp(resource->engine_path, PR_EDITOR_PREFIX, sizeof(PR_EDITOR_PREFIX) - 1) ||
            length <= sizeof(PR_EDITOR_PREFIX) + 4 || strcmp(resource->engine_path + length - 5, ".decl")) continue;
        /* The installed library serves the stock editor entries its packages
         * inherit under their own names, composed from the originals alone:
         * no package owns a change to them. A plain package entry names such an
         * entry, so in any context it presents exactly as that stock entry does;
         * these copies stand for the shipped rows. A stock entry a package does
         * change (an owner) stays a package row, refusing its plain copies. */
        if (resource->baseline_known && !sh_package_owners_count(&resource->owners) &&
            (!resource->original_path || !_stricmp(resource->original_path, resource->engine_path))) continue;
        /* The same unowned stock entry, linked privately for a package's own
         * context (a shared editor declaration it references differs there):
         * the converted entity is placed by the shipped entry itself, so the
         * copy stands for it too. */
        size_t original_length = resource->original_path ? strlen(resource->original_path) : 0;
        if (resource->baseline_known && !sh_package_owners_count(&resource->owners) &&
            original_length > sizeof(PR_EDITOR_PREFIX) + 4 &&
            !_strnicmp(resource->original_path, PR_EDITOR_PREFIX, sizeof(PR_EDITOR_PREFIX) - 1) &&
            !_stricmp(resource->original_path + original_length - 5, ".decl")) {
            context_copy[copies] = resource->engine_path + sizeof(PR_EDITOR_PREFIX) - 1;
            shipped_name[copies++] = resource->original_path + sizeof(PR_EDITOR_PREFIX) - 1;
            continue;
        }
        unsigned char *body = sh_package_compilation_read(compiled, resource, SIZE_MAX / 2, &size, error, sizeof(error));
        if (!body) goto done;
        size_t n = length - (sizeof(PR_EDITOR_PREFIX) - 1) - 5;
        char *name = malloc(n + 1);
        if (!name) { free(body); goto done; }
        memcpy(name, resource->engine_path + sizeof(PR_EDITOR_PREFIX) - 1, n); name[n] = 0;
        int added = sh_editor_rows_add_text(&view->package_rows, name, (const char *)body, size);
        free(name); free(body);
        if (added < 0) goto done;
    }
    /* Package entries inheriting such a copy inherit the shipped entry. */
    for (size_t i = 0; i < view->package_rows.count; i++) {
        sh_editor_row *row = view->package_rows.items + i;
        for (size_t c = 0; row->parent && c < copies; c++) {
            size_t n = strlen(context_copy[c]) - 5, m = strlen(shipped_name[c]) - 5;
            if (strlen(row->parent) != n || _strnicmp(row->parent, context_copy[c], n)) continue;
            char *parent = malloc(m + 1);
            if (!parent) goto done;
            memcpy(parent, shipped_name[c], m); parent[m] = 0;
            free(row->parent); row->parent = parent;
            break;
        }
    }
    state = view->package_rows_state = sh_editor_rows_finish(&view->package_rows, &g_editor_rows) ? 1 : -1;
done:
    free((void *)context_copy); free((void *)shipped_name);
    return state;
}
/* Native state comparison of the actual definitions (R-191, M60). A private
 * definition's Parse resolves its inherit through the engine's global name
 * lookup (VK 0x17ae9d0 stores the parent at +0x160), so per definition: a name
 * the document serves must be served by the engine now with the same compiled
 * source; a name the document leaves original must be original in the engine
 * too (no provider serves a changed copy under that stock name). The target
 * chain's document-only definitions are prepared privately with their authored
 * text instead of being looked up; the candidate chain is stock only. */
#ifdef SH_PACKAGE_RUNTIME_TESTING
static sh_package_runtime_native_compare g_test_native_compare;
void sh_package_runtime_test_native_compare(sh_package_runtime_native_compare compare)
{ g_test_native_compare = compare; }
#endif
typedef struct pr_eval_chain {
    sh_native_eval_layer *layers;
    size_t count;
    size_t prepared;     /* layers through the topmost one the engine does not serve as authored */
    int engine_mismatch; /* the engine answers a stock name with a changed copy */
    char authority[65];  /* per layer: p private, s served same, o original (diagnostic) */
    char detail[200];
} pr_eval_chain;
static int pr_eval_chain_add(pr_eval_chain *chain, const char *name, const sh_decl_source *text, char authority)
{
    sh_native_eval_layer *grown = realloc(chain->layers, (chain->count + 1) * sizeof(*grown));
    char *copy = malloc(text->length + 1), *label = _strdup(name);
    if (grown) chain->layers = grown;
    if (!grown || !copy || !label) { free(copy); free(label); return 0; }
    memcpy(copy, text->text, text->length); copy[text->length] = 0;
    if (chain->count < sizeof(chain->authority) - 1) chain->authority[chain->count] = authority;
    chain->layers[chain->count++] = (sh_native_eval_layer){label, copy};
    return 1;
}
static void pr_eval_chain_free(pr_eval_chain *chain)
{
    for (size_t i = 0; i < chain->count; i++) { free((char *)chain->layers[i].name); free((char *)chain->layers[i].text); }
    free(chain->layers); chain->layers = NULL; chain->count = 0;
}
/* 1 when the engine serves exactly this compiled source under its path,
 * 0 not, -1 unreadable. */
static int pr_eval_served_same(const pr_provider *document, const pr_provider *serving, const char *path)
{
    const sh_compiled_resource *mine = sh_package_compilation_find(document->compiled, path), *theirs;
    unsigned char *a = NULL, *b = NULL; size_t na = 0, nb = 0; char error[160];
    if (!serving || !serving->compiled || !mine) return 0;
    if (serving == document) return 1;
    theirs = sh_package_compilation_find(serving->compiled, path);
    if (!theirs || theirs->native_original || theirs->restored_original) return 0;
    a = sh_package_compilation_read(document->compiled, mine, SIZE_MAX / 2, &na, error, sizeof(error));
    b = a ? sh_package_compilation_read(serving->compiled, theirs, SIZE_MAX / 2, &nb, error, sizeof(error)) : NULL;
    int same = !a || !b ? -1 : na == nb && !memcmp(a, b, na);
    free(a); free(b);
    return same;
}
/* Walk the inherit names the engine follows from name. A definition the
 * document serves holds its name only where the engine serves the same
 * source; otherwise prepare collects it for a private evaluation, and
 * stock_only refuses it. A name the document leaves original must be original
 * in the engine. prepare also collects every definition beneath the topmost
 * collected one (nearest first), because Parse gave the engine's copies of
 * those their class and editor variables from the engine's parent. 1 holds,
 * 0 not (chain->detail set), -1 unavailable. */
static int pr_eval_chain_walk(pr_inline_view *view, const pr_provider *serving, const char *name,
    int prepare, int stock_only, pr_eval_chain *chain)
{
    pr_inline_view engine;
    char *current = name && *name ? _strdup(name) : NULL;
    int result = !name ? -1 : !*name ? 1 : current ? 1 : -1;
    memset(&engine, 0, sizeof(engine));
    engine.provider = serving; engine.originals = view->originals;
    for (int depth = 0; current && result == 1; depth++) {
        sh_decl_source text = {0};
        int served = 0, found = depth < 64 ? pr_inline_read(view, current, &text, &served, NULL) : -1;
        if (found != 1) {
            if (!found) snprintf(chain->detail, sizeof(chain->detail), "'%s' is not available", current);
            result = found < 0 ? -1 : 0; break;
        }
        if (served && stock_only) {
            snprintf(chain->detail, sizeof(chain->detail),
                "the native base's chain reaches '%s', which is not the unchanged stock original", current);
            result = 0;
        } else if (served) {
            size_t length = strlen(current) + sizeof("generated/decls/entitydef/.decl");
            char *path = malloc(length);
            int same = path ? (snprintf(path, length, "generated/decls/entitydef/%s.decl", current),
                pr_eval_served_same(view->provider, serving, path)) : -1;
            free(path);
            if (same < 0) result = -1;
            else if (!same && !prepare) {
                snprintf(chain->detail, sizeof(chain->detail), "the engine does not serve '%s' with this document's source", current);
                result = 0;
            } else if (prepare) {
                if (!pr_eval_chain_add(chain, current, &text, same ? 's' : 'p')) result = -1;
                else if (!same) chain->prepared = chain->count;
            }
        } else if (serving) {
            /* The document's original must also be the engine's: the serving
             * provider may not answer this stock name with a changed copy. */
            sh_decl_source served_text = {0};
            int engine_served = 0, in_engine = pr_inline_read(&engine, current, &served_text, &engine_served, NULL);
            free((void *)served_text.text);
            if (in_engine < 0) result = -1;
            else if (in_engine == 1 && engine_served) {
                snprintf(chain->detail, sizeof(chain->detail), "the engine serves a changed copy of stock '%s'", current);
                chain->engine_mismatch = 1; result = 0;
            }
        }
        if (result == 1 && prepare && !served && !pr_eval_chain_add(chain, current, &text, 'o')) result = -1;
        char error[160];
        /* Parse follows only the positional inherit header
         * (sh_decl_entity_split): a repeated or later inherit is state text. */
        sh_decl_node *tree = result == 1 ? sh_decl_tree_parse_ordered(text, error, sizeof(error)) : NULL;
        if (result != 1) { free((void *)text.text); free(current); current = NULL; break; }
        if (!tree) { free((void *)text.text); free(current); current = NULL; result = -1; break; }
        sh_decl_entity_headers headers;
        sh_decl_entity_split(tree, &headers);
        const sh_decl_node *inherit = headers.inherit;
        const char *literal; size_t n;
        if (inherit && !sh_decl_tree_literal(inherit, &literal, &n)) {
            snprintf(chain->detail, sizeof(chain->detail), "'%s' inherit header is not a plain name", current);
            result = 0;
        }
        free((void *)text.text); free(current); current = NULL;
        if (result != 1) { sh_decl_tree_free(tree); break; }
        if (inherit && sh_decl_tree_literal(inherit, &literal, &n) && n) {
            if ((current = malloc(n + 1))) { memcpy(current, literal, n); current[n] = 0; }
            else result = -1;
        }
        sh_decl_tree_free(tree);
    }
    free(current);
    /* Definitions above the topmost collected one are the engine's own. */
    while (chain->count > chain->prepared) {
        chain->count--;
        free((char *)chain->layers[chain->count].name); free((char *)chain->layers[chain->count].text);
    }
    chain->authority[chain->count < sizeof(chain->authority) ? chain->count : sizeof(chain->authority) - 1] = 0;
    return result;
}
static sh_native_eval_status pr_inline_evaluate(void *context, size_t entity, const char *from, const char *base,
    const sh_decl_node *target, const sh_decl_node *candidate, const sh_native_eval_reduction *reduction, char *detail,
    size_t capacity)
{
    pr_inline_view *view = context;
    pr_eval_chain chain = {0}, stock = {0};
    char *left = NULL, *right = NULL;
    size_t length = 0;
    sh_native_eval_status status = SH_NATIVE_EVAL_FAILED;
    const pr_provider *serving = g_usable ? pr_reader() : NULL;
    (void)entity;
    /* The candidate inherits base by name: stock original in the document
     * and in the engine. */
    int held = pr_eval_chain_walk(view, serving, base, 0, 1, &stock);
    if (held <= 0) {
        snprintf(detail, capacity, "%s", held < 0 ? "the stock chain is unreadable" : stock.detail);
        status = held < 0 || stock.engine_mismatch ? SH_NATIVE_EVAL_UNAVAILABLE : SH_NATIVE_EVAL_UNSUPPORTED;
        goto done;
    }
    /* The target inherits from: what the engine does not serve with the
     * document's source is prepared privately. */
    held = pr_eval_chain_walk(view, serving, from, 1, 0, &chain);
    if (held <= 0) {
        snprintf(detail, capacity, "%s", held < 0 ? "the definition chain is unreadable" : chain.detail);
        status = SH_NATIVE_EVAL_UNAVAILABLE;
        goto done;
    }
    if ((left = sh_decl_tree_write(target, &length)) && (right = sh_decl_tree_write(candidate, &length))) {
#ifdef SH_PACKAGE_RUNTIME_TESTING
        status = g_test_native_compare ? g_test_native_compare(chain.layers, chain.count, left, right, reduction, detail,
            capacity) :
            SH_NATIVE_EVAL_UNAVAILABLE;
#else
        status = sh_native_decl_eval_compare_reduced(chain.layers, chain.count, left, right, reduction, detail, capacity);
#endif
    }
done:
    /* Internal diagnostic: which comparison branch ran. 0 layers is the
     * engine's served chain; otherwise the private layers, nearest first. */
    {
        static const char *const outcome[] = {"unavailable", "equal", "unequal", "unsupported", "failed"};
        char line[768], names[384] = "";
        size_t used = 0;
        for (size_t i = 0; i < chain.count && used + 1 < sizeof(names); i++) {
            int n = snprintf(names + used, sizeof(names) - used, "%s%c:%s", i ? ", " : "",
                i < sizeof(chain.authority) - 1 && chain.authority[i] ? chain.authority[i] : '?', chain.layers[i].name);
            if (n < 0) break;
            used += (size_t)n < sizeof(names) - used ? (size_t)n : sizeof(names) - used - 1;
        }
        snprintf(line, sizeof(line), "MPKG: native state comparison: '%s' on '%s' (%s document): %zu private layer(s)%s%s%s: %s (%s)",
            from ? from : "", base ? base : "", view->provider == serving ? "served" : serving ? "unserved" : "unpublished",
            chain.count, chain.count ? " [" : "", names, chain.count ? "]" : "",
            (unsigned)status < sizeof(outcome) / sizeof(*outcome) ? outcome[status] : "?", detail && capacity ? detail : "");
        backend_log(line);
    }
    free(left); free(right);
    pr_eval_chain_free(&chain); pr_eval_chain_free(&stock);
    return status;
}
static const char *pr_inline_placement(void *context, const char *from, const char *base, sh_decl_carrier_limit *limit)
{
    pr_inline_view *view = context;
    const char *reason = view->placement;
    char authored[512] = "";
    *limit = SH_DECL_CARRIER_GAP;
    AcquireSRWLockExclusive(&g_editor_rows_lock);
    if (pr_stock_rows(view) != 1) {
        snprintf(view->placement, sizeof(view->placement),
            "SnapMap's shipped editor entries could not be read to prove '%s' is placeable", base);
        goto done;
    }
    /* The authored spelling of a served private definition. */
    size_t length = strlen(from) + sizeof("generated/decls/entitydef/.decl");
    char *path = malloc(length);
    if (!path) { snprintf(view->placement, sizeof(view->placement), "placement could not be checked"); goto done; }
    snprintf(path, length, "generated/decls/entitydef/%s.decl", from);
    const sh_compiled_resource *served = sh_package_compilation_find(view->provider->compiled, path);
    free(path);
    const char *original = served ? served->original_path : NULL;
    size_t n = original ? strlen(original) : 0;
    if (n > 31 && !strncmp(original, "generated/decls/entitydef/", 26) && !strcmp(original + n - 5, ".decl") &&
        n - 31 < sizeof(authored)) { memcpy(authored, original + 26, n - 31); authored[n - 31] = 0; }
    if (pr_package_rows(view) != 1) {
        snprintf(view->placement, sizeof(view->placement), "its package's editor entries could not be read");
        goto done;
    }
    reason = sh_editor_rows_placement(&g_editor_rows, &view->package_rows, from, authored[0] ? authored : NULL,
        base, limit, view->placement, sizeof(view->placement));
done:
    ReleaseSRWLockExclusive(&g_editor_rows_lock);
    return reason;
}
#ifdef SH_PACKAGE_RUNTIME_TESTING
int sh_package_runtime_test_placement(const sh_package_compilation *compiled, const char *from, const char *base,
    int *engine, char *reason, size_t capacity)
{
    pr_provider provider; pr_inline_view view;
    sh_decl_carrier_limit limit = SH_DECL_CARRIER_GAP;
    memset(&provider, 0, sizeof(provider)); memset(&view, 0, sizeof(view));
    provider.compiled = (sh_package_compilation *)compiled;
    view.provider = &provider;
    sh_package_runtime_test_source_inputs(NULL, NULL, &view.originals.game, &view.originals.context);
    const char *why = pr_inline_placement(&view, from, base, &limit);
    snprintf(reason, capacity, "%s", why ? why : "");
    *engine = limit == SH_DECL_CARRIER_ENGINE;
    sh_editor_rows_free(&view.package_rows);
    return why ? (view.package_rows_state < 0 ? -1 : 0) : 1;
}
#endif

/* Whether a delivery the derived map would no longer select still carries
 * behavior the map needs. Unused bundle members are no requirement: package
 * definitions, stock-named edits included, compile under private identities
 * that only bound typed uses reach, and the recomputed selection keeps every
 * such use. Spawn registrations are private rows that only the package's own
 * bound requests select. What remains is shared state: a string the derived
 * map still names, a stock definition changed under its stock name (historical
 * composed contexts), cvar requirements, historical string keys and HUD
 * settings for shared weapons. The map needing one of them is a native limit,
 * since map data carries none of them. A shared effect whose consumers are not
 * modelled is unproven: a product gap. Returns 1 to keep (limit/reason set). */
static int pr_inline_published(const sh_compiled_resource *resource)
{
    const char *original = resource->original_path, *slash, *dot;
    char type[64], name[512];
    if (!original || !_stricmp(resource->engine_path, original)) return 1;
    if (strncmp(original, "generated/decls/", 16)) return 0;
    slash = strchr(original + 16, '/'); dot = strrchr(original, '.');
    if (!slash || !dot || dot <= slash || (size_t)(slash - original - 16) >= sizeof(type) ||
        (size_t)(dot - slash - 1) >= sizeof(name)) return 1;
    memcpy(type, original + 16, (size_t)(slash - original - 16)); type[slash - original - 16] = 0;
    memcpy(name, slash + 1, (size_t)(dot - slash - 1)); name[dot - slash - 1] = 0;
    return sh_package_resource_native_matches(resource, type, name);
}
/* A weapon identity every map shares: unchanged stock, or changed under its
 * stock name. Private linked weapons are reached only through package uses. */
static int pr_inline_shared_weapon(const pr_provider *provider, const char *name)
{
    size_t length = strlen(name) + sizeof("generated/decls/weapon/.decl");
    char *path = malloc(length);
    if (!path) return -1;
    snprintf(path, length, "generated/decls/weapon/%s.decl", name);
    const sh_compiled_resource *resource = sh_package_compilation_find(provider->compiled, path);
    free(path);
    if (!resource) return strncmp(name, "smp/", 4) != 0;
    return resource->baseline_known && pr_inline_published(resource);
}
static int pr_inline_mentions(const char *json, size_t length, const char *key)
{
    size_t n = strlen(key);
    for (size_t i = 1; n && json && i + n < length; i++)
        if (json[i - 1] == '"' && json[i + n] == '"' && !_strnicmp(json + i, key, n)) return 1;
    return 0;
}
/* A string key of the package's policy that the derived map still names. */
static int pr_inline_named_string(const sh_package_policy *policy, const char *json, size_t length,
    char *key, size_t capacity)
{
    int found = 0;
    for (size_t i = 0; !found && i < policy->strings.count; i++) {
        const char *raw = policy->strings.members[i].value_json;
        sh_json_object pairs = {0};
        if (!sh_json_parse_object(raw, strlen(raw), 2, &pairs)) return -1;
        for (size_t j = 0; !found && j < pairs.count; j++) {
            int n = snprintf(key, capacity, "#str_%s", pairs.members[j].key);
            found = n > 0 && (size_t)n < capacity && pr_inline_mentions(json, length, key);
        }
        sh_json_object_free(&pairs);
    }
    for (size_t i = 0; !found && i < policy->localized_count; i++)
        if (pr_inline_mentions(json, length, policy->localized[i].key)) {
            snprintf(key, capacity, "%s", policy->localized[i].key); found = 1;
        }
    return found;
}
static int pr_inline_requirement(const pr_provider *provider, const pr_original_source *originals, size_t package,
    const sh_package_references *closure, const char *derived, size_t derived_length, pr_inline_kept *kept)
{
    sh_package_owners owners = {0};
    sh_package_policy policy = {0};
    char error[256], key[256];
    const char *changed = NULL, *weapon = NULL;
    int inspected = sh_package_owners_add(&owners, package) &&
        sh_package_compilation_policy(provider->compiled, &owners, &policy, error, sizeof(error));
    sh_package_owners_free(&owners);
    kept->limit = SH_DECL_CARRIER_GAP;
    if (!inspected) {
        snprintf(kept->reason, sizeof(kept->reason), "its package's shared settings could not be inspected");
        return 1;
    }
    int named = pr_inline_named_string(&policy, derived, derived_length, key, sizeof(key));
    if (named) {
        kept->limit = named < 0 ? SH_DECL_CARRIER_GAP : SH_DECL_CARRIER_ENGINE;
        if (named < 0) snprintf(kept->reason, sizeof(kept->reason), "its package's strings could not be inspected");
        else snprintf(kept->reason, sizeof(kept->reason),
            "the map still names %s, a string its package supplies; map data cannot define strings", key);
        sh_package_policy_free(&policy); return 1;
    }
    for (size_t i = 0; i < provider->compiled->resource_count; i++) {
        const sh_compiled_resource *resource = provider->compiled->resources + i;
        if (!resource->baseline_known || resource->native_original || resource->restored_original ||
            !sh_package_owners_contains(&resource->gameplay_owners, package) || !pr_inline_published(resource)) continue;
        int same = pr_stock_copy(originals, provider->compiled, resource);
        if (same < 0) { sh_package_policy_free(&policy); return -1; }
        if (same) continue;
        const char *shown = resource->original_path ? resource->original_path : resource->engine_path;
        for (size_t r = 0; closure && r < closure->count; r++)
            if (closure->items[r].name && (!_stricmp(closure->items[r].name, resource->engine_path) ||
                (resource->original_path && !_stricmp(closure->items[r].name, resource->original_path)))) {
                kept->limit = SH_DECL_CARRIER_ENGINE;
                snprintf(kept->reason, sizeof(kept->reason), "the map still reaches %s, which its package changes "
                    "under the stock name; map data cannot change stock definitions", shown);
                sh_package_policy_free(&policy); return 1;
            }
        if (!changed) changed = shown;
    }
    for (size_t i = 0; !weapon && i < policy.hud.count + policy.hud_binding_count; i++) {
        const char *name = i < policy.hud.count ? policy.hud.members[i].key : policy.hud_bindings[i - policy.hud.count].name;
        int shared = pr_inline_shared_weapon(provider, name);
        if (shared < 0) { sh_package_policy_free(&policy); return -1; }
        if (shared) weapon = name;
    }
    int keep = 1;
    if (policy.requirements.count)
        snprintf(kept->reason, sizeof(kept->reason),
            "its package lifts SnapMap's resource blacklist, and whether the native map needs that is not modelled");
    else if (policy.strings.count && sh_package_owners_contains(&provider->compiled->policy.legacy_string_owners, package))
        snprintf(kept->reason, sizeof(kept->reason),
            "its package's historical strings use shared keys whose other consumers are not modelled");
    else if (weapon)
        snprintf(kept->reason, sizeof(kept->reason),
            "its package sets HUD presentation for the shared weapon %s, whose use is not modelled", weapon);
    else if (changed)
        snprintf(kept->reason, sizeof(kept->reason), closure && !closure->incomplete ?
            "its package changes %s under the stock name, and consumers outside this map's references are not modelled" :
            "its package changes %s under the stock name, and the map's dependency coverage is incomplete", changed);
    else keep = 0;
    sh_package_policy_free(&policy);
    return keep;
}

static int pr_inline_add_kept(pr_inline_view *view, const unsigned char tree[32], const pr_inline_kept *kept)
{
    for (size_t i = 0; i < view->kept_count; i++) if (!memcmp(view->kept[i].tree, tree, 32)) return 1;
    pr_inline_kept *grown = realloc(view->kept, (view->kept_count + 1) * sizeof(*grown));
    if (!grown) return 0;
    view->kept = grown; view->kept[view->kept_count] = *kept;
    memcpy(view->kept[view->kept_count++].tree, tree, 32);
    return 1;
}

/* How a kept use is reported: a selected-plan conflict, a native limit, or a
 * product gap (support not established). */
static const char *pr_inline_kept_kind(const sh_native_inline_site *site)
{
    return site->conflict ? "plan conflict" : site->limit == SH_DECL_CARRIER_ENGINE ? "native limit" : "product gap";
}
static char *pr_inline_report(const sh_native_inline_report *report)
{
    size_t length = 1;
    for (size_t i = 0; i < report->count; i++) {
        const sh_native_inline_site *site = report->sites + i;
        length += 192 + strlen(site->reason) + (site->from ? strlen(site->from) : 0) + (site->to ? strlen(site->to) : 0) +
            (site->owner ? strlen(site->owner) : 0) + (site->reference ? strlen(site->reference) : 0);
    }
    for (size_t i = 0; i < report->substitution_count; i++)
        if (report->substitutions[i].drop)
            length += 64 + strlen(report->substitutions[i].from) + strlen(report->substitutions[i].to);
    for (const char *line = report->notes; line && *line; line++) length += *line == '\n' ? 8 : 1;
    if (report->notes) length += 8;
    char *text = malloc(length), *at = text;
    if (!text) return NULL;
    *at = 0;
    for (size_t i = 0; i < report->count; i++) {
        const sh_native_inline_site *site = report->sites + i;
        int written = site->owner ? (site->converted && site->retargeted ?
            snprintf(at, length - (size_t)(at - text), "%s %s: %s -> native %s (independent use; %zu exact-identity %s "
                "renamed with it)\n", site->owner, site->reference, site->from, site->to, site->retargeted,
                site->retargeted == 1 ? "operand" : "operands") :
            site->converted ?
            snprintf(at, length - (size_t)(at - text), "%s %s: %s -> native %s (independent use%s)\n", site->owner,
                site->reference, site->from, site->to, site->sigma || site->carried ? "; holder substitution" : "") :
            snprintf(at, length - (size_t)(at - text), "%s %s: %s kept (%s): %s\n", site->owner, site->reference,
                site->from, pr_inline_kept_kind(site), site->reason)) :
            site->converted && site->retargeted ?
            snprintf(at, length - (size_t)(at - text), "entity %zu: %s -> native %s (%zu map-local %s its copy, "
                "%zu ancestry %s retargeted to it%s)\n", site->entity, site->from, site->to, site->renamed,
                site->renamed == 1 ? "use follows" : "uses follow", site->retargeted,
                site->retargeted == 1 ? "filter" : "filters", site->sigma ? "; holder substitution" : "") :
            site->converted && site->renamed ?
            snprintf(at, length - (size_t)(at - text), "entity %zu: %s -> native %s (%zu map-local %s its copy%s)\n",
                site->entity, site->from, site->to, site->renamed, site->renamed == 1 ? "use follows" : "uses follow",
                site->sigma ? "; holder substitution" : "") :
            site->converted ?
            snprintf(at, length - (size_t)(at - text), "entity %zu: %s -> native %s%s\n", site->entity, site->from, site->to,
                site->sigma ? " (holder substitution)" : "") :
            snprintf(at, length - (size_t)(at - text), "entity %zu: %s kept (%s): %s\n", site->entity, site->from,
                pr_inline_kept_kind(site), site->reason);
        if (written > 0) at += written;
    }
    /* A served loot drop the plan names its native drop in place of. */
    for (size_t i = 0; i < report->substitution_count; i++) {
        const sh_native_inline_substitution *row = report->substitutions + i;
        if (!row->drop) continue;
        int written = snprintf(at, length - (size_t)(at - text), "loot drop %s -> native %s (holder substitution)\n",
            row->from, row->to);
        if (written > 0) at += written;
    }
    /* How the plan's loot drop entries were decided (diagnostic). */
    for (const char *line = report->notes; line && *line;) {
        const char *end = strchr(line, '\n');
        size_t n = end ? (size_t)(end - line) : strlen(line);
        int written = snprintf(at, length - (size_t)(at - text), "plan: %.*s\n", (int)n, line);
        if (written > 0) at += written;
        line += n + (end != NULL);
    }
    return text;
}

/* ---- the settled derived document, re-read (H3) ---- */
#ifdef SH_PACKAGE_RUNTIME_TESTING
static int g_test_derived_fault;
void sh_package_runtime_test_derived_fault(int mode) { g_test_derived_fault = mode; }
#endif
/* Whether two uses name their saved definition through the same suppliers:
 * equal context sets (mode, trees, component), order aside. */
static int pr_derived_supplier_same(const sh_package_provenance *a, const sh_package_provenance_use *x,
    const sh_package_provenance *b, const sh_package_provenance_use *y)
{
    if (x->binding >= a->binding_count || y->binding >= b->binding_count ||
        strcmp(a->bindings[x->binding].name, b->bindings[y->binding].name) || x->context_count != y->context_count) return 0;
    for (size_t i = 0; i < x->context_count; i++) {
        if (x->contexts[i] >= a->context_count) return 0;
        const sh_package_provenance_context *p = a->contexts + x->contexts[i];
        int found = 0;
        for (size_t j = 0; j < y->context_count && !found; j++) {
            if (y->contexts[j] >= b->context_count) return 0;
            const sh_package_provenance_context *q = b->contexts + y->contexts[j];
            found = p->mode == q->mode && p->tree_count == q->tree_count &&
                (!p->tree_count || !memcmp(p->trees, q->trees, p->tree_count * sizeof(*p->trees))) &&
                (p->component ? q->component && !strcmp(p->component, q->component) : !q->component);
        }
        if (!found) return 0;
    }
    return 1;
}
/* A live use the derived document no longer lists is one the plan converted:
 * an independent use or an operand renamed with it, a converted placed
 * occurrence's own inherit, or an ancestry filter retargeted to its copy. */
static int pr_derived_converted(const sh_native_inline_report *sites, const sh_package_provenance_use *use)
{
    for (size_t k = 0; use->owner && use->reference && k < sites->count; k++) {
        const sh_native_inline_site *site = sites->sites + k;
        if (!site->converted) continue;
        if (site->owner && !strcmp(site->owner, use->owner) && !strcmp(site->reference, use->reference)) return 1;
        if (!site->owner) {
            char owner[32];
            snprintf(owner, sizeof(owner), "entity/%zu", site->entity);
            if (!strcmp(owner, use->owner) && !strcmp(use->reference, "/k:entityDef/k:inherit")) return 1;
        }
        for (size_t r = 0; r < site->retargeted; r++)
            if (!strcmp(site->retargets[r].owner, use->owner) && !strcmp(site->retargets[r].reference, use->reference))
                return 1;
    }
    return 0;
}
static const sh_package_provenance_use *pr_derived_use(const sh_package_provenance *uses, const char *owner,
    const char *reference)
{
    for (size_t i = 0; uses && owner && reference && i < uses->use_count; i++)
        if (uses->uses[i].owner && uses->uses[i].reference && !strcmp(uses->uses[i].owner, owner) &&
            !strcmp(uses->uses[i].reference, reference)) return uses->uses + i;
    return NULL;
}
/* The same site's other spelling: a projected inherited member (R-249,
 * "<member>#projected") a converted copy states as its own member, or back. */
static const sh_package_provenance_use *pr_derived_projection(const sh_package_provenance *uses,
    const sh_package_provenance_use *use, int projected)
{
    char reference[600];
    size_t length = use->reference ? strlen(use->reference) : 0;
    if (projected) {
        if ((size_t)snprintf(reference, sizeof(reference), "%s#projected", use->reference ? use->reference : "") >=
            sizeof(reference)) return NULL;
    } else {
        if (length <= 10 || strcmp(use->reference + length - 10, "#projected") || length - 10 >= sizeof(reference)) return NULL;
        memcpy(reference, use->reference, length - 10); reference[length - 10] = 0;
    }
    return pr_derived_use(uses, use->owner, reference);
}
/* Whether every supplier of use (in a) is one of origin's (in b): a value a
 * converted occurrence now states came from the chain its inherit read. */
static int pr_derived_suppliers_within(const sh_package_provenance *a, const sh_package_provenance_use *use,
    const sh_package_provenance *b, const sh_package_provenance_use *origin)
{
    for (size_t i = 0; i < use->context_count; i++) {
        if (use->contexts[i] >= a->context_count) return 0;
        const sh_package_provenance_context *p = a->contexts + use->contexts[i];
        int found = 0;
        for (size_t j = 0; j < origin->context_count && !found; j++) {
            if (origin->contexts[j] >= b->context_count) return 0;
            const sh_package_provenance_context *q = b->contexts + origin->contexts[j];
            found = p->mode == q->mode && p->tree_count == q->tree_count &&
                (!p->tree_count || !memcmp(p->trees, q->trees, p->tree_count * sizeof(*p->trees))) &&
                (p->component ? q->component && !strcmp(p->component, q->component) : !q->component);
        }
        if (!found) return 0;
    }
    return use->context_count > 0;
}
/* Whether a value a converted occurrence now states names an exact duplicate
 * of a definition its inherit's suppliers provide: the exact-dedupe contract
 * gives byte-identical units one linked identity, so one name, and the
 * compiled declaration under that name is served from those copies alone.
 * Every supplier of use must be the package of one of the copies, and one
 * copy must be in a package origin names; a byte-different copy is another
 * identity and never qualifies. */
static int pr_derived_exact_duplicate(const pr_inline_view *view, const sh_package_provenance *a,
    const sh_package_provenance_use *use, const sh_package_provenance *b, const sh_package_provenance_use *origin)
{
    const sh_package_compilation *compiled = view->provider->compiled;
    if (!compiled || !compiled->sources || use->binding >= a->binding_count || !use->context_count) return 0;
    const sh_package_provenance_binding *binding = a->bindings + use->binding;
    if (!binding->family || !binding->name) return 0;
    char path[640];
    if ((size_t)snprintf(path, sizeof(path), "generated/decls/%s/%s.decl", binding->family, binding->name) >= sizeof(path))
        return 0;
    const sh_compiled_resource *resource = sh_package_compilation_find(compiled, path);
    if (!pr_exact_unit(compiled, resource)) return 0;
    const sh_package_sources *sources = compiled->sources;
    int within = 0;
    for (size_t i = 0; i < resource->source_count; i++) {
        const sh_package_source_file *file = sources->files + resource->sources[i];
        const unsigned char *tree = sh_package_source_tree(sources, file->owner);
        for (size_t j = 0; tree && j < origin->context_count && !within; j++) {
            if (origin->contexts[j] >= b->context_count) return 0;
            const sh_package_provenance_context *q = b->contexts + origin->contexts[j];
            for (size_t t = 0; t < q->tree_count && !within; t++) within = !memcmp(q->trees[t], tree, 32);
        }
    }
    if (!within) return 0;
    for (size_t c = 0; c < use->context_count; c++) {
        if (use->contexts[c] >= a->context_count) return 0;
        const sh_package_provenance_context *p = a->contexts + use->contexts[c];
        int found = 0;
        if (p->mode != SH_PACKAGE_CONTEXT_ISOLATED || p->tree_count != 1) return 0;
        for (size_t i = 0; i < resource->source_count && !found; i++) {
            const unsigned char *tree = sh_package_source_tree(sources, sources->files[resource->sources[i]].owner);
            found = tree && !memcmp(tree, p->trees[0], 32);
        }
        if (!found) return 0;
    }
    return 1;
}
/* The settled derived document re-read under its own ownership, as reopening
 * it reads it: every live use it no longer lists was converted by the plan;
 * every use it lists keeps the live use's saved definition and suppliers at
 * the same site, or, new at a converted copy, a live use's or an exact
 * duplicate of one (pr_derived_exact_duplicate); the native
 * decisions taken again from the sources it now delivers convert nothing
 * more, fail nothing and decide every use the plan keeps again from a
 * definition those sources serve; and the count observations the plan's holder
 * substitution was decided on (in live, as source reads it) are those the
 * derived document's own sources observe, with the substitution applied
 * (sh_native_inline_observations). Those sources are the deliveries it keeps
 * (delivered, when given) and the native originals. 1 verified, 0 not (error
 * says why), -1 failure. */
static int pr_native_derived(const pr_inline_view *view, const sh_native_inline_source *source,
    const sh_native_inline_report *plan, const sh_package_provenance *before, const sh_package_provenance *after,
    const sh_package_references *typed, const sh_package_map_local_uses *local, const char *json, size_t length,
    const char *live, size_t live_length, const sh_mpkg_used *delivered, size_t delivered_count, char *error,
    size_t capacity)
{
#ifdef SH_PACKAGE_RUNTIME_TESTING
    /* Fault control 4: the re-read fails operationally. */
    if (g_test_derived_fault == 4) { snprintf(error, capacity, "derived re-read fault control"); return -1; }
#endif
    for (size_t i = 0; before && i < before->use_count; i++) {
        const sh_package_provenance_use *use = before->uses + i;
        const sh_package_provenance_use *now = pr_derived_use(after, use->owner, use->reference);
        if (!now && (now = pr_derived_projection(after, use, 0)) != NULL && pr_derived_supplier_same(before, use, after, now))
            continue;
        if (now ? pr_derived_supplier_same(before, use, after, now) : pr_derived_converted(plan, use)) continue;
        snprintf(error, capacity, "the derived document %s the use at %s %s", now ? "changes the definition or suppliers of" :
            "drops, without converting it,", use->owner ? use->owner : "?", use->reference ? use->reference : "?");
        return 0;
    }
    for (size_t i = 0; after && i < after->use_count; i++) {
        const sh_package_provenance_use *use = after->uses + i;
        if (pr_derived_use(before, use->owner, use->reference)) continue;
        const sh_package_provenance_use *projection = pr_derived_projection(before, use, 1);
        if (projection && pr_derived_supplier_same(after, use, before, projection)) continue;
        /* A value of the chain a converted occurrence now states names its
         * definition through suppliers its inherit read. */
        const sh_package_provenance_use *origin = pr_derived_use(before, use->owner, "/k:entityDef/k:inherit");
        int converted = 0;
        for (size_t k = 0; origin && k < plan->count && !converted; k++) {
            char owner[32];
            snprintf(owner, sizeof(owner), "entity/%zu", plan->sites[k].entity);
            converted = !plan->sites[k].owner && plan->sites[k].converted && use->owner && !strcmp(owner, use->owner);
        }
        if (converted && (pr_derived_suppliers_within(after, use, before, origin) ||
            pr_derived_exact_duplicate(view, after, use, before, origin))) continue;
        snprintf(error, capacity, "the derived document adds the use at %s %s, whose definition and suppliers no use of "
            "the original has", use->owner ? use->owner : "?", use->reference ? use->reference : "?");
        return 0;
    }
    /* Its own sources are the deliveries it keeps, each one this session
     * holds: a delivery it does not hold (a retained copy, possibly another
     * variant of a package this session serves) serves text no re-read here
     * can see, neither this session's copy nor the native original. */
    for (size_t j = 0; delivered && j < delivered_count; j++) {
        const unsigned char *tree = delivered[j].bundle ? sh_package_bundle_fingerprint(delivered[j].bundle) : NULL;
        int held = 0;
        for (size_t p = 0; tree && p < view->provider->bundle_count && !held; p++) {
            const unsigned char *candidate = sh_package_bundle_fingerprint(view->provider->bundles[p]);
            held = candidate && !memcmp(candidate, tree, 32);
        }
        if (held) continue;
        snprintf(error, capacity, "the derived document delivers '%s', which this session's sources do not hold",
            delivered[j].name[0] ? delivered[j].name : delivered[j].id);
        return 0;
    }
    pr_inline_view derived = *view;
    derived.uses = after; derived.typed = *typed; derived.local = *local;
    memset(&derived.package_rows, 0, sizeof(derived.package_rows)); derived.package_rows_state = 0;
    derived.delivered = delivered; derived.delivered_count = delivered_count; derived.delivered_only = delivered != NULL;
    sh_native_inline_source again = *source;
    again.context = &derived;
    sh_native_inline_report sites = {0};
    size_t again_length = 0;
    char reason[512] = "";
    char *again_json = sh_native_inline_document(json, length, &again, &again_length, &sites, reason, sizeof(reason));
    int result = 1;
    if (!again_json) {
        snprintf(error, capacity, "the derived document's native representation does not re-verify: %s", reason);
        result = 0;
    }
    for (size_t k = 0; result == 1 && k < sites.count; k++) {
        const sh_native_inline_site *site = sites.sites + k;
        if (!site->converted) continue;
        if (site->owner) snprintf(error, capacity, "the derived document is not settled: %s %s converts again to '%s'",
            site->owner, site->reference, site->to);
        else snprintf(error, capacity, "the derived document is not settled: entity %zu converts again to '%s'", site->entity,
            site->to);
        result = 0;
    }
    /* Every use the plan keeps is decided again from a definition the derived
     * document's own sources serve, as the map still reads it. */
    for (size_t k = 0; result == 1 && k < plan->count; k++) {
        const sh_native_inline_site *kept = plan->sites + k;
        int found = 0;
        if (kept->converted) continue;
        for (size_t j = 0; j < sites.count && !found; j++) {
            const sh_native_inline_site *site = sites.sites + j;
            found = kept->owner ? site->owner && site->reference && kept->reference && !strcmp(site->owner, kept->owner) &&
                !strcmp(site->reference, kept->reference) : !site->owner && site->entity == kept->entity;
        }
        if (found) continue;
        if (kept->owner) snprintf(error, capacity, "the derived document's own sources do not serve '%s', which the use at "
            "%s %s keeps", kept->from, kept->owner, kept->reference ? kept->reference : "?");
        else snprintf(error, capacity, "the derived document's own sources do not serve '%s', which entity %zu keeps", kept->from,
            kept->entity);
        result = 0;
    }
    if (result == 1) {
#ifdef SH_PACKAGE_RUNTIME_TESTING
        /* Fault control 3: the observations are read from the original document. */
        const char *observed_json = g_test_derived_fault == 3 ? live : json;
        size_t observed_length = g_test_derived_fault == 3 ? live_length : length;
#else
        const char *observed_json = json;
        size_t observed_length = length;
#endif
        char observed[512] = "";
        int same = sh_native_inline_observations(source, live, live_length, plan, &again, observed_json, observed_length,
            observed, sizeof(observed));
        if (same < 0) {
            snprintf(error, capacity, "the derived document's observations cannot be read");
            result = -1;
        } else if (!same) {
            snprintf(error, capacity, "the derived document's own sources observe the plan differently: %s", observed);
            result = 0;
        }
    }
    sh_native_inline_report_free(&sites); free(again_json); sh_editor_rows_free(&derived.package_rows);
    return result;
}

/* planned, when given, receives the plan's sites as last decided; a plan the
 * caller does not take is withdrawn there (sh_native_inline_withdraw). */
static int pr_native_document(const pr_provider *provider, sh_decl_registry_source registry, uintptr_t reflection,
    sh_decl_native_source metadata, int retain_native, const sh_package_provenance *saved,
    const sh_package_bundle_binding *additional, size_t additional_count, const char *json, size_t length,
    char **derived, size_t *derived_length, sh_package_occurrence_snapshot **ownership,
    sh_mpkg_used **deliveries, size_t *delivery_count, pr_key_context *keys, sh_native_inline_report *planned,
    char *error, size_t capacity)
{
    pr_inline_view view = {0};
    pr_inline_hints hints = {0};
    sh_package_occurrence_snapshot *live = NULL, *next = NULL;
    sh_mpkg_used *live_used = NULL, *next_used = NULL;
    size_t live_count = 0, next_count = 0, live_length = 0, next_length = 0;
    char *live_json = NULL, *next_json = NULL, *output = NULL;
    sh_native_inline_report sites = {0};
    sh_package_references closure = {0}, next_typed = {0};
    sh_package_map_local_uses next_local = {0};
    int result = -1;
    if (!provider || !provider->compiled) goto done;
    live_json = pr_capture_document(provider, registry, reflection, retain_native, saved, additional, additional_count,
        json, length, &live_length, &live, &live_used, &live_count, NULL, &view.typed, &view.local, keys, error, capacity);
    if (!live_json) goto done;
    view.provider = provider; view.uses = sh_package_occurrence_provenance(live);
    view.native_source = registry; view.hints = &hints;
    view.originals = (pr_original_source){provider->catalog ? sh_resource_catalog_read_path : NULL,
        provider->catalog, provider->native_assets};
#ifdef SH_PACKAGE_RUNTIME_TESTING
    sh_package_runtime_test_source_inputs(NULL, NULL, &view.originals.game, &view.originals.context);
#endif
    metadata.reflection = reflection;
    view.schema = sh_decl_native_schema_open(metadata, (sh_decl_dependency_observer){0}, error, capacity);
    if (!view.schema) goto done;
    view.registry = sh_decl_native_registry_open(registry, NULL, 0);
    sh_decl_native_schema_attach_registry(view.schema, view.registry);
#ifndef SH_PACKAGE_RUNTIME_TESTING
    {
        int renderer = sh_host_is_vulkan();
        view.name_events = (sh_native_event_source){metadata.context, metadata.read,
            (uintptr_t)sh_typeinfo_get_declmgr(),
            renderer >= 0 && sh_host_is_pinned_renderer_build(renderer)};
    }
#endif
    sh_native_inline_source source = {&view, pr_inline_read, pr_inline_derives,
        sh_decl_native_schema_view(view.schema), pr_inline_looked_up, pr_inline_keep, PR_ENTITY_STATE_VERSION,
        pr_inline_placement, pr_inline_evaluate, pr_inline_read_decl, pr_inline_typed_name, pr_inline_local_use,
        pr_inline_served_decl, pr_inline_bound_use, pr_inline_resolve_decl, view.schema, pr_inline_discarded_name_event,
        pr_inline_event_decl_constructs, pr_inline_read_asset, pr_inline_hint_bank, pr_inline_hint_lookup};
    /* A pass that neither settles nor converts nothing keeps at least one more
     * delivery, and kept holds distinct trees of the live map's live_count used
     * bundles (pr_inline_add_kept, its only growth), so at most live_count
     * passes grow it and the next one settles. A fixed cap would report a
     * valid map needing more deliveries as unsettled. */
    for (size_t pass = 0; pass <= live_count; pass++) {
        size_t converted = 0, output_length = 0;
        sh_native_inline_report_free(&sites);
        free(output); output = sh_native_inline_document(live_json, live_length, &source, &output_length, &sites, error, capacity);
        if (!output) goto done;
        for (size_t i = 0; i < sites.count; i++) converted += sites.sites[i].converted != 0;
        if (!converted) { result = 0; goto done; }
        sh_package_occurrence_release(next); next = NULL;
        sh_mpkg_used_free(next_used); next_used = NULL; free(next_json);
        sh_package_references_free(&closure);
        next_json = pr_capture_document(provider, registry, reflection, retain_native, saved, additional, additional_count,
            output, output_length, &next_length, &next, &next_used, &next_count, &closure, &next_typed, &next_local, keys,
            error, capacity);
#ifdef SH_PACKAGE_RUNTIME_TESTING
        /* Fault control 5: the derived document's capture fails. */
        if (g_test_derived_fault == 5 && next_json) {
            free(next_json); next_json = NULL;
            if (error && capacity) snprintf(error, capacity, "derived capture fault control");
        }
#endif
        if (!next_json) {
            /* Nothing converts: the report says why the derived document was not taken. */
            char reason[sizeof(sites.sites->reason)];
            snprintf(reason, sizeof(reason), "the derived document cannot be captured: %s", error && capacity ? error : "");
            sh_native_inline_withdraw(&sites, SH_DECL_CARRIER_GAP, reason);
            goto done;
        }
        /* Recompute ownership: a delivery the derived map drops must not take
         * behavior the map still needs with it; keep its uses and try again. */
        size_t kept_before = view.kept_count;
        for (size_t i = 0; i < live_count; i++) {
            int present = 0;
            for (size_t j = 0; j < next_count && !present; j++) present = !strcmp(live_used[i].id, next_used[j].id);
            if (present) continue;
            const unsigned char *tree = sh_package_bundle_fingerprint(live_used[i].bundle);
            if (!tree) goto done;
            size_t package = SIZE_MAX;
            for (size_t p = 0; p < provider->bundle_count; p++) {
                const unsigned char *candidate = sh_package_bundle_fingerprint(provider->bundles[p]);
                if (candidate && !memcmp(candidate, tree, 32)) { package = p; break; }
            }
            pr_inline_kept kept = {{0}, SH_DECL_CARRIER_GAP, "a retained copy's delivery cannot be inspected here"};
            int keep = package == SIZE_MAX ? 1 :
                pr_inline_requirement(provider, &view.originals, package, &closure, next_json, next_length, &kept);
            if (keep < 0 || (keep && !pr_inline_add_kept(&view, tree, &kept))) goto done;
        }
        if (view.kept_count == kept_before) {
#ifdef SH_PACKAGE_RUNTIME_TESTING
            /* Fault controls: 1 re-reads the original document as the derived
             * one, whose uses then convert again; 2 lists no derived use; 3
             * reads the derived observations from the original document. */
            int fault = g_test_derived_fault;
#else
            int fault = 0;
#endif
            int verified = fault == 1 ?
                pr_native_derived(&view, &source, &sites, view.uses, view.uses, &view.typed, &view.local, live_json,
                    live_length, live_json, live_length, NULL, 0, error, capacity) :
                pr_native_derived(&view, &source, &sites, view.uses, fault == 2 ? NULL :
                    sh_package_occurrence_provenance(next), &next_typed, &next_local, next_json, next_length, live_json,
                    live_length, next_used, next_count, error, capacity);
            if (verified <= 0) {
                /* Nothing converts: the report says why the plan was withdrawn
                 * (a failed re-read is withdrawn with the document). */
                if (!verified) { sh_native_inline_withdraw(&sites, SH_DECL_CARRIER_GAP, error); result = 0; }
                goto done;
            }
            *derived = next_json; next_json = NULL; *derived_length = next_length;
            sh_package_occurrence_release(*ownership); *ownership = next; next = NULL;
            sh_mpkg_used_free(*deliveries); *deliveries = next_used; next_used = NULL; *delivery_count = next_count;
            result = 1; goto done;
        }
    }
    if (error && capacity) snprintf(error, capacity, "native representation did not settle");
done:
    if (planned) { *planned = sites; memset(&sites, 0, sizeof(sites)); }
    sh_native_inline_report_free(&sites);
    if (view.schema) sh_decl_native_schema_close(view.schema);
    if (view.registry) sh_decl_native_registry_close(view.registry);
    pr_inline_hints_clear(&hints);
    sh_editor_rows_free(&view.package_rows);
    free(view.kept); free(output); free(live_json); free(next_json); sh_package_references_free(&closure);
    sh_package_references_free(&next_typed); sh_package_map_local_uses_free(&next_local);
    sh_package_references_free(&view.typed); sh_package_map_local_uses_free(&view.local);
    sh_package_occurrence_release(live); sh_package_occurrence_release(next);
    sh_mpkg_used_free(live_used); sh_mpkg_used_free(next_used);
    return result;
}

int sh_package_runtime_native_document(const sh_package_map_plan *plan,
    const sh_package_provenance *saved, const sh_package_bundle_binding *additional,
    size_t additional_count, const char *json, size_t length,
    char **derived, size_t *derived_length, sh_package_occurrence_snapshot **ownership,
    sh_mpkg_used **deliveries, size_t *delivery_count, char **report,
    char *error, size_t capacity)
{
    int result = -1;
    char *pending = NULL; size_t pending_length = 0, pending_count = 0;
    sh_package_occurrence_snapshot *pending_ownership = NULL;
    sh_mpkg_used *pending_deliveries = NULL;
    sh_native_inline_report planned = {0};
    if (error && capacity) *error = 0;
    if (!derived || !derived_length || !ownership || !deliveries || !delivery_count || !json) return -1;
    int refresh_entered = !g_activation_callback && !pr_refresh_held();
    if (refresh_entered) pr_refresh_acquire(1);
    AcquireSRWLockShared(&g_lock);
    pr_key_context keys;
    pr_key_context_open(&keys, plan ? plan->provider : pr_open_map() ? pr_open_map() : g_library_provider);
#ifndef SH_PACKAGE_RUNTIME_TESTING
    sh_decl_registry_source registry = {0};
    sh_decl_native_source metadata = {NULL, pr_native_read, 0, g_native_scripts};
    if (sh_decl_server_registry_source(&registry) && sh_decl_native_source_ready(&metadata,
        g_native_accessor, g_native_types, g_native_game_system) == 1)
        result = pr_native_document(plan ? plan->provider : pr_reader(), registry, metadata.reflection, metadata,
            !plan, saved, additional, additional_count, json, length, &pending, &pending_length,
            &pending_ownership, &pending_deliveries, &pending_count, &keys, report ? &planned : NULL, error, capacity);
#else
    sh_decl_registry_source registry = {0}; uintptr_t reflection = 0;
    sh_decl_native_source metadata = {NULL, pr_native_read, 0, NULL};
    if (sh_package_runtime_test_source_inputs(&registry, &reflection, NULL, NULL) && (metadata.scripts = registry.scripts, 1))
        result = pr_native_document(plan ? plan->provider : pr_reader(), registry, reflection, metadata,
            !plan, saved, additional, additional_count, json, length, &pending, &pending_length,
            &pending_ownership, &pending_deliveries, &pending_count, &keys, report ? &planned : NULL, error, capacity);
#endif
    ReleaseSRWLockShared(&g_lock);
    if (!pr_key_context_close(&keys, result == 1)) {
        if (result == 1 && error && capacity) snprintf(error, capacity, "map registration dictionary could not be published");
        if (result == 1) result = -1;
    }
    /* A plan not taken keeps every use it would convert, its report saying
     * why, with no success annotation left; the input document is unchanged. */
    if (result != 1) {
        char reason[sizeof(planned.sites->reason)];
        snprintf(reason, sizeof(reason), "the native document was not produced: %s",
            error && capacity && *error ? error : "its preparation failed");
        sh_native_inline_withdraw(&planned, SH_DECL_CARRIER_GAP, reason);
    }
    if (report && planned.count) { free(*report); *report = pr_inline_report(&planned); }
    sh_native_inline_report_free(&planned);
    if (result == 1) {
        free(*derived); *derived = pending; pending = NULL; *derived_length = pending_length;
        sh_package_occurrence_release(*ownership); *ownership = pending_ownership; pending_ownership = NULL;
        sh_mpkg_used_free(*deliveries); *deliveries = pending_deliveries; pending_deliveries = NULL;
        *delivery_count = pending_count;
    }
    free(pending); sh_package_occurrence_release(pending_ownership); sh_mpkg_used_free(pending_deliveries);
    if (refresh_entered) pr_refresh_release(1);
    return result;
}

#ifdef SH_PACKAGE_RUNTIME_TESTING
int sh_package_runtime_test_exact_type(uint32_t type)
{
#ifdef PR_NATIVE_SPAWN
    return sh_spawn_keys_test_exact(type);
#else
    int found = 0;
    AcquireSRWLockShared(&g_lock);
    for (size_t i = 0; g_current_provider && i < g_current_provider->exact_modifier_count; i++)
        if (g_current_provider->exact_modifier_types[i] == type) { found = 1; break; }
    ReleaseSRWLockShared(&g_lock); return found;
#endif
}
int sh_package_runtime_test_unmodified_type(uint32_t type)
{
#ifdef PR_NATIVE_SPAWN
    return sh_spawn_keys_test_unmodified(type);
#else
    int found = 0;
    AcquireSRWLockShared(&g_lock);
    for (size_t i = 0; g_current_provider && i < g_current_provider->unmodified_count; i++)
        if (g_current_provider->unmodified_types[i] == type) { found = 1; break; }
    ReleaseSRWLockShared(&g_lock); return found;
#endif
}
void sh_package_runtime_test_plan_key_table(sh_package_map_plan *plan, const sh_package_key_groups *table)
{
    if (!plan || !plan->provider) abort();
    free(plan->provider->key_groups); plan->provider->key_groups = NULL;
    if (table) {
        plan->provider->key_groups = malloc(sizeof(*table));
        if (!plan->provider->key_groups) abort();
        *plan->provider->key_groups = *table;
    }
}
const sh_package_provenance *sh_package_runtime_test_plan_bindings(const sh_package_map_plan *plan, int installed)
{
    const pr_provider *provider = plan ? installed ? plan->authoring : plan->provider : NULL;
    return provider ? &provider->bindings : NULL;
}
void sh_package_runtime_test_serving_key_table(sh_package_key_groups *table)
{
    AcquireSRWLockShared(&g_lock);
    memset(table, 0, sizeof(*table));
    if (g_current_provider && g_current_provider->key_groups) *table = *g_current_provider->key_groups;
    ReleaseSRWLockShared(&g_lock);
}
void sh_package_runtime_test_key_tables(const sh_package_key_groups *library, const sh_package_key_groups *map)
{
    PR_LOCK_EXCLUSIVE();
    pr_provider *owners[2] = {g_library_provider, g_map_provider};
    const sh_package_key_groups *tables[2] = {library, map};
    for (int i = 0; i < 2; i++) if (owners[i]) {
        free(owners[i]->key_groups); owners[i]->key_groups = NULL;
        if (tables[i] && (owners[i]->key_groups = malloc(sizeof(*tables[i])))) *owners[i]->key_groups = *tables[i];
    }
    if (g_current_provider && g_current_provider != g_library_provider && g_current_provider != g_map_provider) {
        char error[256] = "";
        free(g_current_provider->key_groups); g_current_provider->key_groups = NULL;
        if (!pr_key_groups_add(g_current_provider, g_library_provider, error, sizeof(error)) ||
            !pr_key_groups_add(g_current_provider, g_map_provider, error, sizeof(error))) abort();
    }
    if (g_current_provider) {
        char error[256];
        if (!pr_prepare_spawn_program(g_current_provider, 0, error, sizeof(error))) abort();
    }
    pr_publish_key_groups();
    PR_UNLOCK_EXCLUSIVE();
}
int sh_package_runtime_test_watched_change(void)
{
    return InterlockedCompareExchange(&g_watched_change, 0, 0) != 0;
}
int sh_package_runtime_test_key_groups_current(void)
{
    AcquireSRWLockShared(&g_lock);
    int current = g_test_key_groups[0] == g_current_provider &&
        g_test_key_groups[1] == (g_current_provider ? g_current_provider->key_groups : NULL);
#ifdef PR_NATIVE_SPAWN
    sh_package_key_groups empty = {0};
    const sh_package_key_groups *expected = g_current_provider && g_current_provider->key_groups ?
        g_current_provider->key_groups : &empty;
    const sh_package_key_groups *published = sh_spawn_keys_test_hold();
    current = current && !memcmp(expected, published, sizeof(*expected));
    sh_spawn_keys_test_release();
#endif
    ReleaseSRWLockShared(&g_lock);
    return current;
}
/* Compose one unchanged original row an increment left native into a served
 * library compilation, as pr_increment_view does (test_increment_native_witness). */
int sh_package_runtime_test_witness_compose(sh_package_compilation *served, const sh_compiled_resource *original,
    char *error, size_t capacity)
{
    pr_provider increment = {0};
    sh_package_compilation one = {0}; one.resources = (sh_compiled_resource *)original; one.resource_count = 1;
    int ok = pr_native_witnesses_capture(&one, &increment.native_witnesses, &increment.native_witness_count, error, capacity) &&
        increment.native_witness_count == 1 && pr_native_witnesses_compose(served, &increment, NULL, error, capacity);
    pr_native_witnesses_free(increment.native_witnesses, increment.native_witness_count); return ok;
}
int sh_package_runtime_test_library_digest(char digest[65])
{
    pr_refresh_acquire(0);
    int ok = g_library_provider && pr_library_digest(g_library_provider->compiled, digest);
    pr_refresh_release(0); return ok;
}
void sh_package_runtime_test_dispose(void)
{
    pr_provider *current, *library, *map;
    pr_inventory *inventory;
    pr_refresh_acquire(1);
    {
        char error[1024]; int committed = 0;
        if (g_activation_finish.finish) pr_activation_finish(0,&committed,error,sizeof(error));
        /* Fixture teardown resets its intentional damaged-cleanup seam. This
         * is never a production recovery or native destructor retry. */
        if (!g_activation_finish.finish) {
            g_activation_damaged = 0; g_activation_diagnostic_context = NULL;
        }
    }
    PR_LOCK_EXCLUSIVE();
    current=g_current_provider; library=g_library_provider; map=g_map_provider;
    inventory=g_inventory; g_inventory=NULL;
    sh_virtual_material_runtime_restore(NULL);
    pr_publish(NULL,NULL,NULL);
    g_ready=g_usable=g_activating=g_native_preparing=g_native_prepare_seen=0;
    pr_release(g_occurrence_recovery_provider); g_occurrence_recovery_provider = NULL;
    g_occurrence_recovery_context = NULL;
    free(g_map_json);g_map_json=NULL;g_map_length=0;
    g_departure_deferred = 0;
    pr_dormant_free(&g_dormant);
    pr_release(g_reading_view); g_reading_view = NULL; g_reading_thread = 0;
    sh_package_references_free(&g_map_references);
    sh_package_policy_free(&g_map_policy);
    PR_UNLOCK_EXCLUSIVE();
    pr_release(current);pr_release(library);pr_release(map);pr_inventory_release(inventory);
    pr_departed_map_release(NULL);
    sh_package_provenance_free(&g_promoted);
    pr_collect_leases();
    sh_package_link_history_close(g_link_history); g_link_history = NULL;
    sh_package_source_memo_close(g_source_memo); g_source_memo = NULL;
    InterlockedExchange(&g_maps_swept, 0); /* the next start sweeps its own data root */
    pr_refresh_release(1);
}
#endif
